window.SDG4_GRADES = {"1": [{"ch": 0, "q": "What is Goal 4 about?", "options": ["A good school for everyone", "Fast cars", "Big cities", "Sports only"], "answer": 0, "explain": "Goal 4 is called Quality Education. It wants every child to learn at a good school.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "How many goals does the world have?", "options": ["5", "17", "10", "50"], "answer": 1, "explain": "The world has 17 Sustainable Development Goals. Goal 4 is about education.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Who agreed on the goals?", "options": ["One teacher", "Only children", "Countries of the world, together", "A big company"], "answer": 2, "explain": "All UN member countries agreed on the goals together. The UN is a group of countries.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Can every child go to school?", "options": ["Yes, every child can", "Only in cities", "Only in summer", "No, millions of children cannot"], "answer": 3, "explain": "Millions of children and young people cannot go to school. Goal 4 wants every child to have a place.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Why can some children not go to school?", "options": ["They live far away or their family is poor", "They are too tall", "School is always closed", "They do not like to learn"], "answer": 0, "explain": "Long walks, costs and poverty stop some children from going to school. Goal 4 wants to remove these barriers.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What should every child have?", "options": ["A car", "A place in a good school near home", "A phone", "A house in the sky"], "answer": 1, "explain": "Every child should have a place in a good school, close to home.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "What does it mean to finish school?", "options": ["To leave on the first day", "To skip every class", "To go through all the grades and learn", "To never come back"], "answer": 2, "explain": "Finishing school means going all the way through the grades. Many children leave before the end.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Why is it good for children to finish school?", "options": ["It makes them tired", "It is not important", "It stops their learning", "It helps them learn and get work later"], "answer": 3, "explain": "Finishing school gives children more skills and more chances in life.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Do most children finish school in every country?", "options": ["No, many leave early", "Yes, all of them do", "No one goes to school", "Only girls finish"], "answer": 0, "explain": "Many children do not finish school, so Goal 4 wants more children to stay until the end.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What do children learn to do at school?", "options": ["Only sleep", "Read, write and count", "Only play games", "Nothing useful"], "answer": 1, "explain": "At school children learn to read, write and count. These skills help them all their lives.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Is it enough for children just to attend school?", "options": ["Yes, attending is enough", "Only teachers need to learn", "No, they must really learn", "It does not matter"], "answer": 2, "explain": "Being in school is not enough. Children must actually learn useful things.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What helps children learn to read?", "options": ["Loud music only", "Watching TV all day", "Staying at home", "Books and a good teacher"], "answer": 3, "explain": "Books, a good teacher and practice help children learn to read.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What are skills?", "options": ["Things you can do well, like drawing or counting", "Places where you go to play with friends after school", "Rules your teacher writes on the board each morning", "Shops that sell sweets and toys near your home"], "answer": 0, "explain": "Skills are things we learn to do well. Goal 4 wants young people to learn skills for work and life.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Why do young people need skills?", "options": ["To stop going to school", "To get jobs and help their community", "To be bored", "They do not need them"], "answer": 1, "explain": "Skills help young people find work and help their families and communities.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Which of these is a useful skill?", "options": ["Breaking things", "Hiding from friends", "Using a computer safely", "Ignoring the rules"], "answer": 2, "explain": "Learning computer and other useful skills helps young people in work and life.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Should girls and boys have the same chance to go to school?", "options": ["No, only boys", "No, only girls", "Only in some countries", "Yes, both should"], "answer": 3, "explain": "Girls and boys should have the same chance to learn. Goal 4 wants to end unfair differences between them.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What does fair mean for schools?", "options": ["Everyone gets a chance to learn", "Only rich children learn", "Some children get nothing", "Only some children are welcome"], "answer": 0, "explain": "Fair means every child gets a chance to learn, whatever their family, home or background.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Who should be able to go to school?", "options": ["Only children with money", "Every child, whatever their family has", "Only children who live in cities", "No child"], "answer": 1, "explain": "Goal 4 says quality education must be for everyone, including children who are poor or live far away.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "What helps a school most?", "options": ["A big swimming pool", "Fancy cars in the car park", "Good, trained teachers", "Empty classrooms"], "answer": 2, "explain": "Good teachers help children learn. Goal 4 wants more trained teachers.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "What do teachers need to help children learn?", "options": ["No help at all", "To work with no pay", "To stay away from class", "Training and support"], "answer": 3, "explain": "Teachers need good training and support to help every child learn.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "Should primary and secondary school be free?", "options": ["Yes, Goal 4 wants free school", "No, school must cost a lot", "Only for boys", "Only in cities"], "answer": 0, "explain": "Goal 4 wants primary and secondary school to be free for everyone.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "Who helps make school possible for every child?", "options": ["Only parents with money", "Governments and communities", "Nobody", "Only the children"], "answer": 1, "explain": "Governments and communities help build schools and pay teachers, so every child can go.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "When did countries agree on the goals?", "options": ["1900", "1950", "2015", "2050"], "answer": 2, "explain": "Countries agreed on the goals in 2015. They set 2030 as the year to reach them.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "By which year should the goals be reached?", "options": ["2010", "1990", "2100", "2030"], "answer": 3, "explain": "Countries set 2030 as the year to reach the goals.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Why should small children go to preschool?", "options": ["To get ready for primary school", "Because it is a holiday", "To stop learning", "It is not useful"], "answer": 0, "explain": "Early learning helps young children get ready for primary school and grow.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "When does early learning happen?", "options": ["Only at age 15", "Before primary school", "Only at age 30", "Never"], "answer": 1, "explain": "Early childhood learning is for the years before primary school.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "What is literacy?", "options": ["Being able to swim", "Being able to draw", "Being able to read and write", "Being able to run fast"], "answer": 2, "explain": "Literacy means reading and writing. Goal 4 wants all young people to become literate.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "What is numeracy?", "options": ["Being able to sing", "Being able to cook", "Being able to paint", "Being able to count and do sums"], "answer": 3, "explain": "Numeracy means using numbers, like counting and adding.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Should children with disabilities go to school with other children?", "options": ["Yes, schools should welcome them", "No, they should stay at home", "Only on weekends", "Only in special places"], "answer": 0, "explain": "Goal 4 wants schools that welcome and include every child, including children with disabilities.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "What makes a school inclusive?", "options": ["Only some children are allowed", "Everyone is welcome and can learn", "Children are kept apart", "Nobody can come in"], "answer": 1, "explain": "An inclusive school welcomes every child, so everyone can learn together.", "src": "UN 2030 Agenda (2015)"}], "2": [{"ch": 0, "q": "Which number is Quality Education?", "options": ["4", "2", "9", "12"], "answer": 0, "explain": "Quality Education is Goal 4 of the 17 Global Goals.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Goal 4 is about which thing?", "options": ["Only sports", "Good learning for everyone", "Only holidays", "Only big cities"], "answer": 1, "explain": "Goal 4 wants every child and adult to get a good education.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "In what year did countries agree on the Global Goals?", "options": ["1945", "2001", "2015", "2040"], "answer": 2, "explain": "In 2015 world leaders agreed on 17 Global Goals to reach by 2030.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Why should children go to school?", "options": ["To sleep", "To be late", "To be alone", "To learn and grow"], "answer": 3, "explain": "School helps children learn to read, count and make friends.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "Should every child have the right to go to school?", "options": ["Yes", "No", "Only boys", "Only in cities"], "answer": 0, "explain": "Every child has the right to education.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "A child cannot reach school because it is too far away. This is a problem of:", "options": ["Colour", "Access", "Sleep", "Music"], "answer": 1, "explain": "Access means being able to reach a school and go in.", "src": "UNESCO"}, {"ch": 1, "q": "Which place helps children learn together?", "options": ["A shoe shop", "A car park", "A school", "A grocery shelf"], "answer": 2, "explain": "A school is a place where children learn together with teachers.", "src": "UNESCO"}, {"ch": 2, "q": "Why do parents want their children to finish school?", "options": ["It makes children dislike reading books at home", "It means school fees never have to be paid again", "It removes any need for learning after school", "Finishing school improves a child's future job and health"], "answer": 3, "explain": "Completing school is linked to better jobs, income and health later in life.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Why do some children leave school early?", "options": ["Money, distance or illness can stop them", "They do not like to learn", "School is too short", "They have too many books"], "answer": 0, "explain": "Many children leave early because of money, travel or illness.", "src": "UNESCO"}, {"ch": 2, "q": "Why is it good to stay in school?", "options": ["You get bored", "You learn more each year", "You lose friends", "You stop learning"], "answer": 1, "explain": "Each year at school helps you learn more and build skills.", "src": "UNESCO"}, {"ch": 2, "q": "Which of these helps students finish school?", "options": ["Missing every class", "Skipping meals", "Support from family and teachers", "Never asking questions"], "answer": 2, "explain": "Support from family and teachers helps students keep going.", "src": "UNESCO"}, {"ch": 3, "q": "What is reading?", "options": ["Eating words", "Drawing pictures only", "Running fast", "Understanding words on a page"], "answer": 3, "explain": "Reading means understanding the words and what they say.", "src": "UNESCO"}, {"ch": 3, "q": "Which skill helps you add 2 and 3?", "options": ["Counting", "Swimming", "Singing only", "Cooking"], "answer": 0, "explain": "Counting helps us work out how many things there are altogether.", "src": "UNESCO"}, {"ch": 3, "q": "Which activity helps young children build early reading skills?", "options": ["Watching many hours of television each day", "Reading stories aloud and talking about the pictures", "Copying long lists of random words in silence", "Reading only maths problems and never stories"], "answer": 1, "explain": "Shared reading and talk build vocabulary and early literacy.", "src": "UNESCO"}, {"ch": 3, "q": "What is a library?", "options": ["A place to sell cars", "A place with only toys", "A place with many books", "A place for swimming"], "answer": 2, "explain": "A library is a place where people can read and borrow books.", "src": "UNESCO"}, {"ch": 4, "q": "What is teamwork?", "options": ["Working alone always", "Winning every game alone", "Hiding from friends", "Working together with others"], "answer": 3, "explain": "Teamwork means working together to reach a goal.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Which skill helps you say how you feel?", "options": ["Communication", "Hopping", "Sleeping", "Painting walls"], "answer": 0, "explain": "Communication means saying your thoughts and listening to others.", "src": "UNESCO"}, {"ch": 4, "q": "What does it mean to be creative?", "options": ["Copying exactly", "Making new ideas or things", "Never trying", "Only using money"], "answer": 1, "explain": "Being creative means making something new, like a drawing or a story.", "src": "UNESCO"}, {"ch": 4, "q": "Which skill helps you solve a problem?", "options": ["Closing your eyes", "Running away", "Thinking carefully", "Ignoring it"], "answer": 2, "explain": "Thinking carefully helps us find solutions to problems.", "src": "UNESCO"}, {"ch": 5, "q": "Should girls and boys both go to school?", "options": ["Only boys", "Only girls", "Neither should", "Yes, both should"], "answer": 3, "explain": "Girls and boys should have equal chances to go to school.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What does equal mean in education?", "options": ["Everyone gets a fair chance", "Everyone wears the same shoes", "Some children have no teachers", "Only rich children learn"], "answer": 0, "explain": "Equal education means everyone has a fair chance to learn.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Which is a fair way to share books at school?", "options": ["Only the fastest child gets one", "Everyone gets a turn", "Only the teacher keeps them", "Only the tallest child"], "answer": 1, "explain": "Sharing fairly means every child gets a chance to use the books.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Which children have the right to go to school?", "options": ["Only children whose parents pay the highest fees", "Only boys who live in the capital city", "Every child, no matter their family or background", "Only children who already read very well"], "answer": 2, "explain": "Every child has the right to education, regardless of background.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 6, "q": "What does a teacher do?", "options": ["Sells food only", "Drives buses only", "Cleans the sky", "Helps children learn"], "answer": 3, "explain": "Teachers help children learn new things and grow.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why do schools need good teachers?", "options": ["Teachers help children learn well", "Teachers stop all learning", "Teachers only give homework", "Teachers are not needed"], "answer": 0, "explain": "Good teachers help children learn and feel safe at school.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What helps teachers become better at teaching?", "options": ["Less pay for everyone", "Training and support", "Closing all schools", "Ignoring the children"], "answer": 1, "explain": "Training helps teachers learn new ways to teach.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What can a good teacher show children?", "options": ["How to be cruel", "How to be lazy", "How to be kind and curious", "How to hide"], "answer": 2, "explain": "Good teachers help children be kind, curious and brave.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "What do schools need to work well?", "options": ["Only computers", "Only loud music", "Only a swimming pool", "Books, desks and teachers"], "answer": 3, "explain": "Schools need many things, including books, desks and teachers.", "src": "UNESCO"}, {"ch": 7, "q": "What helps keep children safe and healthy at school?", "options": ["Clean water and toilets", "Big cars", "No roof", "Loud speakers only"], "answer": 0, "explain": "Clean water and toilets help children stay healthy at school.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "Why do some schools have no books?", "options": ["Books are not needed", "They do not have enough money", "Children do not read", "Books are too heavy"], "answer": 1, "explain": "Money is needed to buy books and other school things.", "src": "UNESCO"}, {"ch": 7, "q": "Why do schools need money?", "options": ["To buy cars only", "To pay for holidays only", "To buy things for learning", "Schools do not need money"], "answer": 2, "explain": "Money pays for books, teachers, desks and other school things.", "src": "UNESCO"}, {"ch": 8, "q": "Which document says everyone has the right to education?", "options": ["A cookbook with recipes for family meals", "A map of the moon's craters and seas", "A school timetable for the whole term", "The Universal Declaration of Human Rights"], "answer": 3, "explain": "The Universal Declaration of Human Rights says everyone has the right to education.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "In which year was the Universal Declaration of Human Rights agreed?", "options": ["1948", "1900", "1975", "2030"], "answer": 0, "explain": "It was agreed in 1948 by the United Nations General Assembly.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Which organisation was set up to help countries work together for peace and learning?", "options": ["The Circus", "The United Nations", "The Sports Club", "The Car Company"], "answer": 1, "explain": "The United Nations was formed after the Second World War to help countries work together.", "src": "United Nations"}, {"ch": 9, "q": "What is a good way for young children to learn?", "options": ["Sitting still all day", "Staying silent", "Playing and talking", "Working at night"], "answer": 2, "explain": "Young children learn a lot through play and talking with adults.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What helps babies learn?", "options": ["Keeping them in the dark", "Never holding them", "Giving them only sweets", "Talking and singing to them"], "answer": 3, "explain": "Talking, singing and playing with babies help them learn language.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What helps a child grow well before school?", "options": ["Love and care from adults", "Being left alone", "Too many sweets", "No sleep"], "answer": 0, "explain": "Love, care and play in early years help children grow strong and ready to learn.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "What does literacy mean?", "options": ["Being able to dance", "Being able to read and write", "Being able to swim", "Being able to draw only"], "answer": 1, "explain": "Literacy means being able to read and write.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Which letter comes after A in the alphabet?", "options": ["Z", "D", "B", "Q"], "answer": 2, "explain": "B comes after A in the alphabet.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Which of these helps people get better at reading?", "options": ["Never opening a book", "Only watching videos", "Forgetting the letters", "Reading a little every day"], "answer": 3, "explain": "Reading a little every day helps people get better at reading.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "What does inclusion in school mean?", "options": ["Everyone is welcome and can learn", "Only some children can join", "Children must all be the same", "Children must stay home"], "answer": 0, "explain": "Inclusion means every child can learn at school, including children with disabilities.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Should children with disabilities be able to go to school?", "options": ["No", "Yes", "Only on Sundays", "Only if they have no friends"], "answer": 1, "explain": "Children with disabilities have the right to go to school with others.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What helps a child who uses a wheelchair learn at school?", "options": ["A school with no doors", "A school with stairs only", "A school with ramps", "A school far away"], "answer": 2, "explain": "Ramps and step-free rooms help children who use wheelchairs get around school.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is a kind way to treat a classmate who is different?", "options": ["Leave them out", "Call them names", "Ignore them", "Include them in play"], "answer": 3, "explain": "Including classmates helps everyone feel welcome.", "src": "UN CRPD (2006), Article 24"}, {"ch": 0, "q": "By which year are the Global Goals meant to be reached?", "options": ["2030", "1990", "2000", "2060"], "answer": 0, "explain": "The Global Goals are set to be reached by 2030.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "What helps children get to school safely?", "options": ["Closed roads", "Safe roads and paths", "Crossing busy roads alone", "Staying at home"], "answer": 1, "explain": "Safe roads and paths help children reach school safely.", "src": "UNESCO"}, {"ch": 2, "q": "What is a good reason to keep going when school is hard?", "options": ["Nobody will notice", "School never helps", "You can learn and reach your goals", "Learning is useless"], "answer": 2, "explain": "Keeping going helps you reach your goals and learn new things.", "src": "UNESCO"}, {"ch": 8, "q": "What does the abbreviation UN stand for?", "options": ["United Nurses", "Unique Notes", "Under Name", "United Nations"], "answer": 3, "explain": "UN stands for United Nations.", "src": "United Nations"}, {"ch": 9, "q": "Why is playing good for young children?", "options": ["It helps them learn and grow", "It wastes time", "It only makes them tired", "It is not allowed"], "answer": 0, "explain": "Play builds thinking, language and social skills.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "What is the first letter of the alphabet?", "options": ["Z", "A", "M", "K"], "answer": 1, "explain": "A is the first letter of the English alphabet.", "src": "UNESCO, International Literacy Day"}], "3": [{"ch": 0, "q": "What does SDG stand for?", "options": ["Sustainable Development Goals", "Super Dog Games", "Simple Desk Guide", "Sweet Dinner Group"], "answer": 0, "explain": "SDG stands for Sustainable Development Goals.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "How many Global Goals are there?", "options": ["7", "17", "12", "27"], "answer": 1, "explain": "There are 17 Global Goals, and Goal 4 is about education.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Which word best describes Goal 4?", "options": ["Speed", "Silence", "Quality", "Price"], "answer": 2, "explain": "Goal 4 is called Quality Education.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Which Goal number is clean water and sanitation?", "options": ["2", "9", "15", "6"], "answer": 3, "explain": "Goal 6 is Clean Water and Sanitation.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What is a target in the Global Goals?", "options": ["A specific aim to reach", "A type of paper", "A kind of sport", "A type of food"], "answer": 0, "explain": "Each goal has targets that say exactly what to achieve.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "What is a barrier that can stop a girl from going to school?", "options": ["Too many books", "A long walk on an unsafe road", "Too much sunshine", "Too many teachers"], "answer": 1, "explain": "Distance and unsafe roads can stop children from reaching school.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "What does it mean if a school is free to attend?", "options": ["Children must pay to join", "Children must bring money to each lesson", "Children do not pay fees to join", "Children can only come on weekends"], "answer": 2, "explain": "Free school means children do not have to pay fees to attend.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Which right says every child should be able to go to school?", "options": ["The right to a car", "The right to a holiday", "The right to a sports team", "The right to education"], "answer": 3, "explain": "The right to education means every child can go to school.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "What is a remote area?", "options": ["A place far from towns and cities", "A place with no sky", "A place under the sea", "A place with no people at all"], "answer": 0, "explain": "Remote areas are far from towns, so children may find school hard to reach.", "src": "UNESCO"}, {"ch": 2, "q": "What is a dropout?", "options": ["A student who finishes early", "A student who leaves school before finishing", "A teacher who leaves", "A student who reads fast"], "answer": 1, "explain": "A dropout leaves school before completing it.", "src": "UNESCO"}, {"ch": 2, "q": "Why is it important that children complete primary school?", "options": ["It means no more learning ever", "It is only for fun", "It gives them basic reading, writing and maths", "It removes the need for homework"], "answer": 2, "explain": "Completing primary school builds basic skills for life.", "src": "UNESCO"}, {"ch": 2, "q": "What can help students stay in school?", "options": ["Missing lessons", "Leaving early", "Ignoring teachers", "Mentoring and support"], "answer": 3, "explain": "Mentors and support help students stay in school and keep learning.", "src": "UNESCO"}, {"ch": 2, "q": "What is attendance?", "options": ["Being present at school", "Winning a prize", "Writing a letter", "Buying books"], "answer": 0, "explain": "Attendance means being at school for lessons.", "src": "UNESCO"}, {"ch": 2, "q": "What should a school do when a child is absent for many days?", "options": ["Forget about them", "Find out why and help them return", "Remove them from the list for no reason", "Ask them to pay a fine"], "answer": 1, "explain": "Schools can support families to help children come back.", "src": "UNESCO"}, {"ch": 3, "q": "Which skill is numeracy mainly about?", "options": ["Painting pictures with bright colours and brushes", "Singing songs about animals and the seasons", "Using numbers and basic maths in everyday life", "Memorising the names of countries in the world"], "answer": 2, "explain": "Numeracy means using numbers confidently in daily life.", "src": "UNESCO"}, {"ch": 3, "q": "What is a good way to check your learning?", "options": ["Never trying again", "Copying without thinking", "Sleeping through lessons", "Asking questions and practising"], "answer": 3, "explain": "Practising and asking questions help you understand new things.", "src": "UNESCO"}, {"ch": 3, "q": "What is a learning outcome?", "options": ["What a learner can do after learning", "The price of the school", "The weather on test day", "The number of desks"], "answer": 0, "explain": "A learning outcome is the skill or knowledge a learner gains.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "What is a test used for?", "options": ["Deciding the weather", "Checking what someone has learned", "Making the sun rise", "Choosing the lunch menu"], "answer": 1, "explain": "Tests help teachers and learners see what has been learned.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "What is reading comprehension?", "options": ["Reading very fast", "Reading with a loud voice", "Understanding what you read", "Reading only pictures"], "answer": 2, "explain": "Reading comprehension means understanding the meaning of a text.", "src": "UNESCO"}, {"ch": 4, "q": "Which skill helps you work well with people from other places?", "options": ["Ignoring others", "Shouting at others", "Hiding from others", "Respect for others"], "answer": 3, "explain": "Respect helps people from different backgrounds work and learn together.", "src": "UNESCO"}, {"ch": 4, "q": "What is critical thinking?", "options": ["Checking whether an idea makes sense", "Believing every idea at once", "Never asking questions", "Forgetting what you read"], "answer": 0, "explain": "Critical thinking means asking questions and checking facts.", "src": "UNESCO"}, {"ch": 4, "q": "Which skill can help you get a job one day?", "options": ["Sleeping for long hours during the school day", "Practical skills like computing or repairing", "Avoiding all lessons and practice at home", "Refusing to learn anything new at all"], "answer": 1, "explain": "Practical and job skills help people work and support themselves.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Which skill helps a team make a decision?", "options": ["Shouting the loudest", "Ignoring the team", "Listening to each person", "Leaving the room"], "answer": 2, "explain": "Listening to everyone helps a team choose well.", "src": "UNESCO"}, {"ch": 4, "q": "What is a digital skill?", "options": ["Using only pencils", "Breaking computers", "Never using the internet", "Using computers and the internet safely"], "answer": 3, "explain": "Digital skills help people use technology safely and well.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What does equity in education mean?", "options": ["Fair support so every child can learn", "Every child gets exactly the same", "Only the best students get help", "Schools do not need to help"], "answer": 0, "explain": "Equity means giving each child the support they need to learn.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Which group of children is often left out of school?", "options": ["Children who enjoy playing football at lunch", "Children from poor families or remote areas", "Children who like to sing in the school choir", "Children who always sit near the front row"], "answer": 1, "explain": "Children from poor families and remote areas are more likely to be out of school.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "What is a gender gap in schools?", "options": ["A gap in the playground where children play", "A short break between two lessons each day", "A difference between girls and boys in school", "A hole in a school wall that needs repair"], "answer": 2, "explain": "A gender gap is a difference between girls and boys in schooling or learning.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Why should schools welcome children of every language and background?", "options": ["Only one language should be spoken", "Only one background should be allowed", "Children should be sent away", "Everyone deserves a fair chance to learn"], "answer": 3, "explain": "Education should include all children fairly, whatever their background.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Which group of learners may need extra help to stay safe at school?", "options": ["Vulnerable children", "Children who are always happy", "Children who can fly", "Children who never miss a lesson"], "answer": 0, "explain": "Vulnerable children may be at more risk of being left out or harmed, so they need extra help.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "What is a teacher shortage?", "options": ["Too many teachers for the children", "Not enough trained teachers for the children", "Teachers who never work", "Teachers with too many holidays"], "answer": 1, "explain": "A shortage means there are not enough trained teachers.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What helps a new teacher do well?", "options": ["No support at all", "Being sent to a different country", "Mentoring and training", "Long unpaid breaks"], "answer": 2, "explain": "Mentoring and training help new teachers grow.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why do teachers' working conditions matter?", "options": ["They have no effect", "They only matter for teachers' cars", "They matter only in cities", "They affect how well children learn"], "answer": 3, "explain": "Good conditions help teachers stay and teach well.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What do teachers need to plan a lesson?", "options": ["Clear goals and a good plan", "No idea about the subject", "A broken chair", "A holiday"], "answer": 0, "explain": "Clear goals and a plan help teachers teach well.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What do teachers need to keep learning?", "options": ["No more learning ever", "Ongoing training", "Only holidays", "Only money"], "answer": 1, "explain": "Teachers keep learning through ongoing training.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "What is a school fee?", "options": ["A prize for good grades", "A gift from the teacher", "Money paid to attend a school", "A fine for being late"], "answer": 2, "explain": "A school fee is money families sometimes pay to attend school.", "src": "UNESCO"}, {"ch": 7, "q": "Why do governments spend money on schools?", "options": ["To buy more holidays only", "To build more roads only", "To reduce school days", "To help children learn and grow"], "answer": 3, "explain": "Public money pays for teachers, buildings and books so children can learn.", "src": "UNESCO"}, {"ch": 7, "q": "What does a classroom need to be a safe place to learn?", "options": ["Good lighting, fresh air and a sound roof", "No windows at all, so the room stays dark", "Loud noise from the street all through class", "Broken chairs and a leaking roof each week"], "answer": 0, "explain": "Good buildings help children learn in comfort and safety.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "What can happen if a school has no money for books?", "options": ["Children learn more quickly", "Children have fewer chances to learn", "Children stop needing school", "Children get extra holidays"], "answer": 1, "explain": "Without books, children may find it harder to learn.", "src": "UNESCO"}, {"ch": 8, "q": "In which year was the UN Convention on the Rights of the Child agreed?", "options": ["1948", "1990", "1989", "2015"], "answer": 2, "explain": "It was agreed in 1989 by the UN General Assembly.", "src": "UN Convention on the Rights of the Child, 1989"}, {"ch": 8, "q": "What were the Millennium Development Goals?", "options": ["A set of goals from 1900", "A set of goals for the moon", "A set of goals for sport", "A set of goals from 2000 to 2015"], "answer": 3, "explain": "The MDGs ran from 2000 to 2015, before the Global Goals.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "Which meeting in 1990 focused on Education for All?", "options": ["The World Conference on Education for All in Jomtien", "An international trade fair held in New York that year", "A global film festival held in Cannes that summer", "A world summit about football rules in Brazil"], "answer": 0, "explain": "Countries met in Jomtien, Thailand, in 1990 to commit to education for all.", "src": "UNESCO"}, {"ch": 8, "q": "Which day celebrates teachers each year?", "options": ["1 January", "World Teachers' Day, 5 October", "25 December", "8 September"], "answer": 1, "explain": "UNESCO celebrates World Teachers' Day on 5 October each year.", "src": "UNESCO"}, {"ch": 9, "q": "What is early childhood?", "options": ["Only the teenage years", "Only university years", "The years from birth to about age eight", "Only the last year of school"], "answer": 2, "explain": "Early childhood usually means the years from birth to about age eight.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Why does early learning matter?", "options": ["Early years do not matter", "Only later years matter", "Early learning only helps sport", "Early experiences shape how the brain grows"], "answer": 3, "explain": "Early experiences shape how the brain grows and learns.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Which is a good early learning activity?", "options": ["Reading picture books together", "Watching TV all day", "Being left alone for hours", "Eating only sweets"], "answer": 0, "explain": "Reading together builds language and early learning.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is play-based learning?", "options": ["Learning by sitting still", "Learning through playing", "Learning by copying only", "Learning by never asking"], "answer": 1, "explain": "Play-based learning helps young children learn by doing.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "When is International Literacy Day?", "options": ["1 January", "25 December", "8 September", "30 April"], "answer": 2, "explain": "UNESCO marks International Literacy Day every year on 8 September.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "What helps adults learn to read?", "options": ["Being forced to stop reading", "Sleeping more", "Avoiding books", "Adult literacy classes"], "answer": 3, "explain": "Adult literacy classes help adults learn reading and writing.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Why do some people struggle to read?", "options": ["They did not get a chance to learn", "Reading is illegal", "Books are poisonous", "Letters are too big"], "answer": 0, "explain": "Many people miss out on learning to read when they do not get a chance at school.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "When is International Mother Language Day?", "options": ["1 May", "21 February", "31 October", "14 July"], "answer": 1, "explain": "UNESCO marks International Mother Language Day on 21 February.", "src": "UNESCO, International Mother Language Day"}, {"ch": 11, "q": "What should a school do for children with disabilities?", "options": ["Keep them apart from others", "Refuse to let them in", "Include them and give support", "Send them home"], "answer": 2, "explain": "Inclusive schools welcome children with disabilities and give them support.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is a reasonable accommodation at school?", "options": ["A way to avoid teaching", "A special bus to the city", "A type of exam fee", "An adjustment that helps a child take part"], "answer": 3, "explain": "A reasonable accommodation is an adjustment that helps a child take part in school.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Which of these is an example of inclusion?", "options": ["Braille books in the library", "A school with no entrance", "Teachers who ignore all students", "A room only some children may enter"], "answer": 0, "explain": "Braille books help children who are blind read in class.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What does inclusive mean?", "options": ["Keeping some people out", "Welcoming everyone", "Welcoming only one group", "Making people leave"], "answer": 1, "explain": "Inclusive means welcoming everyone and making space for each person.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is a school place?", "options": ["A seat in a car", "A place to sleep", "A seat for a child at school", "A shop for books"], "answer": 2, "explain": "A school place is a seat for a child to learn.", "src": "UNESCO"}], "4": [{"ch": 0, "q": "What does Goal 4 aim for?", "options": ["Quality and lifelong learning for all", "Only sport for children", "Only jobs for adults", "Less school for everyone"], "answer": 0, "explain": "Goal 4 aims for inclusive, quality and lifelong learning for all.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "How many targets does Goal 4 have?", "options": ["5", "10", "17", "169"], "answer": 1, "explain": "Goal 4 has 10 targets: seven outcome targets and three means of implementation.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "How many targets are there across all 17 Global Goals?", "options": ["17", "50", "169", "300"], "answer": 2, "explain": "The 17 Global Goals have 169 targets in total.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Which Goal is about no poverty?", "options": ["Goal 4", "Goal 9", "Goal 12", "Goal 1"], "answer": 3, "explain": "Goal 1 is No Poverty.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "What is a common reason a child in a village may not attend school?", "options": ["The school is too far away", "The school is too close", "There are too many buses", "There are too many friends"], "answer": 0, "explain": "Long distances are a common barrier to school.", "src": "UNESCO"}, {"ch": 1, "q": "Why do some families keep children at home?", "options": ["They do not want education", "They need help with work or money", "School is illegal", "They have too many cars"], "answer": 1, "explain": "Some families need children to help earn money or work at home.", "src": "UNESCO"}, {"ch": 1, "q": "Which of these helps children in rural areas reach school?", "options": ["Closing the roads", "Crossing rivers alone without help", "School buses or safe paths", "Staying at home"], "answer": 2, "explain": "Transport and safe paths make it easier for rural children to attend.", "src": "UNESCO"}, {"ch": 1, "q": "What is pre-primary education?", "options": ["Learning after university", "Learning only at weekends", "Learning only in a workplace", "Learning before primary school"], "answer": 3, "explain": "Pre-primary education is learning for young children before primary school.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Why is a safe school building important?", "options": ["It protects children from harm", "It makes school longer", "It stops children learning", "It is only for decoration"], "answer": 0, "explain": "Safe buildings protect children and make learning possible.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "What is primary school?", "options": ["The last stage of university", "The first main stage of schooling", "Only for teachers", "A type of holiday camp"], "answer": 1, "explain": "Primary school is usually the first main stage of formal education.", "src": "UNESCO"}, {"ch": 2, "q": "What is secondary school?", "options": ["The stage before kindergarten", "A type of sports camp", "The stage after primary school", "A place only for adults"], "answer": 2, "explain": "Secondary school follows primary school.", "src": "UNESCO"}, {"ch": 2, "q": "Which factor often increases early school leaving?", "options": ["Good weather", "Too many books", "Winning prizes", "Poverty"], "answer": 3, "explain": "Poverty is one of the biggest reasons children leave school early.", "src": "UNESCO"}, {"ch": 2, "q": "What does completion rate mean?", "options": ["The share of children who finish a school level", "The share of teachers who sleep", "The number of school bells", "The price of school bags"], "answer": 0, "explain": "Completion rate is the share of children who finish a level of school.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "What helps children finish school?", "options": ["Closing schools early", "Help families with costs and transport", "Removing books", "Making exams longer every day"], "answer": 1, "explain": "Support with costs and transport helps children stay in school.", "src": "UNESCO"}, {"ch": 2, "q": "What can a school do to keep students attending?", "options": ["Ignore absent students and wait for them to return", "Give fewer lessons to students who miss school", "Track attendance and reach out to families", "Close the school early on every single Friday"], "answer": 2, "explain": "Schools can follow attendance and work with families to support students.", "src": "UNESCO"}, {"ch": 3, "q": "What does a good reading level mean?", "options": ["Reading only numbers", "Never reading out loud", "Reading faster than a car", "Reading and understanding text for your age"], "answer": 3, "explain": "A good reading level means understanding a simple text at your age.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Which subject is about numbers, patterns and shapes?", "options": ["Mathematics", "Music", "Drama", "Art history"], "answer": 0, "explain": "Mathematics is the subject about numbers, patterns and shapes.", "src": "UNESCO"}, {"ch": 3, "q": "What is a curriculum?", "options": ["A type of school uniform", "The set of subjects and what students learn", "A school car park", "A list of holidays"], "answer": 1, "explain": "The curriculum lists what students should learn in each subject.", "src": "UNESCO"}, {"ch": 3, "q": "Why is learning in your first language helpful?", "options": ["It is never helpful", "It means learning less", "Children understand lessons better", "It makes school shorter"], "answer": 2, "explain": "Children learn more easily when they understand the language used in class.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "What is a skill in education?", "options": ["Something you lose", "A type of food", "A school subject only", "Something a person can do well"], "answer": 3, "explain": "A skill is an ability you can practise and improve.", "src": "UNESCO"}, {"ch": 4, "q": "What does problem solving mean?", "options": ["Finding a way to fix a difficult question", "Ignoring problems", "Making problems bigger", "Waiting for others forever"], "answer": 0, "explain": "Problem solving means working out a way to answer or fix something.", "src": "UNESCO"}, {"ch": 4, "q": "Which skill helps you share your ideas clearly with a group?", "options": ["Hiding your voice", "Speaking clearly to a group", "Speaking very quietly", "Never speaking"], "answer": 1, "explain": "Presenting helps you share your ideas clearly with others.", "src": "UNESCO"}, {"ch": 4, "q": "What is leadership?", "options": ["Ordering others to be silent", "Taking all the credit", "Guiding others in a helpful way", "Avoiding responsibility"], "answer": 2, "explain": "Leadership is helping and guiding others towards a goal.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is digital literacy?", "options": ["Using technology to break things", "Never using a computer", "Writing letters only", "Using technology to find and share information"], "answer": 3, "explain": "Digital literacy means using digital tools safely to learn and communicate.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is a vocational skill?", "options": ["A practical job skill like carpentry", "A skill for sleeping", "A skill for avoiding work", "A skill for hiding"], "answer": 0, "explain": "Vocational skills are practical skills used in a job or trade.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What does gender equality in school mean?", "options": ["Only boys can learn", "Girls and boys have equal chances", "Only girls can learn", "Girls must stay at home"], "answer": 1, "explain": "Gender equality means girls and boys have equal rights and chances in education.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Which group does Goal 4 name for equal access?", "options": ["Only tall people", "Only city people", "Persons with disabilities", "Only people who like sport"], "answer": 2, "explain": "Goal 4 mentions persons with disabilities among groups who need equal access.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Why do girls sometimes miss school?", "options": ["Girls do not like learning", "School is too short", "Girls have too many books", "Early marriage, chores or unsafe travel"], "answer": 3, "explain": "Early marriage, household chores and unsafe travel can stop girls attending school.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What is a vulnerable group in education?", "options": ["Groups who face more barriers to learning", "Groups who never learn", "Groups who only read", "Groups who are very rich"], "answer": 0, "explain": "Vulnerable groups face more obstacles, so they may need extra support.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What is an indigenous community?", "options": ["A type of school building", "The first people who lived in a place", "A kind of teacher", "A kind of school bag"], "answer": 1, "explain": "Indigenous peoples are the original people of a region, often with their own languages and cultures.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What is a girl-friendly school?", "options": ["A school for girls only in the city", "A school where girls are not allowed", "A school with safe toilets and no harassment", "A school that teaches only dancing"], "answer": 2, "explain": "Girl-friendly schools are safe, with good facilities and respectful teachers.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "Why do schools need enough teachers?", "options": ["Teachers are not needed", "So children can stop learning", "So school can finish early", "So every class has someone to teach"], "answer": 3, "explain": "Enough teachers mean every class can be taught well.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is a qualified teacher?", "options": ["A teacher who has been trained to teach", "A teacher who has no training", "A teacher who only tells jokes", "A teacher who never teaches"], "answer": 0, "explain": "Qualified teachers have the training needed for their job.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What can help teachers stay in their jobs?", "options": ["Long working hours with no break", "Fair pay and good conditions", "No support at all", "Being moved far away every day"], "answer": 1, "explain": "Fair pay and good conditions help teachers stay in the profession.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is a mentor teacher?", "options": ["A teacher who runs away", "A teacher who only sits", "An experienced teacher who helps a newer one", "A teacher who writes poetry only"], "answer": 2, "explain": "Mentors guide newer teachers and help them improve.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why do teachers need to understand their students?", "options": ["So they can give more homework", "So they can stop teaching", "So they can avoid parents", "To teach in ways that help each child"], "answer": 3, "explain": "Understanding students helps teachers plan lessons that work for them.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "What is a public school?", "options": ["A school paid for by government money", "A school that sells food only", "A school run only by one family", "A school with no students"], "answer": 0, "explain": "Public schools are funded mainly by public money.", "src": "UNESCO"}, {"ch": 7, "q": "What is an education budget?", "options": ["A list of holiday dates", "Money planned for education", "A game about money", "The price of a school uniform"], "answer": 1, "explain": "An education budget is the money a government plans to spend on schools.", "src": "UNESCO"}, {"ch": 7, "q": "What can happen when a school has too little money?", "options": ["More teachers appear", "Books become cheaper", "Fewer teachers and fewer books", "Schools become larger"], "answer": 2, "explain": "Limited money can mean fewer teachers and learning materials.", "src": "UNESCO"}, {"ch": 7, "q": "What costs can families still have even when tuition is free?", "options": ["Nothing at all", "Only air", "Only sunshine", "Uniforms, transport and supplies"], "answer": 3, "explain": "Families can pay for uniforms, transport and school supplies even when tuition is free.", "src": "UNESCO"}, {"ch": 7, "q": "What is a school grant?", "options": ["Money given to help a school or student", "A fine for late homework", "A type of exam", "A school bus ticket only"], "answer": 0, "explain": "A grant is money given to help a school or student, often without repayment.", "src": "UNESCO"}, {"ch": 8, "q": "In which year did the Millennium Development Goals begin?", "options": ["1948", "2000", "1990", "2015"], "answer": 1, "explain": "The Millennium Development Goals started in 2000.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "Where did countries meet in 1990 to start the Education for All movement?", "options": ["Paris, France", "Cairo, Egypt", "Jomtien, Thailand", "Tokyo, Japan"], "answer": 2, "explain": "Countries met in Jomtien, Thailand, in 1990 for Education for All.", "src": "UNESCO"}, {"ch": 8, "q": "Which framework set education goals at Dakar in 2000?", "options": ["The Dakar Football Rules", "The Dakar Road Map", "The Dakar Food Plan", "The Dakar Framework for Action"], "answer": 3, "explain": "The Dakar Framework for Action was agreed in 2000 at the World Education Forum.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Which document says primary education should be compulsory and free?", "options": ["The UN Convention on the Rights of the Child", "A school menu listing lunch options for the week", "A tourist guide to the best beaches in Bali", "A sports rulebook for school football matches"], "answer": 0, "explain": "Article 28 says primary education should be compulsory and free for all.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "What is the name of the 2015 education agreement?", "options": ["The Tokyo Declaration", "The Incheon Declaration", "The Cairo Pact", "The Lima Plan"], "answer": 1, "explain": "The Incheon Declaration in 2015 set the education goals for 2030.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 9, "q": "How do young children often learn?", "options": ["Through long exams", "Through hours of silence", "Through play, songs and stories", "Through night shifts"], "answer": 2, "explain": "Early learning often happens through play, songs and stories.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Why are the first years of life important for the brain?", "options": ["The brain stops growing", "The brain does not change", "The brain only grows at night", "The brain grows very quickly"], "answer": 3, "explain": "The brain develops very fast in the early years.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What does early childhood care include?", "options": ["Health, nutrition and learning", "Only sleep", "Only sports", "Only money"], "answer": 0, "explain": "Early childhood care supports health, food and learning together.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "What is a nursery?", "options": ["A place for growing trees only", "A place where very young children are cared for", "A place for sending mail", "A place for building cars"], "answer": 1, "explain": "Nurseries care for very young children and help them learn.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Which activity helps a toddler learn words?", "options": ["Keeping quiet all day", "Only watching adverts", "Naming objects and talking with them", "Being kept in a dark room"], "answer": 2, "explain": "Talking and naming things helps toddlers build language.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "What is a literacy rate?", "options": ["The price of books", "The number of libraries", "The number of teachers", "The share of people who can read and write"], "answer": 3, "explain": "The literacy rate shows the share of people who can read and write.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Why do adults need literacy?", "options": ["To read job instructions and health information", "To avoid doing any work at all in the factory", "To win every game in the school competition", "To stop learning new things after leaving school"], "answer": 0, "explain": "Reading helps adults work, stay healthy and take part in life.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "What is a reading corner in a classroom?", "options": ["A place to store shoes", "A space with books for reading", "A place only for eating lunch", "A place for storing bikes"], "answer": 1, "explain": "Reading corners give children a place to read and enjoy books.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "What helps a child who is struggling to read?", "options": ["Less time reading", "Being told they are not clever", "Extra reading help and practice", "Never being given books"], "answer": 2, "explain": "Extra help and practice can help children catch up.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "What does inclusive education mean?", "options": ["Education only for the best students", "Education only for one group", "Education with no teachers", "Education that welcomes all learners"], "answer": 3, "explain": "Inclusive education welcomes all learners and supports them.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Why should schools have ramps and accessible toilets?", "options": ["So everyone can use the school", "So children can run faster", "So schools look taller", "So classes are shorter"], "answer": 0, "explain": "Accessible buildings let everyone use school facilities.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is sign language used for in schools?", "options": ["Only for dance", "Communicating with deaf students", "Only for cooking", "Only for maths tests"], "answer": 1, "explain": "Sign language helps deaf students communicate and learn.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Who benefits from an inclusive school?", "options": ["Only teachers", "Only parents", "Everyone in the school", "Only the head teacher"], "answer": 2, "explain": "Inclusive schools help every child learn and grow together.", "src": "UN CRPD (2006), Article 24"}, {"ch": 3, "q": "What is a lesson plan?", "options": ["A plan for family holidays during the summer break", "A list of snacks sold in the school canteen", "A map showing the rooms and corridors of a school", "A plan that shows what will be taught and how"], "answer": 3, "explain": "A lesson plan sets out the goals and steps for a lesson.", "src": "UNESCO Global Report on Teachers (2024)"}], "5": [{"ch": 0, "q": "How many outcome targets are there under Goal 4?", "options": ["Seven", "Three", "Ten", "Seventeen"], "answer": 0, "explain": "Goal 4 has seven outcome targets, numbered 4.1 to 4.7.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What are the three 'means of implementation' targets for Goal 4 called?", "options": ["4.1, 4.2 and 4.3", "4.a, 4.b and 4.c", "4.5, 4.6 and 4.7", "4.8, 4.9 and 4.10"], "answer": 1, "explain": "Targets 4.a, 4.b and 4.c cover facilities, scholarships and teachers.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Which Global Goal is Gender Equality?", "options": ["Goal 2", "Goal 8", "Goal 5", "Goal 11"], "answer": 2, "explain": "Goal 5 is Gender Equality.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What does it mean to leave no one behind?", "options": ["Leaving the slowest people out", "Only helping rich countries", "Ending all help", "Including the people who are most left out"], "answer": 3, "explain": "The 2030 Agenda promises to reach the furthest behind first.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Why are the Global Goals called global?", "options": ["They apply to all countries", "They are only for one country", "They are only for schools", "They are only for sport"], "answer": 0, "explain": "The Global Goals apply to every country, rich and poor.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What is the target year for the Global Goals?", "options": ["2015", "2030", "2050", "2100"], "answer": 1, "explain": "The Global Goals aim to be reached by 2030.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Which group is most likely to be out of school in many countries?", "options": ["Children who love reading", "Children who play football", "Children in conflict areas", "Children who visit libraries"], "answer": 2, "explain": "Children in conflict and crisis areas often find it hardest to attend school.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What does out-of-school mean?", "options": ["Learning in a library", "Going to school on Sundays", "Winning a school prize", "Not enrolled in any school"], "answer": 3, "explain": "Out-of-school children are those who are not enrolled in any school.", "src": "UNESCO"}, {"ch": 1, "q": "Why do many children work instead of going to school?", "options": ["Families need their income", "They prefer working", "School is free", "Work is taught in school"], "answer": 0, "explain": "Families who are poor may need children to work to earn money.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What is child labour?", "options": ["Any quiet play at home with friends after school hours", "Work that harms children's health or stops their schooling", "Helping a parent with homework and simple chores at home", "Reading stories aloud to a younger brother or sister"], "answer": 1, "explain": "Child labour is work that harms children and stops them learning.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What is a school feeding programme?", "options": ["Food sold at shops", "A type of school sport", "Meals given to children at school", "A food festival"], "answer": 2, "explain": "School meals can encourage children to attend and learn.", "src": "UNESCO"}, {"ch": 1, "q": "Why can school meals help children?", "options": ["They stop learning", "They take all the money", "They replace books", "They encourage children to attend"], "answer": 3, "explain": "Meals can make it easier for children to come to school and concentrate.", "src": "UNESCO"}, {"ch": 2, "q": "What is a transition from primary to secondary school?", "options": ["Moving from one school level to the next", "Moving house only", "Changing seats in the same class", "Leaving school forever"], "answer": 0, "explain": "Transition means moving from one stage of school to the next.", "src": "UNESCO"}, {"ch": 2, "q": "Why do some children repeat a school year?", "options": ["Repeating is always a holiday", "They need more time to learn the work", "Repeating is a prize", "They have too many friends"], "answer": 1, "explain": "Some children repeat a year when they need more time to learn.", "src": "UNESCO"}, {"ch": 2, "q": "What does graduate mean?", "options": ["Start a new school", "Move to a new country", "Finish a level of education", "Stop attending classes"], "answer": 2, "explain": "To graduate means to complete a level of study successfully.", "src": "UNESCO"}, {"ch": 2, "q": "What is the goal of completing secondary school?", "options": ["Only to get a holiday", "Only to skip exams", "Only to stop reading", "Skills for work and further study"], "answer": 3, "explain": "Secondary education builds skills for work and further study.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "What does retention mean in schools?", "options": ["Keeping students in school until they finish", "Keeping students in a box", "Keeping books forever", "Keeping the school closed"], "answer": 0, "explain": "Retention means students stay in school until they complete the level.", "src": "UNESCO"}, {"ch": 2, "q": "Which factor helps students stay in school?", "options": ["Being forced to leave school", "A safe route to school", "Having no books", "Missing every test"], "answer": 1, "explain": "Safe routes make it easier for children to stay in school.", "src": "UNESCO"}, {"ch": 3, "q": "What does learning assessment mean?", "options": ["Measuring school buildings", "Counting desks", "Measuring what students have learned", "Counting teachers' cars"], "answer": 2, "explain": "Learning assessments check what students know and can do.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is learning poverty?", "options": ["Having no pencil or notebook for class work", "Having no computer at home to do homework", "Living far away from the nearest library building", "Not being able to read a simple text by age ten"], "answer": 3, "explain": "Learning poverty means a child cannot read and understand a simple text by age ten.", "src": "World Bank, learning poverty"}, {"ch": 3, "q": "What is a foundational skill?", "options": ["A basic skill like reading or counting", "A difficult university subject", "A type of sport", "A type of music"], "answer": 0, "explain": "Foundational skills such as reading and counting support all later learning.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Why is early reading important?", "options": ["It only helps in art", "It supports learning in every subject", "It is not needed in school", "It only helps in sport"], "answer": 1, "explain": "Children who read well can learn more easily in every subject.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is formative assessment?", "options": ["A final exam only", "A test of how tall a student is", "Checking learning during lessons", "A test of cooking skills"], "answer": 2, "explain": "Formative assessment helps teachers check progress and adjust lessons.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is summative assessment?", "options": ["A question asked only at the start", "A game with no marks", "A test given every morning", "A test at the end of a unit or year"], "answer": 3, "explain": "Summative assessment measures learning at the end of a period.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "What is creativity in learning?", "options": ["Coming up with new and useful ideas", "Copying exactly", "Only using old ideas", "Avoiding all ideas"], "answer": 0, "explain": "Creativity means finding new and useful ways of thinking and doing.", "src": "UNESCO"}, {"ch": 4, "q": "Which skill helps you work with people from different cultures?", "options": ["Hiding from differences", "Intercultural understanding", "Refusing to talk", "Ignoring other languages"], "answer": 1, "explain": "Intercultural understanding helps people respect and work with others.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is resilience?", "options": ["Giving up at the first challenge", "Never facing problems", "Bouncing back after difficulty", "Avoiding all new things"], "answer": 2, "explain": "Resilience means recovering and learning from difficult moments.", "src": "UNESCO"}, {"ch": 4, "q": "Why are life skills taught in some schools?", "options": ["To replace all maths lessons with art classes", "To make the school day longer for everyone", "To remove all exams from the school year", "To help students deal with daily challenges"], "answer": 3, "explain": "Life skills help students make good decisions and handle everyday problems.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is financial literacy?", "options": ["Understanding money and how to manage it", "Collecting coins for fun only", "Ignoring prices", "Spending all money at once"], "answer": 0, "explain": "Financial literacy means knowing how to use and save money wisely.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Which skill helps you use information from many sources?", "options": ["Singing", "Research skills", "Juggling", "Gardening only"], "answer": 1, "explain": "Research skills help students find and check information.", "src": "UNESCO"}, {"ch": 5, "q": "What is the gender parity index?", "options": ["A measure of school height", "A count of teachers' pets", "A number comparing girls' and boys' enrolment", "A list of school colours"], "answer": 2, "explain": "A parity index near 1 means girls and boys are enrolled equally.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What does a parity index of 1 mean?", "options": ["No girls are in school", "Only girls are in school", "There are twice as many boys", "Equal numbers of girls and boys"], "answer": 3, "explain": "A value of 1 shows girls and boys are enrolled in equal numbers.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Which group may face extra barriers because of a disability?", "options": ["Children with disabilities", "Children who like drawing", "Children who play games", "Children who wear glasses"], "answer": 0, "explain": "Children with disabilities may face extra barriers without support.", "src": "UN CRPD (2006), Article 24"}, {"ch": 5, "q": "What is discrimination in schools?", "options": ["Fair treatment for everyone", "Unfair treatment because of who someone is", "Choosing books by colour", "Giving the same homework to all"], "answer": 1, "explain": "Discrimination is unfair treatment based on a person's group or background.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Why should schools be free from violence?", "options": ["Violence helps children focus", "Violence is a normal part of school", "Violence stops children learning", "Violence makes children stronger"], "answer": 2, "explain": "Children cannot learn well when they feel unsafe.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What do inclusive policies do?", "options": ["Close schools for some groups", "Make schools only for the rich", "Remove all teachers", "Make education open to all groups"], "answer": 3, "explain": "Inclusive policies help all groups access and benefit from education.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "What is the teacher-to-pupil ratio?", "options": ["How many pupils each teacher has", "How many teachers are paid", "How many desks are in a room", "How many schools a teacher visits"], "answer": 0, "explain": "A teacher-to-pupil ratio shows how many learners share one teacher.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why does a low teacher-to-pupil ratio matter?", "options": ["Teachers have nothing to do", "Teachers can give more attention to each child", "It means classes are noisier", "It makes teachers richer"], "answer": 1, "explain": "Smaller classes let teachers help each child more.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is teacher motivation?", "options": ["Being paid to sleep", "Working as little as possible", "The drive and enthusiasm to teach well", "Avoiding students"], "answer": 2, "explain": "Motivated teachers are more likely to stay and teach well.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why is teacher training important?", "options": ["It replaces lessons", "It removes the need for students", "It only adds holidays", "It improves the quality of teaching"], "answer": 3, "explain": "Good training helps teachers teach in effective ways.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is a teacher education college?", "options": ["A place where teachers are trained", "A place to sell teaching materials only", "A school for pets", "A place for building roads"], "answer": 0, "explain": "Teacher education colleges prepare people to become teachers.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What can support teachers in rural areas?", "options": ["No support at all", "Housing, transport and training", "Being moved every day", "Less pay and more work"], "answer": 1, "explain": "Support like housing and transport helps teachers serve rural communities.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "What is public spending on education?", "options": ["Money families spend on toys", "Money spent on sport only", "Money governments spend on schools", "Money spent on roads only"], "answer": 2, "explain": "Public spending on education is the money governments use to run schools.", "src": "UNESCO"}, {"ch": 7, "q": "What is a school voucher?", "options": ["A type of school uniform", "A ticket to a museum", "A bus route map", "A form of help that pays for school"], "answer": 3, "explain": "Vouchers can help families pay for school costs in some countries.", "src": "UNESCO"}, {"ch": 7, "q": "Which cost can keep poor children out of school?", "options": ["Fees and uniforms", "Free books", "Free meals", "Free transport"], "answer": 0, "explain": "Fees and uniforms can be too expensive for some families.", "src": "UNESCO"}, {"ch": 7, "q": "What does free education usually mean?", "options": ["Free holidays", "No tuition fees", "Free cars", "Free sweets"], "answer": 1, "explain": "Free education usually means there are no tuition fees, though other costs may apply.", "src": "UNESCO"}, {"ch": 8, "q": "In which year was Education for All agreed at Jomtien?", "options": ["1948", "1989", "1990", "2000"], "answer": 2, "explain": "Education for All was agreed at Jomtien in 1990.", "src": "UNESCO"}, {"ch": 8, "q": "What did the Dakar Framework in 2000 aim for?", "options": ["Education only for adults", "No schools at all", "Education only in cities", "Education for All by 2015"], "answer": 3, "explain": "The Dakar Framework set goals to achieve Education for All by 2015.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Which Millennium Development Goal was about universal primary education?", "options": ["Goal 2", "Goal 1", "Goal 5", "Goal 8"], "answer": 0, "explain": "MDG 2 aimed for universal primary education.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "What is the World Education Forum?", "options": ["A football match between two national teams in Asia", "A gathering of countries and partners about education", "A cooking competition for students and families", "A film festival for young directors and actors"], "answer": 1, "explain": "The World Education Forum brings together countries and partners to discuss education.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "What framework supports the Incheon Declaration?", "options": ["The Sports 2030 Framework", "The Cooking 2030 Plan", "The Education 2030 Framework for Action", "The Music 2030 Plan"], "answer": 2, "explain": "The Education 2030 Framework for Action guides countries to reach SDG 4.", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "What year did the Millennium Development Goals end?", "options": ["2000", "2030", "2010", "2015"], "answer": 3, "explain": "The MDGs ended in 2015 and were followed by the Global Goals.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "What is early childhood development?", "options": ["Growth in health, learning and wellbeing from birth", "Growth in height and weight only, year after year", "Learning only at university after many years", "Playing only outdoors in the open air each day"], "answer": 0, "explain": "Early childhood development covers health, learning and wellbeing from birth.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is serve and return in early childhood?", "options": ["A type of tennis game played on grass courts in summer", "Back-and-forth interaction between a child and an adult", "A way of returning toys to the local charity shop", "A type of long sleep that babies have each afternoon"], "answer": 1, "explain": "Serve and return is the back-and-forth interaction that builds the brain.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Why do young children need responsive adults?", "options": ["Adults are not needed", "Adults only give orders", "They learn language and emotions from them", "Adults should stay silent"], "answer": 2, "explain": "Responsive adults help children build language, feelings and thinking skills.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Which SDG 4 target is about early childhood?", "options": ["Target 4.1", "Target 4.6", "Target 4.c", "Target 4.2"], "answer": 3, "explain": "Target 4.2 is about early childhood development, care and pre-primary education.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "What is pre-primary education for?", "options": ["Preparing young children for primary school", "Preparing them for university", "Replacing primary school", "Making children work"], "answer": 0, "explain": "Pre-primary education gives young children skills before primary school.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "Why is nutrition important in early childhood?", "options": ["Food does not affect the brain", "Good food supports healthy brain growth", "Children need only sweets", "Children should eat once a week"], "answer": 1, "explain": "Healthy food supports the brain and body during fast growth.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "What is functional literacy?", "options": ["Reading only magazines and comics for fun", "Writing only poems and songs for school shows", "Reading and writing well enough for daily life", "Reading only numbers printed on bills and tickets"], "answer": 2, "explain": "Functional literacy means reading and writing enough to manage everyday tasks.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Which two basic skills are at the heart of Target 4.6?", "options": ["Singing and drawing", "Cooking and driving", "Walking and running", "Literacy and numeracy"], "answer": 3, "explain": "Target 4.6 is about youth and adults achieving literacy and numeracy.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "Why do libraries help literacy?", "options": ["They give free access to books", "They sell expensive books only", "They are closed to children", "They only store furniture"], "answer": 0, "explain": "Libraries give people free access to books and reading places.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "What is reading fluency?", "options": ["Reading with no understanding", "Reading smoothly and accurately", "Reading backwards", "Reading only in silence"], "answer": 1, "explain": "Fluency means reading smoothly, accurately and with expression.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "What is a resource room in a school?", "options": ["A room that stores old furniture only", "A room that sells school uniforms", "A room that gives extra help to students who need it", "A room that holds sports trophies"], "answer": 2, "explain": "A resource room gives extra support to students with learning or disability needs.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What does universal design mean for schools?", "options": ["Only one kind of building for a city", "Buildings with no doors", "Buildings for animals only", "Buildings and tools that work for everyone"], "answer": 3, "explain": "Universal design makes buildings and tools usable by as many people as possible.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Why do children with disabilities sometimes need assistive devices?", "options": ["They help children hear, see or move", "They make children sleep", "They replace teachers", "They stop children learning"], "answer": 0, "explain": "Assistive devices such as hearing aids or wheelchairs help children take part in school.", "src": "UN CRPD (2006), Article 24"}], "6": [{"ch": 0, "q": "Which SDG 4 target is about free, equitable and quality primary and secondary education?", "options": ["Target 4.1", "Target 4.2", "Target 4.4", "Target 4.7"], "answer": 0, "explain": "Target 4.1 aims for free, equitable and quality primary and secondary education.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Which target mentions technical and vocational skills for employment?", "options": ["Target 4.1", "Target 4.4", "Target 4.5", "Target 4.b"], "answer": 1, "explain": "Target 4.4 focuses on skills, including technical and vocational skills, for jobs.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Which target is about scholarships for students in developing countries?", "options": ["Target 4.a", "Target 4.c", "Target 4.b", "Target 4.6"], "answer": 2, "explain": "Target 4.b calls for more scholarships for students from developing countries.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Which target is about the supply of qualified teachers?", "options": ["Target 4.b", "Target 4.2", "Target 4.7", "Target 4.c"], "answer": 3, "explain": "Target 4.c aims to increase the supply of qualified teachers.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Which target is about building and upgrading education facilities?", "options": ["Target 4.a", "Target 4.1", "Target 4.3", "Target 4.5"], "answer": 0, "explain": "Target 4.a calls for safe, inclusive and effective learning facilities.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What is Target 4.7 about?", "options": ["Only sports, games and physical fitness for the whole school year", "Knowledge and skills for sustainable development and global citizenship", "Only money, banking and business accounts for grown-up adults", "Only cooking, food and nutrition for the school dining hall"], "answer": 1, "explain": "Target 4.7 covers sustainable development, human rights, gender equality and global citizenship.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Which target focuses on early childhood development and pre-primary education?", "options": ["Target 4.1", "Target 4.6", "Target 4.2", "Target 4.c"], "answer": 2, "explain": "Target 4.2 is about early childhood development, care and pre-primary education.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "What does equitable mean in Target 4.1?", "options": ["Only for the richest families in the country", "Only for those living in the big cities", "Only for adults who have finished their schooling", "Fair for all, including the most disadvantaged"], "answer": 3, "explain": "Equitable education reaches everyone fairly, including people who are disadvantaged.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Which group is named in Target 4.5 as needing equal access?", "options": ["Indigenous peoples", "Only people with money", "Only people in big cities", "Only people who speak one language"], "answer": 0, "explain": "Target 4.5 names persons with disabilities, indigenous peoples and children in vulnerable situations.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "Why is free primary education important?", "options": ["It increases school fees", "It removes a major barrier for poor families", "It stops children learning", "It makes schools less useful"], "answer": 1, "explain": "Free primary education helps families who cannot afford fees.", "src": "UNESCO"}, {"ch": 1, "q": "What does universal primary education mean?", "options": ["Only some children attend primary school", "Only adults attend primary school", "Every child can attend primary school", "Primary school is optional for everyone"], "answer": 2, "explain": "Universal primary education means every child has a place in primary school.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 1, "q": "Which children may still be out of school even when fees are removed?", "options": ["Children who are very tall", "Children who like reading", "Children who never eat meals", "Children with disabilities or in remote areas"], "answer": 3, "explain": "Costs are not the only barrier; disability, distance and discrimination also keep children out.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "What is the purpose of tracking completion rates?", "options": ["To see if children are finishing school", "To choose the best holiday places for school trips", "To sell more school books in the local shops", "To measure the size of desks in each classroom"], "answer": 0, "explain": "Completion rates show whether children reach the end of each level.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Why do secondary school completion rates matter?", "options": ["They show how many teachers sleep", "They show progress toward Target 4.1", "They show the price of school bags", "They show the weather"], "answer": 1, "explain": "Completion rates help track progress towards Goal 4.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "What is second chance education?", "options": ["Learning only after finishing a university degree", "Learning only through sports and games on the field", "Learning opportunities for people who missed school", "Learning that is banned in most countries today"], "answer": 2, "explain": "Second chance education helps people catch up on learning they missed.", "src": "UNESCO"}, {"ch": 2, "q": "What is a bridging programme?", "options": ["A programme for building bridges over rivers and roads", "A programme that closes schools in remote villages each year", "A programme for weekend sports and games for everyone", "A programme that helps learners move between levels or systems"], "answer": 3, "explain": "Bridging programmes help learners move smoothly between schools and training.", "src": "UNESCO"}, {"ch": 2, "q": "Why do students drop out in lower secondary school?", "options": ["Costs, work and distance", "They finish too quickly", "They get too many prizes", "They have no homework"], "answer": 0, "explain": "Costs, work and distance are common reasons students leave school early.", "src": "UNESCO"}, {"ch": 2, "q": "What can help a student return to school after leaving?", "options": ["Permanent exclusion", "A flexible programme and support", "Being forced to repeat the same year", "Punishment from teachers"], "answer": 1, "explain": "Flexible programmes and support help students return to learning.", "src": "UNESCO"}, {"ch": 3, "q": "What kind of learning does Target 4.1 aim for?", "options": ["Only good handwriting", "Only high marks in sport", "Relevant and effective learning", "Only faster reading"], "answer": 2, "explain": "Target 4.1 aims for relevant and effective learning outcomes, not just attendance.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "Why is measuring learning harder than counting attendance?", "options": ["Learning is always easy to count", "Attendance can never be counted", "Learning is measured only by height", "Learning must be assessed, not just counted"], "answer": 3, "explain": "Attendance shows presence, but learning needs assessment of skills and understanding.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is a minimum proficiency level?", "options": ["The lowest level a learner should reach", "The highest level of learning", "A level for teachers only", "A level for school buildings"], "answer": 0, "explain": "Minimum proficiency is the basic skill level all learners should reach.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Why do many countries test reading and maths?", "options": ["To choose lunch", "To see if learners reach basic skills", "To check the weather", "To decide holidays"], "answer": 1, "explain": "Testing shows whether learners reach essential basic skills.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is learning equity?", "options": ["Only the best students learn", "Everyone gets identical support whatever their needs", "Every learner gets a fair chance to learn well", "Learning only happens in some schools"], "answer": 2, "explain": "Equity in learning means giving more support where it is needed.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What skill links letters to sounds to help children read?", "options": ["Juggling", "Painting", "Dancing only", "Phonics"], "answer": 3, "explain": "Phonics links letters to sounds and helps children read.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "What is computational thinking?", "options": ["Breaking a problem into steps to solve it", "Using a calculator for everything", "Guessing answers", "Avoiding puzzles"], "answer": 0, "explain": "Computational thinking breaks problems into steps, a useful skill in coding and beyond.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is entrepreneurship education?", "options": ["Learning to sleep well and rest during the day", "Learning to start and run a business or idea", "Learning to avoid work and stay at home", "Learning to sing songs in a choir every week"], "answer": 1, "explain": "Entrepreneurship education helps learners create and manage their own ideas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is global citizenship?", "options": ["Only living in one town", "Refusing to learn about other countries", "Understanding and caring about the wider world", "Ignoring other people"], "answer": 2, "explain": "Global citizenship encourages people to understand and respect the wider world.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Which skill helps a person judge whether news is true?", "options": ["Juggling", "Gardening", "Cooking", "Media literacy"], "answer": 3, "explain": "Media literacy helps people check information from different sources.", "src": "UNESCO"}, {"ch": 4, "q": "What is collaboration in learning?", "options": ["Working together to reach a shared goal", "Working alone to beat others", "Copying from classmates", "Avoiding group tasks"], "answer": 0, "explain": "Collaboration means learners work together and share responsibility.", "src": "UNESCO"}, {"ch": 4, "q": "What does culture of peace in Target 4.7 mean?", "options": ["Living apart from others", "Living together without violence", "Winning every argument", "Ignoring other cultures"], "answer": 1, "explain": "A culture of peace promotes non-violence, respect and understanding.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Which factor can keep girls out of secondary school?", "options": ["Good weather", "Free books", "Early marriage and household duties", "Too many teachers"], "answer": 2, "explain": "Early marriage and household duties can stop girls from completing secondary school.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What is disaggregated data?", "options": ["Data that is kept secret from the public forever", "Data that is never used to make any decisions", "Data about the weather in the region each day", "Data split by group, such as gender or disability"], "answer": 3, "explain": "Disaggregated data helps reveal who is left behind.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Why is disaggregated data useful?", "options": ["It shows which groups need help", "It hides problems", "It is never accurate", "It only helps companies"], "answer": 0, "explain": "Splitting data by group shows where support is needed.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What is school-related gender-based violence?", "options": ["A sports rule about how players may tackle", "Violence linked to gender in or around schools", "A type of exam taken at the end of the year", "A school holiday that lasts for two whole weeks"], "answer": 1, "explain": "This violence is linked to gender and harms children's learning.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What can schools do to protect children from violence?", "options": ["Ignore complaints from students and their parents", "Punish the children who report problems to staff", "Create safe reporting systems and train staff", "Close the school whenever a complaint is made"], "answer": 2, "explain": "Safe reporting systems and staff training help protect children.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What is a safe learning environment?", "options": ["A place with no teachers", "A place with no rules at all", "A place where students are always alone", "A place where students feel safe to learn"], "answer": 3, "explain": "Safe learning environments let students learn without fear.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Why is it important to pay teachers fairly?", "options": ["It helps keep qualified teachers in schools", "It makes schools poorer", "It reduces learning", "It stops teachers caring"], "answer": 0, "explain": "Fair pay helps keep trained teachers in schools.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is teacher attrition?", "options": ["Teachers getting promoted", "Teachers leaving the profession", "Teachers taking holidays", "Teachers winning awards"], "answer": 1, "explain": "Attrition means teachers leave the profession, which harms learning.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is a teacher career pathway?", "options": ["A path to the school gate only", "A path for students only", "A route for growth and promotion", "A path with no pay"], "answer": 2, "explain": "Career pathways give teachers ways to develop and move forward.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is continuing professional development for teachers?", "options": ["One day of training ever", "No training after graduating", "Training only for principals", "Ongoing training during a teaching career"], "answer": 3, "explain": "Continuing development keeps teachers skilled throughout their careers.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why does teacher quality matter?", "options": ["It is one of the key factors in how well children learn", "It has no effect at all on how children learn", "It matters only for sports and physical education", "It matters only for the look of the school building"], "answer": 0, "explain": "Teacher quality is one of the key factors in how well children learn.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why do remote areas often struggle to keep teachers?", "options": ["Remote areas have too many teachers", "Too few teachers want to work there", "Teachers prefer holidays", "Teachers never travel"], "answer": 1, "explain": "Remote areas often struggle to attract and keep enough teachers.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "What is domestic financing for education?", "options": ["Money from the moon", "Money from sports clubs only", "Money a country raises itself for schools", "Money from school uniforms only"], "answer": 2, "explain": "Domestic financing means money a country raises from its own taxes and income.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "What share of GDP does the Incheon Framework suggest for education?", "options": ["0.5 to 1 per cent", "20 to 30 per cent", "50 to 60 per cent", "4 to 6 per cent"], "answer": 3, "explain": "The Incheon Framework suggests 4 to 6 per cent of GDP and/or 15 to 20 per cent of public spending.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "What share of public spending does the Incheon Framework suggest for education?", "options": ["15 to 20 per cent", "1 to 2 per cent", "40 to 50 per cent", "90 to 100 per cent"], "answer": 0, "explain": "Incheon suggests 15 to 20 per cent of total public expenditure on education.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "What is a financing gap in education?", "options": ["Money saved up for family holidays and summer trips", "The difference between money needed and money available", "A distance between two school buildings in the city", "Money that has no real use in any school today"], "answer": 1, "explain": "A financing gap is the amount still needed to fund education goals.", "src": "UNESCO"}, {"ch": 7, "q": "Why do schools in poor areas often have less money?", "options": ["They have too many students", "They choose not to take money", "Less tax income and unequal funding", "They do not need books"], "answer": 2, "explain": "Unequal funding can leave poorer areas with fewer resources.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "What is capitation funding?", "options": ["Money given for each teacher's car", "Money given for each school bus", "Money given for each sports trophy", "Money given to schools for each student"], "answer": 3, "explain": "Capitation funding pays schools based on the number of students.", "src": "UNESCO"}, {"ch": 8, "q": "Which goals replaced the Millennium Development Goals?", "options": ["The Sustainable Development Goals", "The Olympic Goals", "The Trade Goals", "The Space Goals"], "answer": 0, "explain": "The SDGs (Global Goals) replaced the MDGs in 2015.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "In which year was the Education 2030 Framework for Action adopted?", "options": ["1990", "2015", "2000", "2030"], "answer": 1, "explain": "The Education 2030 Framework for Action was adopted in 2015.", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "What did the 1948 declaration say about education?", "options": ["Schools should be closed", "Education is only for adults", "Everyone has the right to education", "Education is a luxury"], "answer": 2, "explain": "The Universal Declaration of Human Rights says education is a human right.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "What does Article 26 of the Universal Declaration say about primary education?", "options": ["It should be expensive", "It should be optional for all", "It should be only for boys", "It should be free and compulsory"], "answer": 3, "explain": "Article 26 says elementary education should be compulsory and free.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "What happened at the 2015 World Education Forum in Incheon?", "options": ["Countries agreed education goals for 2030", "Countries closed all schools", "Countries agreed on a new sport", "Countries ended literacy programmes"], "answer": 0, "explain": "The Incheon Declaration set the education goals for 2030.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "What did the Jomtien conference of 1990 call for?", "options": ["Education only for the rich", "Education for all", "Education only in English", "Schools without teachers"], "answer": 1, "explain": "The Jomtien conference of 1990 called for education for all.", "src": "UNESCO"}, {"ch": 9, "q": "Why is early childhood care linked to later learning?", "options": ["Early years have no link", "Only adult learning matters", "Early skills support later school success", "Later learning is unrelated"], "answer": 2, "explain": "Strong early foundations make later learning easier.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is school readiness?", "options": ["Being ready to leave school", "Being tall enough for desks", "Being able to drive", "Being ready to learn at the start of school"], "answer": 3, "explain": "School readiness means children have the skills and health to start school.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is the role of play in early learning?", "options": ["It builds thinking, language and social skills", "It has no role", "It replaces all learning forever", "It only wastes time"], "answer": 0, "explain": "Play helps children build thinking, language and social skills.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Why do babies need responsive care?", "options": ["It spoils them", "It helps their brains and emotions develop", "It is not needed", "It only makes them sleep"], "answer": 1, "explain": "Responsive care supports healthy brain and emotional development.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What are the first thousand days?", "options": ["The first day at school", "The first week of holidays", "The period from pregnancy to age two", "The first year at university"], "answer": 2, "explain": "The first thousand days, from pregnancy to age two, are very important for development.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Which early childhood activity supports brain growth?", "options": ["Total silence", "Constant screen time only", "Being left alone for hours", "Talking and reading with children"], "answer": 3, "explain": "Talking and reading with children support language and brain growth.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "What is post-literacy?", "options": ["Learning that builds on basic literacy", "Reading only comics", "Literacy only for teachers", "Reading only magazines"], "answer": 0, "explain": "Post-literacy helps people keep and build on basic reading and writing skills.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "What is literacy for all?", "options": ["Literacy only for children", "Literacy opportunities for everyone", "Literacy only for rich people", "Literacy only in one language"], "answer": 1, "explain": "Literacy for all aims to give everyone the chance to read and write.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Why are multilingual literacy programmes useful?", "options": ["They prevent learning a second language", "They remove the need for books", "They help learners read in their own language first", "They only work in sport"], "answer": 2, "explain": "Learning to read in a language a child understands supports later learning.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "What is the link between literacy and health?", "options": ["Reading makes people sick", "There is no link", "Health only depends on sport", "Reading helps people understand health advice"], "answer": 3, "explain": "Literacy helps people read medicine labels and health guidance.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "What does a literacy campaign aim to do?", "options": ["Teach reading and writing to many people", "Sell more newspapers to busy families each week", "Stop people from reading books and magazines", "Build more roads and bridges across the country"], "answer": 0, "explain": "A literacy campaign works to reduce illiteracy across communities.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Which skill is basic to literacy?", "options": ["Juggling balls", "Recognising letters and sounds", "Driving a bus", "Cooking rice"], "answer": 1, "explain": "Recognising letters and their sounds is a basic literacy skill.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "What does Target 4.5 ensure for vulnerable groups?", "options": ["Access only for the best students", "Access only for rich families", "Equal access to education", "Access only in big cities"], "answer": 2, "explain": "Target 4.5 ensures equal access for vulnerable groups.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "What is an individual education plan for a student?", "options": ["A plan for holidays", "A plan to avoid class", "A plan to move students to another school", "A plan tailored to a learner's needs"], "answer": 3, "explain": "Individual education plans help teachers meet a student's specific needs.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What does reasonable accommodation require from schools?", "options": ["Adjustments that help learners take part", "Ignoring learners' needs", "Charging extra fees", "Removing all support"], "answer": 0, "explain": "Schools must make reasonable adjustments so learners with disabilities can take part.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Why are accessible materials important?", "options": ["They make learning harder for everyone", "They let all learners use the same content", "They are only for teachers", "They replace teachers"], "answer": 1, "explain": "Accessible materials such as large print or braille help learners access lessons.", "src": "UN CRPD (2006), Article 24"}], "7": [{"ch": 0, "q": "Which Global Goal is about climate action?", "options": ["Goal 13", "Goal 3", "Goal 14", "Goal 10"], "answer": 0, "explain": "Goal 13 is Climate Action.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Which target is about eliminating gender disparities in education?", "options": ["Target 4.1", "Target 4.5", "Target 4.4", "Target 4.a"], "answer": 1, "explain": "Target 4.5 aims to eliminate gender disparities and ensure equal access.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Why is measuring learning outcomes important?", "options": ["It only counts how many school buildings exist in town", "It sets the price of school books in every shop", "It shows what children actually learn, not just enrolment", "It measures the height and weight of every pupil"], "answer": 2, "explain": "Monitoring learning outcomes shows whether children are really learning.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "What is the purpose of the SDG 4 indicators?", "options": ["To choose school colours", "To rank teachers by height", "To set holiday dates", "To measure progress on each target"], "answer": 3, "explain": "Indicators measure progress toward each target.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Why is Goal 4 linked to other Global Goals?", "options": ["Education supports health, jobs and equality", "Education has no links to other goals", "Education only matters for sport", "Education is only for cities"], "answer": 0, "explain": "Education supports progress across many goals, such as health, work and gender equality.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Which target aims for literacy and numeracy for youth and adults?", "options": ["Target 4.1", "Target 4.6", "Target 4.5", "Target 4.c"], "answer": 1, "explain": "Target 4.6 aims for literacy and numeracy for all youth and a substantial share of adults.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What does indicator 4.1.1 track?", "options": ["The number of school buses running on each main road", "The average price of school uniforms in each town", "Children reaching minimum proficiency in reading and maths", "The average height of each classroom in the school"], "answer": 2, "explain": "Indicator 4.1.1 tracks the share of children reaching minimum proficiency levels.", "src": "UN SDG Report 2026"}, {"ch": 1, "q": "What is the digital divide?", "options": ["A gap between two classrooms in the same large school building", "A break between two long lessons on a busy school day", "A divide between two languages that are spoken at home only", "The gap between people who have internet access and those who do not"], "answer": 3, "explain": "The digital divide is the gap in access to devices and the internet.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Why can distance education help some learners?", "options": ["It reaches learners in remote areas", "It replaces all teachers", "It stops learning", "It is only for adults"], "answer": 0, "explain": "Distance and online learning can reach people who live far from schools.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What is a learning centre in a remote community?", "options": ["A shopping centre with many shops and cafes", "A space where learners can study with support", "A hospital ward where patients rest and recover", "A sports stadium used for big football matches"], "answer": 1, "explain": "Learning centres give remote learners a place to study and get help.", "src": "UNESCO"}, {"ch": 1, "q": "What is school mapping?", "options": ["Drawing maps of holiday routes for family trips abroad", "Mapping the sports fields used for school matches", "Finding where schools are needed and who can reach them", "Designing new logos and posters for every school"], "answer": 2, "explain": "School mapping helps governments plan where new schools and transport are needed.", "src": "UNESCO"}, {"ch": 1, "q": "What is a common barrier to school in cities?", "options": ["Too much green space", "Too many libraries", "Too many teachers", "High living costs for poor families"], "answer": 3, "explain": "In cities, poor families may struggle with transport and living costs.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What does access mean for learners with disabilities?", "options": ["Being able to enter and use school facilities", "Being able to leave school at any time", "Being able to skip lessons", "Being able to avoid tests"], "answer": 0, "explain": "Access means disabled learners can enter and use school spaces and learning materials.", "src": "UN CRPD (2006), Article 24"}, {"ch": 2, "q": "What is a completion gap?", "options": ["A gap in a school wall that needs urgent repair", "A difference in finishing school between groups", "A space between two desks in a crowded classroom", "A gap in the school timetable every Friday afternoon"], "answer": 1, "explain": "A completion gap shows that some groups finish school less often than others.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Why do children from higher-income families often complete school more?", "options": ["Their children are less intelligent", "Their children never take tests", "Their families can cover costs and transport", "Their children avoid homework"], "answer": 2, "explain": "Income helps families cover costs and transport, making completion more likely.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "What does a survival rate to the last grade measure?", "options": ["The share who win races", "The share who own bikes", "The share who speak two languages", "The share of children who reach the last grade"], "answer": 3, "explain": "Survival rate measures how many students reach the final grade of a level.", "src": "UNESCO"}, {"ch": 2, "q": "Why does early marriage affect school completion?", "options": ["It can end a girl's schooling", "It improves school attendance", "It has no effect at all", "It only affects boys"], "answer": 0, "explain": "Early marriage often ends girls' education before they complete school.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 2, "q": "What is re-entry into school?", "options": ["Entering a school for the first time", "Returning to school after leaving", "Leaving school forever", "Changing the school uniform"], "answer": 1, "explain": "Re-entry policies help young people return to school after dropping out.", "src": "UNESCO"}, {"ch": 2, "q": "What is the school-to-work transition?", "options": ["Moving school buildings", "Changing teachers", "Moving from school into employment or training", "Moving to a new country only"], "answer": 2, "explain": "The school-to-work transition is the move from education into jobs or training.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "What is learning loss?", "options": ["Losing a pencil case on the bus each morning", "Forgetting a password for the school computer", "Losing a football match against a rival school", "Losing skills after a long break in learning"], "answer": 3, "explain": "Learning loss means skills fade after schools close or learning is interrupted.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What helps students recover from learning loss?", "options": ["Targeted tutoring and catch-up classes", "Less teaching", "Removing all tests", "Longer holidays only"], "answer": 0, "explain": "Targeted support helps learners catch up on what they missed.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is mastery learning?", "options": ["Learners never repeat a topic", "Learners move on only after understanding a topic", "Learners skip all difficult topics", "Learners only memorise answers"], "answer": 1, "explain": "Mastery learning ensures learners understand before moving on.", "src": "UNESCO"}, {"ch": 3, "q": "Why is the language of instruction important?", "options": ["It has no effect", "Only one language should ever be used", "Learners understand lessons best in a language they know", "It only matters in sport"], "answer": 2, "explain": "Using a language learners understand supports learning.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "What is bilingual education?", "options": ["Teaching through games only", "Teaching in no language at all", "Teaching in one language for dance", "Teaching in two languages"], "answer": 3, "explain": "Bilingual education uses two languages to help learners understand and grow.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "What is critical reading?", "options": ["Questioning and evaluating a text", "Reading without thinking", "Reading only the title", "Reading only pictures"], "answer": 0, "explain": "Critical reading asks whether the text is accurate, fair and well argued.", "src": "UNESCO"}, {"ch": 4, "q": "What does ICT stand for in education?", "options": ["International Cooking Trust", "Information and communication technology", "Interesting Campus Tour", "Important Classroom Test"], "answer": 1, "explain": "ICT stands for information and communication technology.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is vocational education?", "options": ["Education with no practical skills or hands-on training", "Education only for those who are already working as teachers", "Education that prepares people for specific trades or jobs", "Education only for students who go on to university"], "answer": 2, "explain": "Vocational education builds practical skills for specific jobs.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What does TVET stand for?", "options": ["Teachers' video exam test", "Total visual education tool", "Tertiary video education theme", "Technical and vocational education and training"], "answer": 3, "explain": "TVET stands for technical and vocational education and training.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Why is coding taught in some schools?", "options": ["It builds problem-solving and digital skills", "It replaces all other subjects", "It is only for games", "It stops learning"], "answer": 0, "explain": "Coding teaches logic and digital skills useful in many jobs.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is digital citizenship?", "options": ["Using technology to harm others", "Using technology safely, responsibly and respectfully", "Avoiding all technology", "Using technology only to play games"], "answer": 1, "explain": "Digital citizenship means behaving well online and respecting others.", "src": "UNESCO"}, {"ch": 4, "q": "What is an emerging skill?", "options": ["A skill that is no longer needed", "A skill for ancient languages only", "A skill that becomes important in new jobs", "A skill for sleeping"], "answer": 2, "explain": "Emerging skills become important as new kinds of work develop.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What is the gender gap in STEM education?", "options": ["Girls study more maths than boys in almost every country today", "No gap of any kind exists in science classes anywhere", "Only boys are allowed to study science subjects at school", "Fewer girls than boys study science, technology, engineering and maths"], "answer": 3, "explain": "Many countries show fewer girls in STEM subjects, which limits their options.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Why can women teachers matter in some places?", "options": ["They can be role models and help girls stay in school", "They are not needed in any school anywhere in the world", "They only teach sport and outdoor physical activities", "They stop children from learning any new subjects at all"], "answer": 0, "explain": "Female teachers can encourage girls and help create safe environments.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What is a gender-responsive school?", "options": ["A school for girls only", "A school that meets the needs of girls and boys", "A school that ignores gender", "A school with no toilets"], "answer": 1, "explain": "Gender-responsive schools plan for the different needs of girls and boys.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What does marginalised mean?", "options": ["Placed in the centre of attention", "Given extra money automatically", "Pushed to the edge of society and left out", "Allowed to make all the rules"], "answer": 2, "explain": "Marginalised groups are often excluded from education and opportunities.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "Why are minority language speakers at risk of being left behind?", "options": ["They are always the best learners", "Their language is never spoken", "They never attend school", "Schools may not teach in their language"], "answer": 3, "explain": "When lessons use a language children do not speak, many fall behind.", "src": "UNESCO, International Mother Language Day"}, {"ch": 5, "q": "What is affirmative action in education?", "options": ["Extra support to groups who face disadvantage", "Punishing groups who do well", "Ignoring all differences", "Closing schools for some groups"], "answer": 0, "explain": "Affirmative action gives extra support to help disadvantaged groups catch up.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What does socio-economic status mean?", "options": ["A type of school exam", "A person's social and economic position", "The colour of a school bag", "A number of sports wins"], "answer": 1, "explain": "Socio-economic status describes a family's income, education and social position.", "src": "UNESCO GEM Report 2026"}, {"ch": 6, "q": "What is a teacher gap?", "options": ["Extra teachers who do nothing", "Teachers with no lessons", "The number of extra teachers needed to meet demand", "Teachers who never leave school"], "answer": 2, "explain": "A teacher gap is the number of additional teachers needed to reach education goals.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why is teacher supply a challenge in many countries?", "options": ["Too many people want to teach", "Teachers are never needed", "Teachers have too many students only", "Not enough people train or stay as teachers"], "answer": 3, "explain": "Shortages come from too few trainees, poor pay and high turnover.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is teacher status?", "options": ["How teachers are valued in society", "A teacher's height", "A teacher's car", "A teacher's school bag"], "answer": 0, "explain": "Teacher status affects whether people choose and stay in teaching.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is a teacher in a crisis area?", "options": ["A teacher who only works in cities", "A teacher who works where conflict or disaster has hit", "A teacher who never teaches", "A teacher who only works on holidays"], "answer": 1, "explain": "Teachers in crisis areas work under difficult conditions to keep children learning.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why do some teachers leave the profession?", "options": ["Too much pay and too many paid holidays", "Too little work and too many free days", "Low pay, heavy workloads or poor support", "Too many prizes and too much praise"], "answer": 2, "explain": "Low pay and heavy workloads push some teachers out of the profession.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is a teacher's workload?", "options": ["The weight of a teacher's bag", "The number of teacher holidays", "The price of a teacher's car", "The amount of work a teacher has to do"], "answer": 3, "explain": "Workload includes teaching, planning, marking and other duties.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "What is the learning poverty rate used for?", "options": ["Tracking children who cannot read by age ten", "Tracking school buildings", "Tracking the price of pens", "Tracking teacher holidays"], "answer": 0, "explain": "The learning poverty rate shows the share of children unable to read a simple text by age ten.", "src": "World Bank, learning poverty"}, {"ch": 7, "q": "Why is public spending on education important?", "options": ["It has no purpose", "It pays for teachers, buildings and materials", "It pays for holidays only", "It only buys sports equipment"], "answer": 1, "explain": "Public money keeps schools running and makes learning available to all.", "src": "UNESCO"}, {"ch": 7, "q": "What is budget execution in education?", "options": ["Cancelling all lessons", "Stopping all school trips", "Spending the money as planned", "Selling school buildings"], "answer": 2, "explain": "Budget execution checks whether planned education money is actually spent.", "src": "UNESCO"}, {"ch": 7, "q": "What is cost-sharing in education?", "options": ["Schools paying families", "Teachers paying students", "Students paying teachers", "Families paying part of the cost of school"], "answer": 3, "explain": "Cost-sharing means families contribute, which can limit access for poorer children.", "src": "UNESCO"}, {"ch": 7, "q": "What is an education tax?", "options": ["A tax used to fund schools", "A fee for taking exams only", "A tax on school books only", "A fine for missing school"], "answer": 0, "explain": "Some countries raise an education tax to fund schools.", "src": "UNESCO"}, {"ch": 7, "q": "Why do schools need regular repairs?", "options": ["New buildings always need repairs", "Old buildings can become unsafe", "Repairs make schools bigger", "Repairs stop children learning"], "answer": 1, "explain": "Regular repairs keep buildings safe and suitable for learning.", "src": "UNESCO"}, {"ch": 7, "q": "What is value for money in education spending?", "options": ["Spending as much money as possible each year", "Spending money only on sports equipment", "Getting good learning results for the money spent", "Spending none of the money at all each year"], "answer": 2, "explain": "Value for money means spending wisely to improve learning.", "src": "UNESCO"}, {"ch": 8, "q": "Which conference adopted the 2030 Agenda?", "options": ["A regional meeting held in Tokyo, 2005", "A meeting in Cairo on population, 1994", "A conference in Lima on farming, 2014", "The UN summit in New York, 2015"], "answer": 3, "explain": "World leaders adopted the 2030 Agenda at a UN summit in New York in 2015.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "When was the Jomtien World Conference on Education for All held?", "options": ["1990", "1975", "2005", "2020"], "answer": 0, "explain": "The Jomtien conference was held in 1990.", "src": "UNESCO"}, {"ch": 8, "q": "In which year did the Dakar World Education Forum take place?", "options": ["1995", "2000", "2010", "2015"], "answer": 1, "explain": "The Dakar World Education Forum took place in 2000.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "What did the 1990 Jomtien declaration focus on?", "options": ["Only university learning", "Only sports", "Meeting the basic learning needs of all", "Only exams"], "answer": 2, "explain": "The 1990 declaration focused on meeting the basic learning needs of all people.", "src": "UNESCO"}, {"ch": 8, "q": "What did the MDGs focus on in education?", "options": ["Free cars", "University scholarships only", "Sports leagues", "Universal primary education"], "answer": 3, "explain": "MDG 2 focused on universal primary education.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "What is the purpose of a global report on education?", "options": ["To track progress and share evidence", "To close schools", "To choose holidays", "To sell textbooks"], "answer": 0, "explain": "Global reports track progress and share evidence to guide policy.", "src": "UNESCO GEM Report 2026"}, {"ch": 9, "q": "What does child development cover in the early years?", "options": ["Growth only in size", "Growth of body, mind and social skills", "Growth only in money", "Growth only in speed"], "answer": 1, "explain": "Child development covers physical, thinking, language and social growth.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is toxic stress in early childhood?", "options": ["A type of healthy food eaten by growing children daily", "A fun game that children often play in the park", "Strong, long-lasting stress that can harm development", "A school subject taught to children in early years"], "answer": 2, "explain": "Toxic stress can harm the developing brain when it is long and unsupported.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Why do early-years programmes help disadvantaged children?", "options": ["They create gaps", "They are only for rich children", "They replace families", "They reduce gaps before school begins"], "answer": 3, "explain": "Early programmes can help level the start for children from disadvantaged homes.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What does parenting support do for early learning?", "options": ["Helps parents support their children's learning", "Replaces parents completely in their children's lives", "Stops children from learning at home and school", "Only buys toys for children to play with"], "answer": 0, "explain": "Parenting support gives adults ideas for talking, playing and caring for young children.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What does a home learning environment include?", "options": ["Only television", "Books, talking and play at home", "Only silence", "Only homework"], "answer": 1, "explain": "A supportive home learning environment encourages reading, talking and play.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Why is early childhood care important for girls?", "options": ["It is not needed for girls", "It only matters after school", "It helps them start school ready to learn", "It only matters for boys"], "answer": 2, "explain": "Early care supports girls' health, learning and confidence.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 10, "q": "What is family literacy?", "options": ["Literacy only for grandparents", "Reading without children", "Writing only for the elderly", "Parents and children learning to read together"], "answer": 3, "explain": "Family literacy helps parents and children grow their reading skills together.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "What is the reading gap between countries?", "options": ["Differences in reading levels between countries", "The space between books on shelves", "The gap between school desks", "The distance between two schools"], "answer": 0, "explain": "The reading gap shows how much reading levels differ between places.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "What is writing fluency?", "options": ["Writing with no words", "Writing clearly and quickly", "Writing only in capital letters", "Writing only with a computer"], "answer": 1, "explain": "Writing fluency means writing smoothly enough to express ideas.", "src": "UNESCO"}, {"ch": 10, "q": "What is oral language?", "options": ["Written language only", "Language used only in books", "Spoken language", "Language used only by animals"], "answer": 2, "explain": "Oral language is the spoken language that children learn first.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "Why is oral language important before reading?", "options": ["It has no link to reading", "It stops children reading", "It is only for singing", "It builds vocabulary that supports reading"], "answer": 3, "explain": "Strong spoken language helps children understand what they read.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "What is the purpose of International Literacy Day?", "options": ["To raise awareness of literacy and its benefits", "To close all the libraries in the country", "To sell more books in shops across the country", "To stop all reading lessons in primary schools"], "answer": 0, "explain": "International Literacy Day raises awareness of literacy and what it makes possible.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "What does inclusive education ask of teachers?", "options": ["Teaching only the top students", "Adapting lessons to different learners", "Ignoring learners who need help", "Refusing extra training"], "answer": 1, "explain": "Inclusive teaching adapts methods so every learner can take part.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is universal design for learning?", "options": ["A design for school buildings with no classrooms at all", "Teaching that uses only one way for every learner", "Teaching designed to work for many kinds of learners", "A type of school uniform worn by every pupil daily"], "answer": 2, "explain": "Universal design for learning offers multiple ways to learn and show understanding.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Why do learners with disabilities need reasonable accommodation?", "options": ["To get out of work", "To avoid tests", "To have a holiday", "To take part equally in lessons"], "answer": 3, "explain": "Accommodations let learners with disabilities take part equally.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What does a sign language interpreter do in class?", "options": ["Translates between sign and spoken language", "Teaches dance and music to the whole class", "Sells books and stationery to the students", "Drives the school bus on the morning route"], "answer": 0, "explain": "Interpreters help deaf learners follow lessons.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What does Braille help learners do?", "options": ["Hear music", "Read by touch", "Swim faster", "Grow taller"], "answer": 1, "explain": "Braille lets people who are blind read by touching raised dots.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Why does inclusion benefit everyone in a school?", "options": ["It makes classes smaller for no reason", "It reduces learning", "It builds understanding and respect", "It stops friendships"], "answer": 2, "explain": "Inclusive classrooms teach respect and understanding among all learners.", "src": "UN CRPD (2006), Article 24"}], "8": [{"ch": 0, "q": "How many SDG 4 targets are about means of implementation?", "options": ["Three", "Seven", "Ten", "Four"], "answer": 0, "explain": "Targets 4.a to 4.c are the three means of implementation.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What is Target 4.c about?", "options": ["Building new sports fields", "Increasing the supply of qualified teachers", "Giving free books to adults", "Making schools smaller"], "answer": 1, "explain": "Target 4.c calls for more qualified teachers, including through training.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Which target focuses on sustainable development and global citizenship?", "options": ["Target 4.1", "Target 4.2", "Target 4.7", "Target 4.b"], "answer": 2, "explain": "Target 4.7 covers knowledge for sustainable development and global citizenship.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What does a proficiency indicator focus on?", "options": ["How many buildings a school has", "How many holidays a year", "How tall learners are", "Whether learners reach a set level in key skills"], "answer": 3, "explain": "Proficiency indicators check whether learners reach a set level in skills such as reading and maths.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "What does disaggregating data by sex, age and disability mean?", "options": ["Breaking the data down by each of these groups", "Keeping the data secret", "Collecting data only from men", "Collecting data only about buildings"], "answer": 0, "explain": "Disaggregation shows whether progress reaches every group.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Which Goal is about reduced inequalities?", "options": ["Goal 6", "Goal 10", "Goal 13", "Goal 15"], "answer": 1, "explain": "Goal 10 is Reduced Inequalities.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "What is an out-of-school rate?", "options": ["The share of students who skip lunch", "The share of schools with no roof", "The share of school-age children who are not in school", "The share of teachers on leave"], "answer": 2, "explain": "The out-of-school rate measures school-age children who are not enrolled.", "src": "UNESCO"}, {"ch": 1, "q": "What makes a school accessible in terms of distance?", "options": ["It is far from all homes", "It can be reached only by plane", "It is closed on weekdays", "It is within safe reach of children's homes"], "answer": 3, "explain": "Accessibility means children can reach school safely and regularly.", "src": "UNESCO"}, {"ch": 1, "q": "Which cost is often hidden for poor families?", "options": ["Lost income from children's work", "Free exercise books", "Free school lunches", "Free transport"], "answer": 0, "explain": "Poor families may lose income when children attend school instead of working.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What is a last-mile challenge in education?", "options": ["Walking the longest race", "Reaching the most remote children", "Taking the last exam", "Closing the final school"], "answer": 1, "explain": "Last-mile challenges focus on reaching children who are hardest to reach.", "src": "UNESCO"}, {"ch": 1, "q": "Why do governments track enrolment data?", "options": ["To choose school colours", "To rank students by height", "To plan teachers, buildings and places", "To choose holiday dates"], "answer": 2, "explain": "Enrolment data helps governments plan teachers, classrooms and transport.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "What does a transition rate measure?", "options": ["The speed of school buses travelling on the main road", "The number of school bells rung in one whole day", "The price of notebooks and pens sold in the canteen", "The share of students moving from one level to the next"], "answer": 3, "explain": "Transition rates show how many students progress to the next level.", "src": "UNESCO"}, {"ch": 2, "q": "Why do some students fail to transition to secondary school?", "options": ["Costs, distance and weak earlier learning", "Secondary school is always free", "Secondary school has no entry rules", "Students are too tall"], "answer": 0, "explain": "Costs, distance and gaps from primary learning can stop students moving up.", "src": "UNESCO"}, {"ch": 2, "q": "What does upper secondary completion mean?", "options": ["Finishing the first year of kindergarten", "Finishing the final stage of secondary school", "Finishing a sports course", "Finishing a holiday camp"], "answer": 1, "explain": "Upper secondary completion means finishing the last stage of secondary school.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Which group is most likely to face several barriers to completion at once?", "options": ["Boys from rich, urban families", "Children with no barriers at all", "Girls from poor, rural families with disabilities", "Adults only"], "answer": 2, "explain": "Overlapping disadvantages make completion harder for some learners.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "What is an alternative learning pathway?", "options": ["A route to a qualification with no written exam at all", "A route that is only open to qualified teachers", "A route that stops learners from finishing their study", "A route to the same qualification by a different path"], "answer": 3, "explain": "Alternative pathways let learners earn qualifications in flexible ways.", "src": "UNESCO"}, {"ch": 2, "q": "What is an early warning system in schools?", "options": ["Spotting learners at risk of leaving so help can start early", "Warning students about the final exams at the end of year", "Sending loud alarms at lunchtime to call pupils back in", "Ringing the school bell louder and longer for assemblies"], "answer": 0, "explain": "Early warning systems flag attendance and learning problems so schools can act.", "src": "UNESCO"}, {"ch": 3, "q": "What is an international learning assessment?", "options": ["A school sports competition", "A test comparing learning across countries", "A teacher hiring test", "A government budget plan"], "answer": 1, "explain": "International assessments such as PISA, TIMSS and PIRLS compare learning across countries.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is PISA?", "options": ["A school bus system that runs for children in rural areas", "A type of school uniform worn by pupils in the city", "A test of 15-year-olds' skills in reading, maths and science", "A global sports tournament for young athletes each year"], "answer": 2, "explain": "PISA is an OECD test of 15-year-olds in reading, mathematics and science.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Why do learning assessments need careful design?", "options": ["So that tests are never needed", "So that tests are longer", "So that students never see them", "To measure fairly across languages and cultures"], "answer": 3, "explain": "Good assessments are designed to be fair and comparable across groups.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is a learning crisis?", "options": ["Many children are in school but not learning", "Children are learning too fast", "Schools have too many books", "Children never attend school"], "answer": 0, "explain": "The learning crisis describes children who attend school but do not gain basic skills.", "src": "World Bank, learning poverty"}, {"ch": 3, "q": "What is an early grade reading assessment?", "options": ["A test for adults only, held after their working day", "A test of reading in the first years of school", "A test of sports skills for the school football team", "A test of cooking skills for young learners at home"], "answer": 1, "explain": "Early grade reading assessments check whether young children are learning to read.", "src": "UNESCO"}, {"ch": 3, "q": "What does comprehension help learners do with a maths word problem?", "options": ["Guess the answer without reading", "Skip the question", "Understand what the problem asks", "Copy from a friend"], "answer": 2, "explain": "Comprehension helps learners understand a problem before solving it.", "src": "UNESCO"}, {"ch": 4, "q": "What is data literacy?", "options": ["Collecting data about pets", "Hiding data from others", "Storing data only on paper", "Reading, understanding and using data"], "answer": 3, "explain": "Data literacy means understanding and using data to make decisions.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Why do students need to understand artificial intelligence?", "options": ["To use it wisely and understand its limits", "To replace all teachers", "To stop using computers", "To avoid all technology"], "answer": 0, "explain": "Learners need to use AI tools responsibly and understand what they can and cannot do.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is an entrepreneurial mindset?", "options": ["Avoiding all risks and always staying in one place", "Spotting opportunities and taking sensible risks", "Only working for other people and never for yourself", "Never trying new things or new ideas in your life"], "answer": 1, "explain": "An entrepreneurial mindset means noticing opportunities and acting on them responsibly.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What are soft skills?", "options": ["Skills for lifting heavy objects", "Skills for baking bread only", "Skills like teamwork, empathy and communication", "Skills for sleeping"], "answer": 2, "explain": "Soft skills help people work and live well with others.", "src": "UNESCO"}, {"ch": 4, "q": "What is lifelong learning?", "options": ["Learning only until age ten", "Learning only at university", "Learning only on Sundays", "Learning throughout life, not only at school"], "answer": 3, "explain": "Lifelong learning means continuing to learn across the whole of life.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Why is lifelong learning important for work?", "options": ["Work changes, so people need new skills", "Jobs never change", "Learning is useless after school", "Jobs need no skills"], "answer": 0, "explain": "New technologies and industries mean people keep learning new skills.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What does learning to learn mean?", "options": ["Memorising nothing at all and hoping to pass anyway", "Knowing how you learn best and planning your learning", "Copying answers quickly from a classmate's notebook", "Never asking any questions in class or at home"], "answer": 1, "explain": "Learning to learn helps people become independent learners.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What is intersectionality in education?", "options": ["A type of school building with many floors and rooms", "A kind of school timetable used across all classes", "How overlapping identities can increase disadvantage", "A way of splitting classes by each child's height"], "answer": 2, "explain": "Intersectionality recognises that gender, poverty, disability and other factors can overlap.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What does gender-transformative education aim to do?", "options": ["Keep gender norms unchanged", "Teach only one gender", "Ignore gender in every subject", "Change harmful gender norms"], "answer": 3, "explain": "Gender-transformative education challenges stereotypes and unequal roles.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "Why do some girls face higher risks of leaving school during conflict?", "options": ["Insecurity, displacement and gender-based violence", "Girls are always safer", "Conflict has no effect on schools", "Girls prefer conflict"], "answer": 0, "explain": "Conflict can increase risks such as displacement and violence, which push girls out of school.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What helps prevent gender-based violence in schools?", "options": ["Hiding incidents from parents and the public", "Policies, codes of conduct and training", "Blaming the victims for what happened to them", "Ignoring every report that the school receives"], "answer": 1, "explain": "Prevention includes clear codes of conduct, training and reporting systems.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What is equal participation in a classroom?", "options": ["Only the loudest learners speak", "Only boys speak in class", "All learners can take part and be heard", "Only the teacher speaks"], "answer": 2, "explain": "Equal participation means every learner has a fair chance to contribute.", "src": "UNESCO"}, {"ch": 5, "q": "What is discriminatory language in a school?", "options": ["Words that praise hard work", "Words that explain a lesson", "Words that describe the weather", "Words that demean people based on who they are"], "answer": 3, "explain": "Discriminatory language harms learners and creates an unsafe environment.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What does stigma mean for learners?", "options": ["Negative judgements that exclude people", "A type of school prize", "A kind of school uniform", "A form of praise"], "answer": 0, "explain": "Stigma leads people to be treated unfairly, which can stop them learning.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "What are teacher professional standards?", "options": ["A list of teacher holidays", "Expectations for what teachers should know and do", "A list of school snacks", "A list of teacher salaries only"], "answer": 1, "explain": "Professional standards describe what good teaching looks like.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why is teacher recruitment a policy challenge?", "options": ["It requires hiring only relatives", "It requires no planning", "It requires attracting and selecting capable people", "It requires closing schools"], "answer": 2, "explain": "Good recruitment finds capable people and places them where they are needed.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is teacher deployment?", "options": ["Sending teachers on holiday", "Sending teachers to other countries only", "Removing teachers from schools", "Placing teachers where they are needed"], "answer": 3, "explain": "Deployment means allocating teachers to schools and areas where they are most needed.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is teacher retention?", "options": ["Keeping teachers in the profession", "Keeping teachers in class with no breaks", "Keeping students from becoming teachers", "Keeping teachers away from children"], "answer": 0, "explain": "Retention strategies keep trained teachers in their jobs.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why do teachers need some autonomy?", "options": ["To avoid all rules", "To adapt lessons to their students", "To teach nothing", "To work without support"], "answer": 1, "explain": "Some autonomy helps teachers adapt their lessons to real classroom needs.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is a teacher union?", "options": ["A group that closes schools", "A group that sells textbooks", "An organisation that represents teachers' interests", "A group that sets exam dates alone"], "answer": 2, "explain": "Teacher unions represent teachers in discussions about pay and working conditions.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is teacher absenteeism?", "options": ["Teachers attending training", "Teachers helping in clubs", "Teachers reading books", "Teachers missing work without good reason"], "answer": 3, "explain": "Absenteeism reduces learning time, so it is a policy concern.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What does teacher wellbeing affect?", "options": ["How well teachers teach and stay in their jobs", "Only the price of school buses", "Only the weather", "Nothing important"], "answer": 0, "explain": "Teacher wellbeing affects teaching quality and retention.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "What is budget transparency in education?", "options": ["Hiding spending from the public", "Publishing how education money is spent", "Spending money in secret", "Ignoring budgets"], "answer": 1, "explain": "Transparency lets citizens check how education funds are used.", "src": "UNESCO"}, {"ch": 7, "q": "What is targeted financing for education?", "options": ["Equal funds for every school, regardless of its need", "Funds spent only on school sports, games and trips", "Extra funds sent to schools or students with the greatest needs", "Funds sent only to schools that are already very rich"], "answer": 2, "explain": "Targeted financing directs more resources where needs are greatest.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "What is efficiency in school spending?", "options": ["Spending the most money possible", "Spending on the least useful things", "Spending only on buildings", "Getting the most learning from the money spent"], "answer": 3, "explain": "Efficient spending gets better learning results from the same amount of money.", "src": "UNESCO"}, {"ch": 7, "q": "Why do many countries fund schools through local taxes?", "options": ["To give local communities a say in spending", "Local taxes are illegal", "Local taxes replace all government money", "Local taxes are only for sports"], "answer": 0, "explain": "Local funding can make schools more responsive, though it can also increase inequality.", "src": "UNESCO"}, {"ch": 7, "q": "What is the risk of relying on local taxes alone?", "options": ["Poorer areas always get more money", "Richer areas may fund schools better", "Schools never need money", "Local taxes always end inequality"], "answer": 1, "explain": "Relying only on local taxes can widen gaps between rich and poor areas.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "What is a capital budget for schools?", "options": ["Money for teachers' salaries only", "Money for holidays", "Money for buildings and equipment", "Money for school uniforms only"], "answer": 2, "explain": "A capital budget pays for long-term assets such as buildings and equipment.", "src": "UNESCO"}, {"ch": 7, "q": "What is a recurrent budget for schools?", "options": ["Money for building one new school", "Money for a single exam", "Money for one-off sports events", "Money for everyday running costs such as salaries"], "answer": 3, "explain": "A recurrent budget covers ongoing costs like teacher salaries and materials.", "src": "UNESCO"}, {"ch": 7, "q": "What is unit cost in education?", "options": ["The cost of educating one student for a year", "The cost of one school bus", "The cost of a whole school uniform", "The cost of one exam paper only"], "answer": 0, "explain": "Unit cost helps governments plan how much money each learner needs.", "src": "UNESCO"}, {"ch": 8, "q": "In which year did the World Education Forum meet in Incheon?", "options": ["1990", "2015", "2000", "2030"], "answer": 1, "explain": "The World Education Forum was held in Incheon, Republic of Korea, in 2015.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Where was the 2015 World Education Forum held?", "options": ["Dakar, Senegal", "Jomtien, Thailand", "Incheon, Republic of Korea", "Paris, France"], "answer": 2, "explain": "Incheon in the Republic of Korea hosted the 2015 forum.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Where was the 2000 World Education Forum held?", "options": ["Incheon, Republic of Korea", "Jomtien, Thailand", "Nairobi, Kenya", "Dakar, Senegal"], "answer": 3, "explain": "The Dakar forum in 2000 adopted the Dakar Framework for Action.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "What does Article 26 of the Universal Declaration of Human Rights cover?", "options": ["The right to education", "The right to a car", "The right to a holiday", "The right to vote in schools"], "answer": 0, "explain": "Article 26 sets out the right to education.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "What does Education 2030 build on?", "options": ["Only the Olympic Games and the rules for athletes", "The Millennium Development Goals and Education for All", "Only space exploration and rocket science studies", "Only sports rules and football tournament results"], "answer": 1, "explain": "Education 2030 builds on earlier global education commitments.", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "Why did the world move from the MDGs to the SDGs?", "options": ["To cancel all education goals for the next decade", "To focus on just one country and ignore others", "To cover a wider range of issues for all countries", "To remove every target that countries had set"], "answer": 2, "explain": "The SDGs are universal and cover more issues than the MDGs.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "What period did the MDGs cover?", "options": ["1990 to 2000", "2015 to 2030", "2000 to 2030", "2000 to 2015"], "answer": 3, "explain": "The MDGs ran from 2000 to 2015.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "What is responsive caregiving?", "options": ["Adults reacting warmly and appropriately to a child's signals", "Ignoring a child's signals and letting them cry", "Only giving orders and never listening to children", "Keeping children apart from adults in all settings"], "answer": 0, "explain": "Responsive caregiving builds trust and supports learning.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Why does a child's health matter for learning?", "options": ["Health has no effect on learning", "Illness and hunger can stop children learning", "Only sport needs health", "Healthy children never need school"], "answer": 1, "explain": "Good health and nutrition help children learn and concentrate.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "What is stunting?", "options": ["Growing very fast and becoming much taller than most of your peers", "A school discipline rule about uniform, hair and shoes for everyone", "Being much shorter than expected for age because of poor nutrition", "Being very tall for age and growing faster than most peers"], "answer": 2, "explain": "Stunting is a sign of chronic under-nutrition and can affect learning.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "What is early stimulation?", "options": ["Keeping a baby in complete silence for many hours each day", "Giving toddlers only sweets and treats at every meal", "Keeping babies in dark rooms for most of the whole day", "Activities that encourage a baby's senses and thinking"], "answer": 3, "explain": "Early stimulation includes talking, singing, touch and play.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Why do early-years services need trained staff?", "options": ["Trained staff support children's development best", "Staff are not needed", "Training is a waste of money", "Trained staff make children stop learning"], "answer": 0, "explain": "Well-trained early-years staff understand how young children learn.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "What is a transition programme from early years to primary school?", "options": ["A bridge over a river", "A programme that helps children adjust", "A road for school buses", "A sports field"], "answer": 1, "explain": "Transition programmes help young children settle into primary school.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "What is phonemic awareness?", "options": ["Knowing the names of colours", "Writing in capital letters only", "Noticing the sounds in spoken words", "Reading the back of a book"], "answer": 2, "explain": "Phonemic awareness helps children link sounds to letters.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "What is vocabulary in early reading?", "options": ["The price of books", "The number of pages", "The size of letters", "The words a child knows and uses"], "answer": 3, "explain": "A strong vocabulary helps children understand what they read.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "What is adult basic education?", "options": ["Basic reading, writing and numeracy for adults", "Advanced university study in physics and law", "Sports coaching for a local football team", "Driving lessons for adults who want a licence"], "answer": 0, "explain": "Adult basic education helps adults learn essential literacy and numeracy.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "What is a print-rich environment?", "options": ["A place with no printed words", "A place with lots of printed words to read", "A place where all books are locked away", "A place with only pictures"], "answer": 1, "explain": "Print-rich environments expose children to letters and words in daily life.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "Why do rural areas often have lower literacy levels?", "options": ["Rural people never read", "Literacy is not taught in rural areas by law", "Fewer schools, books and reading places are close by", "Rural people do not need reading"], "answer": 2, "explain": "Many countries show lower literacy in rural areas, where schools and books are harder to reach.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Why is reading for pleasure important?", "options": ["It wastes time", "It is only for teachers", "It stops children reading later", "It builds reading habits and wider knowledge"], "answer": 3, "explain": "Reading for pleasure builds habits that support lifelong learning.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "What does universal design for learning encourage?", "options": ["Multiple ways to present, engage and assess learning", "One way of teaching that every learner must follow", "Removing all assessments from the school year", "Teaching only in silence with no discussion at all"], "answer": 0, "explain": "Universal design offers choices so that learners can access and show learning.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is a learning support plan?", "options": ["A plan for school holidays for all the students", "A plan that sets out support for a learner's needs", "A plan to end lessons early every single day", "A plan to remove some learners from the school"], "answer": 1, "explain": "Learning support plans set out adjustments and help for individual learners.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Why should families of learners with disabilities be involved?", "options": ["Families should not be involved", "Families only pay fees", "They know the learner's needs best", "Families cause problems"], "answer": 2, "explain": "Families contribute knowledge that helps schools support learners.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is inclusive assessment?", "options": ["Tests that only the best can pass", "Tests that are never given", "Tests that only measure speed", "Tests that let all learners show what they know"], "answer": 3, "explain": "Inclusive assessment adjusts how learning is shown so all learners can demonstrate it.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is peer support in an inclusive school?", "options": ["Classmates helping each other learn", "Classmates competing to exclude others", "Classmates working only alone", "Classmates avoiding each other"], "answer": 0, "explain": "Peer support helps learners feel included and learn together.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Why do inclusive schools reduce discrimination?", "options": ["They separate children by ability", "They teach respect and make difference normal", "They remove all diversity", "They increase fear"], "answer": 1, "explain": "When children learn together, they build respect and understanding.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is segregation in schools?", "options": ["Bringing all children together in the same classroom each day", "Sharing books and materials equally between pupils", "Separating children by disability, gender or background", "Giving everyone a fair turn on the playground"], "answer": 2, "explain": "Segregation separates learners unfairly and is opposed by inclusive education.", "src": "UN CRPD (2006), Article 24"}, {"ch": 1, "q": "What is a school catchment area?", "options": ["A type of school sport", "The roof of a school", "A school meal", "The area a school is planned to serve"], "answer": 3, "explain": "A catchment area is the zone of children a school is planned to serve.", "src": "UNESCO"}], "9": [{"ch": 0, "q": "Which SDG is about partnerships for the goals?", "options": ["Goal 17", "Goal 7", "Goal 12", "Goal 1"], "answer": 0, "explain": "Goal 17 is Partnerships for the Goals.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What does means of implementation refer to?", "options": ["The names of all the goals written on a large poster", "The resources and tools needed to reach the goals", "The dates of the meetings held in the city hall each year", "The colours of the posters hung up in the school hall"], "answer": 1, "explain": "Means of implementation include finance, technology, capacity and partnerships.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What is the data gap problem in SDG monitoring?", "options": ["There is far too much data for anyone to read properly", "Data is only kept on paper in old filing cabinets", "Many countries lack reliable data to track progress", "Data is always perfect and never needs any checking"], "answer": 2, "explain": "Gaps in data make it hard to measure progress and identify who is left behind.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "Why do the SDGs use indicators?", "options": ["To set school timetables", "To choose the national anthem", "To replace teachers", "To measure progress in a consistent way"], "answer": 3, "explain": "Indicators make progress comparable across countries and over time.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What is Agenda 2030?", "options": ["A plan adopted in 2015 to reach the goals by 2030", "A plan for the Olympic Games held in Paris in 2030", "A school timetable that runs for every term until 2030", "A holiday schedule for every school across the year 2030"], "answer": 0, "explain": "Agenda 2030 is the UN plan adopted in 2015 for the Global Goals.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What does a national SDG 4 plan do?", "options": ["Closes all schools", "Sets out how a country will reach SDG 4", "Cancels all exams", "Ends school fees by decree alone"], "answer": 1, "explain": "A national plan sets priorities, budgets and actions to reach SDG 4.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "What is school exclusion?", "options": ["Being given a prize", "Being moved to a new school by choice", "Being removed or kept out of school", "Being offered extra lessons"], "answer": 2, "explain": "Exclusion keeps children from learning, which breaks their right to education.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "What is the impact of child marriage on school?", "options": ["It always improves school", "It has no effect", "It makes school free", "It often ends schooling early"], "answer": 3, "explain": "Child marriage is a major reason girls leave school early.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "What is displacement for education?", "options": ["Being forced to leave home, often disrupting schooling", "Moving a school desk to the other side of the room", "Choosing a new school for the next term each year", "A type of school test given at the start of term"], "answer": 0, "explain": "Displaced children can lose years of schooling without support.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What is refugee education?", "options": ["Education only for teachers who work in one particular school", "Education for children and young people who have fled their homes", "Education in sport and outdoor activity only for the whole school", "Education only for adults who return to study in later life"], "answer": 1, "explain": "Refugee education helps displaced learners continue learning.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Why does education in emergencies matter?", "options": ["It has no value in crises", "It is only for tourists", "It gives children stability and protection", "It replaces all food aid"], "answer": 2, "explain": "Schools in emergencies provide safety, routine and hope for children.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "What is a temporary learning space?", "options": ["A building used for storing cars and heavy machinery", "A shop that sells books, pens and paper to all students", "A place only for adults to rest in the afternoon each day", "A safe place for learning set up quickly after a crisis"], "answer": 3, "explain": "Temporary learning spaces keep children learning when permanent schools are not usable.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What is distance to school usually measured by?", "options": ["The time or distance a child must travel", "The number of books", "The colour of the school", "The number of teachers in town"], "answer": 0, "explain": "Travel time and distance are common measures of access.", "src": "UNESCO"}, {"ch": 1, "q": "Why do children with disabilities often miss school?", "options": ["They do not want to learn", "Schools are not accessible or supported", "They are too clever for school", "They have too many toys"], "answer": 1, "explain": "A lack of accessible buildings, teaching and support keeps many children out.", "src": "UN CRPD (2006), Article 24"}, {"ch": 2, "q": "What is a repetition rate?", "options": ["The share who win races", "The share who enter early", "The share of students who repeat a grade", "The share who study music"], "answer": 2, "explain": "Repetition rates show how often students repeat a grade.", "src": "UNESCO"}, {"ch": 2, "q": "Why is repetition often a poor solution?", "options": ["It always improves learning", "It is free for everyone", "It removes all gaps", "It can increase the risk of dropping out"], "answer": 3, "explain": "Repeating a year often increases the chance a student leaves school.", "src": "UNESCO"}, {"ch": 2, "q": "What is grade promotion?", "options": ["Moving up to the next grade", "Selling school uniforms", "Moving to a new country", "Quitting school"], "answer": 0, "explain": "Promotion means a student moves on to the next grade.", "src": "UNESCO"}, {"ch": 2, "q": "What is a school-leaving certificate?", "options": ["A ticket to a big football match at the national stadium", "A document that shows a student has finished a level", "A fine given to any student who misses school often", "A map that shows where each school in the town is located"], "answer": 1, "explain": "A school-leaving certificate records completion of a level of education.", "src": "UNESCO"}, {"ch": 2, "q": "What do national completion targets aim to do?", "options": ["Reduce the total number of schools across the whole country", "Stop children from ever moving up to the next level", "Raise the share of children who finish each level", "Give fewer exams to every student in the entire school"], "answer": 2, "explain": "National targets focus on helping more children finish each level.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "What is skills certification?", "options": ["A type of school bag with many small pockets inside", "A holiday schedule for the whole family each summer", "A cooking recipe for a special family dinner at home", "Official recognition of skills a person has"], "answer": 3, "explain": "Certification shows employers and others that a person has a skill.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "What is recognition of prior learning?", "options": ["Giving credit for learning already gained outside school", "Ignoring all past learning and starting from zero each time", "Only counting exams taken at a university or college", "Removing qualifications that people have already earned"], "answer": 0, "explain": "Recognising prior learning helps people move forward without repeating what they know.", "src": "UNESCO"}, {"ch": 3, "q": "What is a learning standard?", "options": ["A type of school building with many classrooms", "A statement of what learners should know and do", "A kind of school bus that travels every morning", "A school dress code for students and teachers"], "answer": 1, "explain": "Learning standards describe expected outcomes for each level.", "src": "UNESCO"}, {"ch": 3, "q": "What does the Global Education Monitoring Report focus on?", "options": ["Selling textbooks", "Choosing school sports", "Tracking progress in education worldwide", "Planning holidays"], "answer": 2, "explain": "The GEM Report tracks progress on education and shares evidence.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is a learning profile?", "options": ["A photo of a student", "A list of school holidays", "A map of the school", "A record of a learner's strengths and needs"], "answer": 3, "explain": "Learning profiles help teachers plan support for each learner.", "src": "UNESCO"}, {"ch": 3, "q": "Why do teachers use diagnostic assessments?", "options": ["To find what learners already know and what they need", "To give grades only at the end of each school year", "To avoid teaching the whole class for the whole day", "To punish children every time they make a mistake"], "answer": 0, "explain": "Diagnostic assessments help teachers plan lessons that match learners' needs.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is curriculum reform?", "options": ["Changing the school colour", "Changing what is taught and how", "Closing all schools", "Cancelling all subjects"], "answer": 1, "explain": "Curriculum reform updates subjects, skills and teaching methods.", "src": "UNESCO"}, {"ch": 3, "q": "What is competency-based learning?", "options": ["Focusing only on memorising facts", "Focusing only on sports", "Focusing on what learners can do", "Focusing only on time spent in class"], "answer": 2, "explain": "Competency-based learning measures skills and abilities, not just knowledge.", "src": "UNESCO"}, {"ch": 3, "q": "Why is science literacy important?", "options": ["It replaces all reading and writing skills", "It only helps scientists in their laboratories", "It has no real use in everyday life at all", "It helps people understand and judge evidence"], "answer": 3, "explain": "Science literacy helps people make informed decisions about health and the environment.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "What is mathematical reasoning?", "options": ["Explaining why a method works", "Guessing the answer", "Copying the answer", "Skipping the working"], "answer": 0, "explain": "Reasoning shows that learners understand the method, not just the answer.", "src": "UNESCO"}, {"ch": 3, "q": "What is a learning gain?", "options": ["A gain in weight", "Progress a learner makes over a period", "A profit from school sales", "A gain in holidays"], "answer": 1, "explain": "Learning gains measure how much a learner improves over time.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "What is a green skill?", "options": ["A skill for painting walls green", "A skill for growing grass only", "A skill that helps protect the environment", "A skill for playing green games"], "answer": 2, "explain": "Green skills support environmental protection and sustainable jobs.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Why is climate education linked to Target 4.7?", "options": ["Climate has no link to learning", "Climate education is banned", "Climate education replaces maths", "It supports education for sustainable development"], "answer": 3, "explain": "Target 4.7 includes education for sustainable development, which covers climate.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is peace education?", "options": ["Learning how to resolve conflict without violence", "Learning how to start conflicts", "Learning only war history", "Learning to avoid people"], "answer": 0, "explain": "Peace education teaches respect, dialogue and non-violence.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What does human rights education teach?", "options": ["Only the rules of games", "Learners' rights and responsibilities", "Only the history of trains", "Only how to cook"], "answer": 1, "explain": "Human rights education helps learners know and respect rights.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is civic education?", "options": ["Learning only about cars", "Learning only about trees", "Learning about citizenship and public life", "Learning only about sport"], "answer": 2, "explain": "Civic education helps learners take part responsibly in their community.", "src": "UNESCO"}, {"ch": 4, "q": "Why is cultural understanding taught?", "options": ["It stops people travelling", "It makes all cultures identical", "It is only for tourists", "It helps people respect different ways of life"], "answer": 3, "explain": "Cultural understanding reduces prejudice and builds respect.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is problem-based learning?", "options": ["Learning by solving real problems", "Learning by memorising lists", "Learning by avoiding questions", "Learning by copying notes only"], "answer": 0, "explain": "Problem-based learning develops thinking by working through real challenges.", "src": "UNESCO"}, {"ch": 5, "q": "What does poverty mean in education?", "options": ["Having too many books on the classroom shelf", "A lack of money that limits access to learning", "Having too many teachers for the number of pupils", "Having too many holidays during the school year"], "answer": 1, "explain": "Poverty can limit access to school, food, transport and learning materials.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "What is an ethnic disparity in education?", "options": ["Differences in the colour of school bags", "Differences in school holidays only", "Differences in school results between ethnic groups", "Differences in school shoes"], "answer": 2, "explain": "Ethnic disparities show that some groups achieve less, which may reflect unfair barriers.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "What is a rural-urban disparity?", "options": ["Differences in the number of city parks", "Differences in rainfall", "Differences in school uniforms", "Differences between learning in rural and urban areas"], "answer": 3, "explain": "Rural areas often have fewer resources, which can widen learning gaps.", "src": "UNESCO"}, {"ch": 5, "q": "What does a wealth quintile measure?", "options": ["Dividing households into five groups by wealth", "Five types of school bus used across the whole town", "Five ways to write a test for a whole class each year", "Five colours of chalk used in every classroom at school"], "answer": 0, "explain": "Wealth quintiles split families into five groups to compare education outcomes.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "What is a pro-poor policy in education?", "options": ["A policy that only helps the richest", "A policy that targets the poorest learners", "A policy that closes schools in poor areas", "A policy that raises fees for the poor"], "answer": 1, "explain": "Pro-poor policies focus resources on those who need them most.", "src": "UNESCO"}, {"ch": 5, "q": "What is equal opportunity in education?", "options": ["Only the best learners get chances", "Chances depend on family wealth", "The same chance to succeed, regardless of background", "Chances are given only in cities"], "answer": 2, "explain": "Equal opportunity means background should not decide what a learner can achieve.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "What is a teacher pay gap?", "options": ["Teachers are paid more than doctors", "Teachers are paid in gold", "Teachers are never paid", "Teachers are paid less than similar professionals"], "answer": 3, "explain": "A pay gap means teachers earn less than comparable workers, making the job less attractive.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why does teacher pay matter for learning?", "options": ["It affects who becomes and stays a teacher", "It has no link with learning", "It only affects school buildings", "It only affects holidays"], "answer": 0, "explain": "Pay influences whether capable people choose and remain in teaching.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is teacher licensing?", "options": ["A permit to sell school food", "Official permission to teach", "A permit to build schools", "A permit to run a bus service"], "answer": 1, "explain": "Licensing sets minimum standards for people who teach.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is a teacher induction programme?", "options": ["Training for school bus drivers", "Training for cooks", "Support for teachers in their first years", "Training for parents only"], "answer": 2, "explain": "Induction helps new teachers settle in and improve.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is teacher mobility?", "options": ["Teachers flying in planes", "Teachers running races", "Teachers staying in one room forever", "Teachers moving between schools or areas"], "answer": 3, "explain": "Teacher mobility affects which areas have enough qualified teachers.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is teacher diversity?", "options": ["Teachers from different backgrounds in schools", "Teachers who all look the same", "Teachers who speak only one language", "Teachers with no training"], "answer": 0, "explain": "Diverse teaching staff can help students see themselves in their teachers.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "What is instructional leadership?", "options": ["School leaders focusing on sports only", "School leaders focusing on teaching and learning", "School leaders focusing on holidays", "School leaders avoiding teachers"], "answer": 1, "explain": "Instructional leaders help teachers improve classroom practice.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why do schools need school leaders?", "options": ["They replace the teachers in every classroom", "They teach only sport and physical education", "They guide teaching and manage the school", "They are not needed in a well-run school"], "answer": 2, "explain": "School leaders support teachers and set the direction for learning.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "What is sustainable financing for education?", "options": ["Money that is spent once and never again", "Money raised only from one lottery", "Money spent only on buildings", "Funding that lasts over the long term"], "answer": 3, "explain": "Sustainable financing means reliable funding that continues over many years.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "What is aid for education?", "options": ["Money or support given by other countries or organisations", "Money given by teachers to their own school for supplies", "Money that comes only from school fees paid by parents", "Money raised only from school sales, bake sales and fairs"], "answer": 0, "explain": "Education aid comes from donors to support schools in other countries.", "src": "UNESCO"}, {"ch": 7, "q": "What does ODA stand for?", "options": ["Official Digital Access", "Official Development Assistance", "Open Document Archive", "Online Daily Attendance"], "answer": 1, "explain": "ODA means Official Development Assistance, which includes aid to education.", "src": "UNESCO"}, {"ch": 7, "q": "What is domestic resource mobilisation?", "options": ["Raising money only from other countries", "Raising money by selling schools", "Raising money within the country for public services", "Raising money from the moon"], "answer": 2, "explain": "Countries raise money through taxes and other domestic income for schools.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "Why do some countries rely on external aid for education?", "options": ["They have unlimited money", "They do not want schools", "They cannot spend money", "Their own resources are limited"], "answer": 3, "explain": "Limited domestic resources can mean reliance on external support.", "src": "UNESCO"}, {"ch": 7, "q": "What is an education fund used for?", "options": ["Paying for schooling and learning programmes", "Paying for family holidays and summer trips", "Paying for new cars for the school staff", "Paying for tickets to big sports events"], "answer": 0, "explain": "Education funds pay for schooling, materials and programmes.", "src": "UNESCO"}, {"ch": 8, "q": "What did the Jomtien conference of 1990 produce?", "options": ["A football rulebook used for school tournaments only", "A declaration on meeting basic learning needs", "A list of the school holidays for every single year", "A new currency introduced in the whole region that year"], "answer": 1, "explain": "The World Declaration on Education for All was adopted at Jomtien in 1990.", "src": "UNESCO"}, {"ch": 8, "q": "What is the World Declaration on Education for All?", "options": ["A 2030 sports plan for all the national teams", "A school uniform code that applies to all students", "A 1990 declaration promising education for all", "A teacher pay law passed by parliament last year"], "answer": 2, "explain": "The declaration was adopted at Jomtien in 1990 and set out Education for All.", "src": "UNESCO"}, {"ch": 8, "q": "Which 2000 event adopted the Dakar Framework?", "options": ["A football World Cup", "An Olympic Games", "A trade summit", "The World Education Forum"], "answer": 3, "explain": "The Dakar Framework was adopted at the World Education Forum in 2000.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "What did the Incheon Declaration commit to?", "options": ["Inclusive, equitable, quality education for lifelong learning", "Only university study for a small group of top students", "Only sports and games for the school team every week", "Only holidays and free days for all the students"], "answer": 0, "explain": "The Incheon Declaration committed countries to lifelong learning opportunities.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "What did the Dakar Framework include beyond children's schooling?", "options": ["Literacy only for teachers", "Adult literacy and gender equality", "Literacy only in sport", "Literacy only for rich countries"], "answer": 1, "explain": "The Dakar Framework included goals for adult literacy and gender equality.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "Which Millennium Development Goal aimed to promote gender equality?", "options": ["Goal 1", "Goal 5", "Goal 3", "Goal 6"], "answer": 2, "explain": "MDG 3 aimed to promote gender equality and empower women.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "What did the MDGs aim to reduce?", "options": ["Sport", "Schools", "Holidays", "Extreme poverty and hunger"], "answer": 3, "explain": "Among other aims, the MDGs aimed to reduce extreme poverty and hunger.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "What is quality early learning?", "options": ["Learning that is responsive, playful and supportive", "Learning that is strict and silent", "Learning that uses only worksheets", "Learning that avoids adults"], "answer": 0, "explain": "Quality early learning builds skills through warm, playful interactions.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Why is early identification of delays important?", "options": ["Problems should be ignored until school", "Support can start while the brain is developing quickly", "Children should be labelled for life", "Parents should be blamed"], "answer": 1, "explain": "Early identification allows support to begin while the brain is developing quickly.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Why is the early years workforce important?", "options": ["Staff are not needed", "Staff only clean rooms", "Skilled staff make a big difference to children", "Staff do not affect children"], "answer": 2, "explain": "Trained early years staff shape children's learning and wellbeing.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "What is a child-friendly space?", "options": ["A shop that sells only toys and sweets for children", "A building with no windows or doors at all for pupils", "A room where children are kept apart from others all day", "A safe place where children can learn and play"], "answer": 3, "explain": "Child-friendly spaces give children safe places to learn and play, especially in crises.", "src": "UNESCO GEM Report 2026"}, {"ch": 9, "q": "What does a stimulating environment mean for babies?", "options": ["Lots of talking, touch and play", "Total silence", "Dark rooms", "Constant loud noise"], "answer": 0, "explain": "Stimulating environments support brain development through interaction.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Why is early childhood a priority for policy?", "options": ["It has no benefit for children or families", "Early investment gives high returns later", "It only costs money and gives nothing back", "It only helps adults who are already working"], "answer": 1, "explain": "Early investment helps children learn and reduces later costs.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "What is emergent literacy?", "options": ["Literacy for adults only", "Reading only at university", "Early skills that lead to reading and writing", "Reading only numbers"], "answer": 2, "explain": "Emergent literacy covers early skills like letter knowledge and rhyme that lead to reading.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "What is rhyme awareness?", "options": ["Painting rhymes on walls", "Singing only loud songs", "Writing rhymes on paper only", "Hearing and making rhyming sounds"], "answer": 3, "explain": "Rhyme awareness helps children hear the sounds in words.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "What does bilingual literacy include?", "options": ["Reading and writing in two languages", "Only reading numbers", "Only drawing", "Only listening"], "answer": 0, "explain": "Bilingual literacy builds reading in two languages.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "Why is literacy linked to employment?", "options": ["Jobs never need reading", "Many jobs require reading and writing", "Literacy is only for teachers", "Literacy has no link to jobs"], "answer": 1, "explain": "Literacy helps people read instructions, write reports and learn new skills.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "What is information literacy?", "options": ["Hiding information from everyone around you", "Memorising every page of every book you read", "Finding, judging and using information well", "Ignoring the news and all current events"], "answer": 2, "explain": "Information literacy helps people judge sources and use information responsibly.", "src": "UNESCO"}, {"ch": 10, "q": "Why do many countries use local languages in early reading?", "options": ["Local languages are not allowed", "Local languages make reading harder", "Local languages are only for adults", "Children learn best in a language they speak"], "answer": 3, "explain": "Early reading is easier when children understand the words they see.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "Why is writing practice important?", "options": ["It turns reading knowledge into communication", "It has no link at all to reading skills", "It only matters for students studying art", "It replaces reading with drawing pictures only"], "answer": 0, "explain": "Writing practice helps learners express ideas and deepen reading.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "What is an inclusive curriculum?", "options": ["A curriculum that excludes some learners", "A curriculum that values and includes all learners", "A curriculum for only one group", "A curriculum with no subjects"], "answer": 1, "explain": "Inclusive curricula reflect the needs and identities of all learners.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is multi-sensory teaching?", "options": ["Using only sound", "Teaching in silence", "Using sight, sound and touch in lessons", "Teaching with blindfolds only"], "answer": 2, "explain": "Multi-sensory teaching helps learners who learn best in different ways.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is assistive technology in education?", "options": ["Games that make learning much harder for all students", "Tools that stop students from reading their books at all", "Equipment that is used for sport and games only", "Tools that help learners with disabilities take part"], "answer": 3, "explain": "Assistive technology includes screen readers, hearing devices and communication aids.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is a reasonable adjustment for exams?", "options": ["Changes such as extra time or a reader", "Removing the exam entirely for everyone", "Making exams harder for some", "Charging extra for exams"], "answer": 0, "explain": "Adjustments make exams fair without changing what is being tested.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Why should schools collect data on disability?", "options": ["To rank children by disability", "To plan support and track inclusion", "To stop children enrolling", "To sell school equipment"], "answer": 1, "explain": "Disability data helps schools plan support and check whether children are included.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is a stereotype in education?", "options": ["A type of school exam given once a year", "A school bus route that goes past the farm", "A fixed and often unfair idea about a group", "A kind of school bag that holds many books"], "answer": 2, "explain": "Stereotypes can limit what learners believe they can achieve.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "What is a sense of belonging in a school?", "options": ["Being alone in class", "Being removed from lessons", "Being moved to another city", "Feeling accepted and valued"], "answer": 3, "explain": "A sense of belonging helps learners engage and stay in school.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "What does universal access mean for disability?", "options": ["Access for everyone, including people with disabilities", "Access only for people without disabilities", "Access only in one building", "Access only on special days"], "answer": 0, "explain": "Universal access means education is open to all, with the support each person needs.", "src": "UN CRPD (2006), Article 24"}], "10": [{"ch": 0, "q": "Which principle means Agenda 2030 aims to reach the furthest behind first?", "options": ["Leave no one behind", "Survival of the fittest", "Growth at any cost", "Each country for itself"], "answer": 0, "explain": "Leave no one behind means prioritising the most disadvantaged people.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Which SDG 4 indicator tracks participation in organised learning one year before primary school?", "options": ["Indicator 4.1.1", "Indicator 4.2.2", "Indicator 4.5.1", "Indicator 4.7.1"], "answer": 1, "explain": "Indicator 4.2.2 measures participation in organised learning one year before the official primary entry age.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "What is the purpose of Targets 4.a to 4.c?", "options": ["To set exam questions", "To pick school colours", "To provide the means to deliver education", "To close universities"], "answer": 2, "explain": "These targets focus on facilities, scholarships and teacher supply.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "Why are SDG 4 targets measured with indicators and data?", "options": ["To make reports longer", "To avoid making decisions", "To replace teachers", "To check whether progress is real and fair"], "answer": 3, "explain": "Indicators and disaggregated data show progress and inequality.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What is the relationship between SDG 4 and SDG 1 (No Poverty)?", "options": ["Education helps reduce poverty and poverty limits education", "They have no link to each other in any country at all", "Education causes poverty and makes families poorer each year", "Poverty only affects how well children play sport at school"], "answer": 0, "explain": "Education and poverty are closely linked in both directions.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What is a baseline in SDG monitoring?", "options": ["The finishing line that marks the end of a long race", "The starting point against which progress is measured", "The bottom of a school bag where old books are kept", "The price of a brand new textbook in the local shop"], "answer": 1, "explain": "A baseline is the starting data used to measure change.", "src": "UN SDG Report 2026"}, {"ch": 1, "q": "What is compulsory education?", "options": ["Education that is optional for everyone", "Education that is only for adults", "Education that the law requires children to attend", "Education that is banned"], "answer": 2, "explain": "Compulsory education means children must attend school up to a legal age.", "src": "UNESCO"}, {"ch": 1, "q": "What is a conditional cash transfer for education?", "options": ["Money given to teachers for holidays", "Money paid for school fees by donors only", "Money used to build roads only", "Money given to families if children attend school"], "answer": 3, "explain": "Conditional cash transfers encourage families to send children to school.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Why do governments remove school fees?", "options": ["To widen access for poor families", "To reduce the number of pupils", "To make schools less useful", "To stop teacher pay"], "answer": 0, "explain": "Removing fees helps poorer children enrol and stay.", "src": "UNESCO"}, {"ch": 1, "q": "Who are out-of-school adolescents?", "options": ["Adults who study online from home on a regular basis", "Young people of secondary age who are not in school", "Children in kindergarten who play in the garden all day", "Teachers who are on leave from their school this year"], "answer": 1, "explain": "Out-of-school adolescents are teenagers who are not enrolled in school.", "src": "UNESCO"}, {"ch": 1, "q": "What is flexible schooling for children?", "options": ["Schooling with no rules or timetable at all for the children", "Schooling only at night for everyone in the whole town", "Schooling arranged around children's work or family needs", "Schooling with no teachers present in the room at any time"], "answer": 2, "explain": "Flexible schooling helps children who cannot attend full time.", "src": "UNESCO"}, {"ch": 1, "q": "Why is safe transport important for girls' access to school?", "options": ["Transport is never needed for any school trip", "Girls cannot travel anywhere outside their home", "Girls prefer walking very far to reach school", "Unsafe or long journeys can keep girls at home"], "answer": 3, "explain": "Safe transport can make a big difference to girls' attendance.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "What is an enrolment drive?", "options": ["A campaign to get children into school", "A car race", "A school fundraising dinner only", "A sports tournament"], "answer": 0, "explain": "Enrolment drives encourage families to register children for school.", "src": "UNESCO"}, {"ch": 2, "q": "What does lower secondary completion mean?", "options": ["Finishing kindergarten", "Finishing the first stage of secondary school", "Finishing university", "Finishing a holiday course"], "answer": 1, "explain": "Lower secondary is the first stage of secondary education.", "src": "UNESCO"}, {"ch": 2, "q": "Why do adolescents drop out in many countries?", "options": ["They finish school too quickly and early each year", "They all win scholarships to the best schools", "Work pressure, cost and learning that feels irrelevant", "They get far too many holidays and free days during term"], "answer": 2, "explain": "Work pressure, cost and learning that feels irrelevant often push students out.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "What is a learning pathway for young people who have left school?", "options": ["A route into a shop where goods are sold to customers", "A route with no qualifications at all at the end", "A route that is only open to qualified teachers and staff", "A route back into learning with recognised qualifications"], "answer": 3, "explain": "Pathways help young people return to learning and gain qualifications.", "src": "UNESCO"}, {"ch": 2, "q": "Why is completing upper secondary linked to jobs?", "options": ["It opens more job and training options", "It stops all job opportunities", "It means no further learning", "It only helps artists"], "answer": 0, "explain": "Upper secondary completion widens access to jobs and further study.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "What is a school-based intervention to keep children in school?", "options": ["Closing the school earlier on every single day of the week", "A support action inside the school, such as mentoring", "Removing all lessons from the school timetable each week", "Ignoring students who have been absent from school for weeks"], "answer": 1, "explain": "School-based support helps students who are at risk of leaving.", "src": "UNESCO"}, {"ch": 2, "q": "Why are cash and food support linked to completion?", "options": ["They replace all the teaching that happens in the classroom", "They cause more children to leave school early each year", "They reduce costs that push children out of school", "They make the school day much longer and more tiring"], "answer": 2, "explain": "Support with costs can help children stay until they finish.", "src": "UNESCO"}, {"ch": 2, "q": "Why do some students drop out after repeated exam failure?", "options": ["Exams are never failed", "Failing exams helps students", "Failure is rewarded", "Repeated failure can discourage learners"], "answer": 3, "explain": "Repeated failure without support can make students lose confidence and leave.", "src": "UNESCO"}, {"ch": 3, "q": "What is Teaching at the Right Level?", "options": ["Grouping learners by skill level rather than age", "Teaching only the oldest learners", "Teaching only in English", "Teaching without a plan"], "answer": 0, "explain": "Teaching at the Right Level groups learners by what they can already do.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is foundational learning?", "options": ["Advanced university research in science, law and medicine", "Basic reading, writing and numeracy that support later learning", "Only physical education and sport for the whole school year", "Only art history and the study of ancient painting and sculpture"], "answer": 1, "explain": "Foundational learning is the base for all later education.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Which international study tests reading in primary school?", "options": ["PISA", "TIMSS", "PIRLS", "ICAO Test"], "answer": 2, "explain": "PIRLS, the Progress in International Reading Literacy Study, tests reading in primary school.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What does TIMSS measure?", "options": ["Music and dance", "Sport and fitness", "Cooking skills", "Maths and science achievement"], "answer": 3, "explain": "TIMSS, the Trends in International Mathematics and Science Study, measures maths and science achievement.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is a low-stakes test?", "options": ["A test where results do not decide a student's future", "A test that decides who is expelled", "A test with no questions", "A test used only to hire teachers"], "answer": 0, "explain": "Low-stakes tests help teachers see learning without high pressure.", "src": "UNESCO"}, {"ch": 3, "q": "Why do learning outcomes differ within a country?", "options": ["Only the weather changes results from one school to another", "Income, language, location and gender all play a part", "Only the school colour decides how well pupils perform", "Only the bus timetable decides how well pupils perform"], "answer": 1, "explain": "Learning outcomes are shaped by many social and economic factors.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is cognitive skill in learning?", "options": ["Skills for sleeping soundly through every single night", "Skills for playing football in the school team all year", "Thinking skills like memory, reasoning and problem solving", "Skills for cooking simple meals at home for the family"], "answer": 2, "explain": "Cognitive skills underpin reasoning and learning across subjects.", "src": "UNESCO"}, {"ch": 3, "q": "Why are learning assessments important for policy?", "options": ["They replace schools in every community across the country", "They only give prizes to the very top pupils each year", "They end the need for teachers in every school anywhere", "They show where learning is weakest and needs support"], "answer": 3, "explain": "Assessment data helps governments decide where to invest and support.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "What are the four Cs of 21st century skills?", "options": ["Creativity, critical thinking, communication and collaboration", "Cooking, cleaning, cycling and colouring at school each week", "Calculating, counting, copying and coding in the computer lab", "Cheering, coaching, competing and cooking for the school team"], "answer": 0, "explain": "The four Cs are widely used to describe key skills for modern work and life.", "src": "UNESCO"}, {"ch": 4, "q": "What does STEM stand for?", "options": ["Sports, teaching, exams and music", "Science, technology, engineering and mathematics", "Speaking, theatre, editing and markets", "Sociology, tourism, economics and media"], "answer": 1, "explain": "STEM covers science, technology, engineering and maths.", "src": "UNESCO"}, {"ch": 4, "q": "What is digital safety for learners?", "options": ["Sharing passwords with everyone you meet online each day", "Ignoring online privacy and sharing every single photo", "Protecting personal data and recognising online risks", "Meeting online strangers in person and keeping it secret"], "answer": 2, "explain": "Digital safety helps learners protect their information and stay safe online.", "src": "UNESCO"}, {"ch": 4, "q": "What is an ethical use of technology in learning?", "options": ["Copying others' work without credit", "Harassing classmates online", "Sharing private photos", "Using it honestly, respectfully and with consent"], "answer": 3, "explain": "Ethical technology use respects others and academic honesty.", "src": "UNESCO"}, {"ch": 4, "q": "What is a competency framework?", "options": ["A list of skills and knowledge a learner should gain", "A type of school building with several floors and rooms", "A list of school sports, games and clubs to join", "A plan for exams and tests only, with no other learning"], "answer": 0, "explain": "Competency frameworks set out what learners should be able to do.", "src": "UNESCO"}, {"ch": 4, "q": "Why is entrepreneurship linked to SDG 4?", "options": ["It has no link at all to jobs or to problem solving", "It develops skills for creating jobs and solving problems", "It teaches only sales and shop management for shops", "It stops people from ever getting any work at all"], "answer": 1, "explain": "Entrepreneurship builds initiative and problem solving.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is a skills gap?", "options": ["A gap in a school wall that needs urgent repair this term", "A break between two long lessons on a busy school day", "A mismatch between the skills people have and the jobs need", "A missing exam from the school timetable this term"], "answer": 2, "explain": "Skills gaps make it hard for people to find work and employers to fill jobs.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "Why is TVET important for youth employment?", "options": ["It replaces all academic learning", "It is only for adults", "It is never useful", "It provides practical skills that link to jobs"], "answer": 3, "explain": "TVET gives young people job-ready skills and pathways into work.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What is a gender-based barrier to learning?", "options": ["A rule or norm that makes learning harder for one gender", "A barrier that helps every student learn much better", "A barrier that only affects the teachers at the school", "A barrier that has no real effect on learning at all"], "answer": 0, "explain": "Gender-based barriers include norms and practices that limit learning for girls or boys.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "How can the lack of hygiene facilities affect girls at school?", "options": ["It has no link to school attendance at all in any country", "Girls may miss school without private toilets and hygiene supplies", "It only affects boys who study in the same school", "It is a school subject taught to students in year nine"], "answer": 1, "explain": "Access to hygiene and private toilets helps girls stay in school.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What does a child labour policy aim to do?", "options": ["Force children to work long hours in the fields every day", "Stop all education for children in the village and town", "Protect children from work that harms learning and health", "Pay children to skip school and stay at home each day"], "answer": 2, "explain": "Child labour policies protect children's right to learn and be healthy.", "src": "UNESCO"}, {"ch": 5, "q": "What does a minority group in education mean?", "options": ["A group that is always the richest", "A group that is always the best at exams", "A group that never attends school", "A group that is smaller than the main population"], "answer": 3, "explain": "A minority group is a smaller group within a population, which may face barriers.", "src": "UNESCO"}, {"ch": 5, "q": "Why do indigenous learners often need culturally relevant education?", "options": ["It respects their identity and improves learning", "It replaces their language with another one entirely", "It is not needed in any school at all anywhere", "It only affects the sport and games played in school"], "answer": 0, "explain": "Culturally relevant education helps indigenous learners feel valued and learn better.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What is targeting in equity policy?", "options": ["Giving resources to the richest", "Focusing resources on groups who are left behind", "Giving the same resources to the strongest only", "Ignoring groups in need"], "answer": 1, "explain": "Targeting focuses effort on the groups most in need.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What is a gender-sensitive curriculum?", "options": ["A curriculum for boys only, taught in every school", "A curriculum that teaches stereotypes about girls and boys", "A curriculum that avoids stereotypes and treats all learners equally", "A curriculum with no subjects at all for any pupils"], "answer": 2, "explain": "Gender-sensitive curricula challenge stereotypes and support all learners.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What does intersectional discrimination describe?", "options": ["Discrimination in one place only", "Discrimination that is always fair", "Discrimination against teachers only", "Multiple forms of discrimination that overlap"], "answer": 3, "explain": "Intersectional discrimination happens when several identities combine to create disadvantage.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "What is teacher supply in Target 4.c?", "options": ["The number of qualified teachers available", "The number of holidays", "The number of school bells", "The number of desks"], "answer": 0, "explain": "Target 4.c focuses on increasing the supply of qualified teachers.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "Why do countries need to recruit more teachers?", "options": ["Because teachers are not needed", "To meet growing demand and replace those who leave", "To reduce class sizes to zero", "To close schools"], "answer": 1, "explain": "Recruitment is needed to keep pace with growing numbers and retirements.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is contract teaching?", "options": ["Teaching under a lifetime promise", "Teaching with no pay", "Teaching on short, temporary contracts", "Teaching by phone only"], "answer": 2, "explain": "Contract teachers often have less security, which can affect retention.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What does pre-service teacher education mean?", "options": ["Training after retiring", "Training only for principals", "Training for parents", "Training before starting to teach"], "answer": 3, "explain": "Pre-service training prepares people before they start teaching.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What does in-service training mean?", "options": ["Training while already teaching", "Training for people who do not teach", "Training only during holidays by law", "Training that replaces all teaching"], "answer": 0, "explain": "In-service training helps teachers keep improving on the job.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is a teacher code of conduct?", "options": ["A secret teacher language that only staff use", "Rules that set expected professional behaviour", "A list of teacher holidays for the whole year", "A school dress rule that only applies to teachers"], "answer": 1, "explain": "Codes of conduct set out how teachers should behave toward learners.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why do teachers need training in inclusive teaching?", "options": ["It is not needed", "So they can avoid learners", "To support learners with different needs", "So they can teach fewer subjects"], "answer": 2, "explain": "Inclusive training helps teachers meet a range of learner needs.", "src": "UN CRPD (2006), Article 24"}, {"ch": 6, "q": "What is teacher burnout?", "options": ["Teachers who are too energetic", "Teachers who teach too well", "Teachers who are paid too much", "Long-term exhaustion from stressful work"], "answer": 3, "explain": "Burnout reduces wellbeing and can push teachers to leave.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "What does the financing gap for SDG 4 measure?", "options": ["The extra money needed beyond current spending", "Money spent on sports", "Money saved in banks", "Money paid to school sellers"], "answer": 0, "explain": "The financing gap shows how much more is needed to reach education goals.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "What does tax revenue contribute to education?", "options": ["Money that only pays for holidays", "Money that governments use to fund schools", "Money that replaces teachers", "Money that is always wasted"], "answer": 1, "explain": "Tax revenue is a main source of government funding for education.", "src": "UNESCO"}, {"ch": 7, "q": "What is off-budget funding for education?", "options": ["Money spent on holidays", "Money kept under the bed", "Money spent outside the official budget", "Money spent on private jets"], "answer": 2, "explain": "Off-budget funding can make it harder to track total education spending.", "src": "UNESCO"}, {"ch": 7, "q": "Why do donors sometimes fund education?", "options": ["To make a large profit from running schools for children", "To close down schools in the poorest countries each year", "To stop children from learning in any school at all", "To support children in countries with fewer resources"], "answer": 3, "explain": "Donors often fund education to help countries that need extra support.", "src": "UNESCO"}, {"ch": 7, "q": "How can debt affect education spending?", "options": ["High debt repayments can reduce money for schools", "Debt pays for schools automatically", "Debt has no effect at all", "Debt only affects sports"], "answer": 0, "explain": "Governments that spend heavily on debt repayments may have less for education.", "src": "UNESCO"}, {"ch": 7, "q": "What is a value-for-money audit in education?", "options": ["A check on the price and quality of school uniforms", "A check on whether spending achieves good results", "A check on how long each teacher takes off for holidays", "A check on the school food served at lunch each day"], "answer": 1, "explain": "Value-for-money audits check whether education money delivers learning results.", "src": "UNESCO"}, {"ch": 7, "q": "Why do schools need stable funding?", "options": ["So they can change the weather", "So they can avoid all teachers", "So they can plan teachers, materials and repairs", "So they can close early"], "answer": 2, "explain": "Stable funding lets schools plan ahead and keep learning going.", "src": "UNESCO"}, {"ch": 7, "q": "What does a school-level grant do?", "options": ["Gives teachers holidays", "Gives children prizes only", "Gives families cars", "Gives schools money to meet local needs"], "answer": 3, "explain": "School grants let schools respond to local priorities.", "src": "UNESCO"}, {"ch": 8, "q": "Which 1994 statement promoted inclusive schools for all children?", "options": ["The Salamanca Statement", "The Tokyo Declaration", "The Cairo Pact", "The Lima Plan"], "answer": 0, "explain": "The Salamanca Statement of 1994 promoted inclusive schools for all children.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "In which year was the Salamanca Statement adopted?", "options": ["1948", "1994", "1989", "2015"], "answer": 1, "explain": "The Salamanca Statement was adopted in 1994.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "What did the 1990 Jomtien conference call for beyond schooling?", "options": ["Only school for adults", "Only sport", "Learning for children, youth and adults", "No learning after age ten"], "answer": 2, "explain": "Jomtien emphasised learning throughout life for everyone.", "src": "UNESCO"}, {"ch": 8, "q": "How many goals did the Dakar Framework set for Education for All?", "options": ["Three", "Ten", "Seventeen", "Six"], "answer": 3, "explain": "The Dakar Framework set six goals for Education for All.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "What did the 1948 Universal Declaration of Human Rights say about education?", "options": ["It is a human right", "It is a luxury", "It is only for boys", "It is optional"], "answer": 0, "explain": "The UDHR states that education is a human right.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Why was the 1990 Jomtien conference important?", "options": ["It banned all the schools in the entire country", "It set the global commitment to Education for All", "It set the price of books for every shop in town", "It ended teacher training in most countries that year"], "answer": 1, "explain": "Jomtien set the global commitment to Education for All.", "src": "UNESCO"}, {"ch": 8, "q": "What do major global education commitments have in common?", "options": ["They are never followed", "They are only for private schools", "They set goals that governments agree to pursue", "They apply only to one country"], "answer": 2, "explain": "Global commitments set shared goals that governments agree to work towards.", "src": "UNESCO"}, {"ch": 8, "q": "When is International Day of Education?", "options": ["1 May", "31 October", "25 December", "24 January"], "answer": 3, "explain": "UNESCO marks International Day of Education on 24 January each year.", "src": "UNESCO"}, {"ch": 9, "q": "What is the Nurturing Care Framework?", "options": ["A framework bringing together health, nutrition, care and learning in early childhood", "A plan for building schools only in the big cities of the country", "A list of school rules and punishments for young children", "A plan for sports and games in the playground each week"], "answer": 0, "explain": "The framework links health, nutrition, responsive care, safety and learning in early childhood.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "What does brain architecture mean in early childhood?", "options": ["The shape of a school building", "The way brain connections form in early life", "The design of school desks", "The layout of a city"], "answer": 1, "explain": "Early experiences shape the connections that form the brain's architecture.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is parental engagement in early learning?", "options": ["Parents never attending any school events at all", "Parents paying teachers to teach their children privately", "Parents taking an active part in children's learning", "Parents avoiding their children and their schoolwork entirely"], "answer": 2, "explain": "Engaged parents support learning at home and at school.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is play and exploration in the early years?", "options": ["Sitting still for hours with no movement at all in class", "Copying from the board for the whole of every lesson", "Silent drills repeated over and over every day at school", "Hands-on activity that helps children discover ideas"], "answer": 3, "explain": "Play and exploration help children learn about the world.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What makes early childhood education high quality?", "options": ["Trained staff, good spaces and warm interactions", "Large classes with no adults in the room", "Only worksheets handed out with no teaching", "Long silent hours with no adults or activities"], "answer": 0, "explain": "Quality depends on skilled staff, safe spaces and warm relationships.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "What is attachment in early childhood?", "options": ["A type of toy", "A secure bond between a child and caregiver", "A fixed school timetable", "A tax on families"], "answer": 1, "explain": "Secure attachment supports children's emotional and social development.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What does school readiness include beyond academic skills?", "options": ["Only reading words aloud in a loud voice each day", "Only writing letters and numbers on paper for hours", "Health, emotional wellbeing and social skills", "Only physical strength and speed in races each term"], "answer": 2, "explain": "Readiness includes health, social and emotional skills as well as academic ones.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "What is a literacy environment at home?", "options": ["Silent rooms with no books", "Television only", "No family contact", "Books, talk and a reading routine at home"], "answer": 3, "explain": "A literacy environment at home supports reading skills.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "What is a reading culture?", "options": ["Shared habits and value placed on reading", "A type of dance performed in school halls", "A form of sport played on the school field", "A school bell system used all through the day"], "answer": 0, "explain": "A reading culture makes reading part of everyday life.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "Why do adults with low literacy find it hard to get work?", "options": ["Jobs never need reading", "Many jobs need reading and writing skills", "Adults cannot find jobs anyway", "Employers prefer illiteracy"], "answer": 1, "explain": "Low literacy can limit access to many jobs and training.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "What is post-primary literacy?", "options": ["Literacy before birth", "Literacy only in kindergarten", "Literacy skills after primary school", "Literacy only for teachers"], "answer": 2, "explain": "Post-primary literacy builds and maintains reading and writing after primary school.", "src": "UNESCO"}, {"ch": 10, "q": "What is one cause of a reading difficulty?", "options": ["A type of diet", "A type of exam", "A type of weather", "Dyslexia"], "answer": 3, "explain": "Some reading difficulties are caused by dyslexia, which needs specialist support.", "src": "UN CRPD (2006), Article 24"}, {"ch": 10, "q": "What helps rural communities get access to books?", "options": ["Libraries nearby or book delivery", "Banning books", "Selling books at very high prices", "Keeping books only in cities"], "answer": 0, "explain": "Book access in rural areas can be improved through libraries and mobile services.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "What is a mobile library?", "options": ["A library in a car park only", "A library that travels to communities", "A library that sells mobile phones", "A library closed to the public"], "answer": 1, "explain": "Mobile libraries bring books to people who live far from libraries.", "src": "UNESCO"}, {"ch": 11, "q": "What does Article 24 of the UN CRPD cover?", "options": ["Sports and games for all the students", "Cooking and food for families at home", "Education, including inclusive education", "Holidays and tourism for school groups"], "answer": 2, "explain": "Article 24 of the UN CRPD sets out the right to inclusive education.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What does accessibility mean for schools?", "options": ["Only one door at the front of the building for everyone", "Materials that only the teachers are allowed to read", "Information kept secret from the families of pupils", "Buildings, materials and information that everyone can use"], "answer": 3, "explain": "Accessibility makes school spaces and information usable by all.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is inclusive pedagogy?", "options": ["Teaching methods designed to include every learner", "Teaching only the top learners in each class every day", "Teaching in one fixed way that suits all the learners", "Teaching without any materials or resources in the room"], "answer": 0, "explain": "Inclusive pedagogy adapts teaching so all learners participate and learn.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Why do schools need support staff for inclusion?", "options": ["Support staff are not needed", "To help learners access lessons and daily life", "To replace all teachers", "To keep learners apart"], "answer": 1, "explain": "Support staff help learners with disabilities take part in school.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is the least restrictive environment?", "options": ["The most crowded classroom in the whole school building", "The room farthest away from all the other classrooms", "The setting where a learner can learn with the most inclusion", "The room with no windows, no light and no seats"], "answer": 2, "explain": "The least restrictive environment supports learning with as much inclusion as possible.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What does full participation mean for learners with disabilities?", "options": ["Attending only on special days", "Watching from outside", "Being kept in a separate room", "Taking part equally in all parts of school life"], "answer": 3, "explain": "Full participation means learners can join in all activities and learning.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is the social model of disability?", "options": ["Disability is shaped by barriers in society", "Disability is a personal fault", "Disability can be ignored in schools", "Disability only affects work"], "answer": 0, "explain": "The social model says barriers in society, not impairment alone, limit participation.", "src": "UN CRPD (2006), Article 24"}, {"ch": 0, "q": "What is the link between SDG 4 and SDG 5 (Gender Equality)?", "options": ["They have no link", "Girls' education supports gender equality", "Gender equality reduces learning", "Girls should not study"], "answer": 1, "explain": "Education is a key tool for gender equality, which is Goal 5.", "src": "UN 2030 Agenda (2015)"}], "11": [{"ch": 0, "q": "How does Agenda 2030 describe the relationship between the goals?", "options": ["Integrated and indivisible", "Separate and unrelated", "Competing and conflicting", "Optional and ignored"], "answer": 0, "explain": "The 2030 Agenda describes the goals as integrated and indivisible.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What does a national education monitoring system provide?", "options": ["Only holiday dates for every school in the year", "Regular data to track progress and identify gaps", "Only exam prizes for the top students in each class", "Only building designs for new schools in the town"], "answer": 1, "explain": "Monitoring systems collect data so governments can see progress and gaps.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "What is an EMIS?", "options": ["An electronic music instrument set used in school bands", "An exam marking tool used only by teachers at the end", "An education management information system that collects school data", "An energy management plan for all the school buildings"], "answer": 2, "explain": "EMIS stands for education management information system, which records school and learner data.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "What is policy coherence for sustainable development?", "options": ["Each sector ignores the others and works completely alone", "Policies that conflict with each other on purpose each year", "Policies that stop exactly at the borders of each district", "Aligning policies across sectors so they support each other"], "answer": 3, "explain": "Policy coherence means different policy areas work together toward the same goals.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What does SDG 4 localisation mean?", "options": ["Adapting the goals to local priorities and contexts", "Copying one country's plan exactly", "Ignoring local needs", "Moving schools to the moon"], "answer": 0, "explain": "Localisation helps communities adapt global goals to their own situation.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What is accountability in education policy?", "options": ["Avoiding all responsibility for the results of the school", "Holding leaders responsible for results and spending", "Hiding results from the public and from the press", "Blaming learners alone for every single failure in class"], "answer": 1, "explain": "Accountability means leaders answer for how education resources are used.", "src": "UNESCO"}, {"ch": 0, "q": "What is multi-stakeholder engagement in education?", "options": ["Involving only government officials in every single decision", "Involving only private companies and their business staff", "Involving government, families, teachers and communities", "Involving no one but the students in every decision made"], "answer": 2, "explain": "Multi-stakeholder approaches bring many groups together to plan and monitor education.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "What is a sector plan in education?", "options": ["A plan only for sports fields and playgrounds in each town", "A timetable for one school in one district for one term", "A list of holiday dates for the whole country each year", "A plan that sets out priorities and actions for education"], "answer": 3, "explain": "Sector plans guide how governments invest and act across education.", "src": "UNESCO"}, {"ch": 1, "q": "What is an out-of-school survey?", "options": ["A survey that finds children who are not in school", "A survey of school buses on all the main roads in town", "A survey of teachers' holidays across the whole country", "A survey of school uniforms worn in every town each year"], "answer": 0, "explain": "Out-of-school surveys help governments locate children who need to be enrolled.", "src": "UNESCO"}, {"ch": 1, "q": "Why does universal access require more than building schools?", "options": ["Building schools is always enough on its own for everyone", "Cost, distance, discrimination and quality also matter", "Access depends only on the weather in each season", "Access is never a problem for any family in any region"], "answer": 1, "explain": "Access depends on many factors, not only the number of school buildings.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What is age-appropriate enrolment?", "options": ["Children enrolled in any grade regardless of age", "Children never enrolled", "Children enrolled in the grade that matches their age", "Children enrolled only in college"], "answer": 2, "explain": "Age-appropriate enrolment helps children learn at a suitable level.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What is an over-age learner?", "options": ["A teacher who is too old to teach in any classroom now", "A learner who finished the grade early and left school", "A learner with no birthday recorded anywhere in the file", "A learner older than the normal age for their grade"], "answer": 3, "explain": "Over-age learners often need flexible programmes to catch up.", "src": "UNESCO"}, {"ch": 1, "q": "What is remote learning during school closures?", "options": ["Learning from a distance using technology or materials", "Learning only in the same room as the teacher every day", "Learning only through silence and no talking at all", "Learning only at night when the schools are closed"], "answer": 0, "explain": "Remote learning keeps education going when schools cannot open.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Why do school closures harm learning?", "options": ["They have no effect", "Children lose time and may fall behind", "They always improve learning", "They only affect teachers"], "answer": 1, "explain": "Long closures can cause learning loss, especially for disadvantaged children.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What is digital inclusion for learners?", "options": ["Avoiding all technology in daily life and in every study task", "Using only paper and pencils for all lessons every day", "Access to devices, connectivity and the skills to use them", "Owning a car and driving it to school with friends each day"], "answer": 2, "explain": "Digital inclusion means everyone can access and use digital learning tools.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "Why do some learners struggle to study at home?", "options": ["They prefer to be bored", "Home is always ideal", "They do not want to learn", "No quiet space, devices or support at home"], "answer": 3, "explain": "Home conditions affect how well learners can study from a distance.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "What does continuation mean between grades?", "options": ["Moving from one grade to the next without leaving school", "Repeating the same grade forever without ever moving on", "Leaving school permanently and never returning to any class", "Switching to a new school in another country each year"], "answer": 0, "explain": "Continuation means learners move through grades steadily.", "src": "UNESCO"}, {"ch": 2, "q": "What is a dropout prevention policy?", "options": ["Measures that expel learners", "Measures that keep at-risk learners in school", "Measures that close schools", "Measures that ignore absences"], "answer": 1, "explain": "Dropout prevention policies focus on early support for learners at risk.", "src": "UNESCO"}, {"ch": 2, "q": "What does a completion gap between girls and boys show?", "options": ["Which group is taller on average in each school each year", "Which group reads faster during each lesson in class", "Whether one group is less likely to finish school", "Which group likes sport much more than the others"], "answer": 2, "explain": "Completion gaps reveal inequalities that need targeted policy.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 2, "q": "What is a reintegration programme for former learners?", "options": ["A programme that sends learners to work abroad", "A programme that ends schooling", "A programme for teachers only", "A programme that helps former learners return to school"], "answer": 3, "explain": "Reintegration programmes support learners to rejoin education.", "src": "UNESCO"}, {"ch": 2, "q": "What does good transition policy do for learners moving between systems?", "options": ["Makes moves between schools or levels smoother", "Makes moves much harder for every learner", "Stops all moves between schools and levels", "Cancels exams at the end of each school year"], "answer": 0, "explain": "Good transition policy reduces the risk that learners drop out between levels.", "src": "UNESCO"}, {"ch": 2, "q": "What is early tracking in schools?", "options": ["Tracking children with GPS only", "Splitting learners into separate paths at a young age", "Teaching all children the same at all ages", "Recording the weather"], "answer": 1, "explain": "Early tracking can limit later opportunities and widen inequality.", "src": "UNESCO"}, {"ch": 2, "q": "Why is streaming a concern for equity?", "options": ["It always helps the weakest learners", "It has no effect on equity", "It can lock disadvantaged learners into lower paths", "It makes learning easier for all"], "answer": 2, "explain": "Early streaming may reinforce disadvantage if it is not flexible.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "What does the phrase completion is not enough mean?", "options": ["Completion is the only goal", "Learning does not matter", "Schools should close early", "Learning quality must also be ensured"], "answer": 3, "explain": "Finishing school is important, but learners also need to learn well.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is value-added in learning measurement?", "options": ["The progress a school adds beyond what learners started with", "The money a school adds to its annual budget each year", "The weight of all the books kept on the school shelves", "The number of teachers a school hires in each and every year"], "answer": 0, "explain": "Value-added measures how much a school helps learners progress.", "src": "UNESCO"}, {"ch": 3, "q": "What is a learning gap linked to family income called?", "options": ["A weather gap", "A socio-economic learning gap", "A sports gap", "A shoe gap"], "answer": 1, "explain": "Learning gaps linked to family income show unequal opportunities.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "Why do countries benchmark their learning results?", "options": ["To avoid teaching", "To rank teachers by height", "To compare progress and set realistic targets", "To punish learners"], "answer": 2, "explain": "Benchmarking helps countries compare results and learn from each other.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What does learning in the mother tongue support?", "options": ["Only writing in English", "Only singing", "No learning", "Understanding and early reading"], "answer": 3, "explain": "Mother tongue instruction helps learners understand and build early reading skills.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "What is curriculum alignment with assessment?", "options": ["Tests that measure what the curriculum teaches", "Tests that never match lessons", "Tests that cover topics not taught", "Tests that are never marked"], "answer": 0, "explain": "Good alignment makes sure tests measure the learning the curriculum intends.", "src": "UNESCO"}, {"ch": 3, "q": "What is learning analytics?", "options": ["Counting the number of desks", "Using data about learning to improve teaching", "Guessing the weather", "Selling data to companies"], "answer": 1, "explain": "Learning analytics uses data to understand learning and guide support.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "What is metacognition?", "options": ["Thinking only about sport", "Forgetting all thoughts", "Thinking about your own thinking", "Thinking in one language only"], "answer": 2, "explain": "Metacognition helps learners plan, monitor and improve their learning.", "src": "UNESCO"}, {"ch": 3, "q": "What is deep learning in education?", "options": ["Learning as deeply as possible in a pool", "Memorising without understanding", "Learning only in dark rooms", "Understanding ideas well enough to apply them"], "answer": 3, "explain": "Deep learning goes beyond memorising to understanding and applying ideas.", "src": "UNESCO"}, {"ch": 4, "q": "What is employability in education?", "options": ["The skills that help people find and keep work", "Being unable to work in any job or trade", "Owning a company but never doing any work", "Avoiding every kind of job for your whole life"], "answer": 0, "explain": "Employability combines skills, knowledge and attitudes that support work.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is labour market relevance of education?", "options": ["Learning that ignores jobs entirely", "Learning that matches the skills the economy needs", "Learning only for artists", "Learning that never changes"], "answer": 1, "explain": "Relevant education prepares learners for work that exists or is emerging.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is an apprenticeship?", "options": ["A type of school exam taken at the end of each year", "A holiday for teachers taken in the middle of each term", "Learning a job while working under an experienced person", "A kind of school uniform worn for every single lesson each day"], "answer": 2, "explain": "Apprenticeships combine on-the-job training with formal learning.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is digital competence for teachers and learners?", "options": ["Avoiding all technology", "Using only paper", "Breaking computers", "Using digital tools safely and effectively"], "answer": 3, "explain": "Digital competence helps people use technology to learn, work and communicate.", "src": "UNESCO"}, {"ch": 4, "q": "What is artificial intelligence literacy?", "options": ["Understanding what AI can and cannot do", "Believing AI is always correct", "Refusing to learn about AI", "Thinking AI replaces all thinking"], "answer": 0, "explain": "AI literacy helps learners use AI responsibly and question its outputs.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What does a lifelong learning policy aim to do?", "options": ["End all learning once the school years are finished", "Create opportunities to learn at every stage of life", "Limit all learning to only the young people in town", "Stop all adult education programmes across the country"], "answer": 1, "explain": "Lifelong learning policies support learning from childhood through old age.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is recognition of skills gained informally?", "options": ["Ignoring all skills learned at work over many years", "Only counting marks from written school exams every year", "Giving formal credit for skills learned outside school", "Removing certificates that people have already earned at work"], "answer": 2, "explain": "Recognition helps people use skills learned through work and community life.", "src": "UNESCO"}, {"ch": 4, "q": "What is innovation in education?", "options": ["Keeping old methods forever", "Copying old textbooks", "Stopping all new ideas", "New ideas that improve learning"], "answer": 3, "explain": "Innovation in education introduces new approaches that improve learning.", "src": "UNESCO"}, {"ch": 5, "q": "What is gender-responsive budgeting in education?", "options": ["Budgets that consider the needs of girls and boys", "Budgets that ignore gender completely in every decision", "Budgets only for boys in each school in the district", "Budgets only for teachers and their pay and holidays"], "answer": 0, "explain": "Gender-responsive budgeting plans money to meet different needs.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What is girls' retention in secondary school?", "options": ["Keeping girls out of school", "Keeping girls enrolled until they finish", "Keeping girls in one class", "Keeping girls at home"], "answer": 1, "explain": "Retention for girls means they stay in school until completion.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What does social protection for poor families do?", "options": ["Takes children away from their families and their homes", "Adds new school fees for every poor family in the area", "Helps families cope with shocks and keep children in school", "Stops free school meals for poor children each day"], "answer": 2, "explain": "Social protection can help families keep children in school during hard times.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What is child poverty?", "options": ["Having too many toys", "Being too tall", "Being too clever", "Living in poverty during childhood"], "answer": 3, "explain": "Child poverty limits access to food, health, housing and learning.", "src": "UNESCO"}, {"ch": 5, "q": "What is ethnic segregation in schools?", "options": ["Learners from different ethnic groups are separated", "All learners share one playground", "All learners share one language", "All learners wear the same uniform"], "answer": 0, "explain": "Segregation separates learners and limits shared learning and understanding.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "Why should policies reach nomadic and mobile communities?", "options": ["They never need any school at all and do not want it", "They often miss out on schooling without flexible options", "They are always rich and have no needs for schooling", "They prefer to have no school at all in their whole life"], "answer": 1, "explain": "Mobile communities need flexible schooling to reach education.", "src": "UNESCO"}, {"ch": 5, "q": "What is an affirmative quota in education?", "options": ["A quota that bans disadvantaged groups", "A quota only for teachers", "A set share of places reserved for disadvantaged groups", "A quota for sport only"], "answer": 2, "explain": "Quotas can help disadvantaged learners access places they might otherwise miss.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What does equal access mean for girls in conflict zones?", "options": ["Closing all girls' schools", "Sending girls away from home", "Ignoring girls' needs", "Safe, protected routes and schools"], "answer": 3, "explain": "Protected spaces and safe routes help girls keep learning in conflict.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "What is a common cause of teacher attrition?", "options": ["Low pay, poor conditions and lack of career growth", "Too many promotions and rapid career growth for everyone", "High job security and long-term contracts for all staff", "Long holidays and short working hours for every teacher"], "answer": 0, "explain": "Teachers leave when pay, conditions and career prospects are weak.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is teacher quality assurance?", "options": ["Systems that remove all teachers", "Systems that check teaching meets set standards", "Systems that set teacher holidays", "Systems that ignore students"], "answer": 1, "explain": "Quality assurance helps keep teaching at a high standard.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is teacher appraisal?", "options": ["A test of teachers' running speed on the school track", "A ranking of teachers by their height in the staff room", "A review of a teacher's performance to support improvement", "A check of teachers' holiday plans for the whole summer"], "answer": 2, "explain": "Appraisal helps teachers reflect and improve, when done fairly.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is a teacher education curriculum?", "options": ["A school timetable for children", "A list of school uniforms", "A menu for school meals", "The subjects and skills taught to future teachers"], "answer": 3, "explain": "Teacher education curricula prepare teachers in subjects and pedagogy.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why do teachers need training in assessment?", "options": ["To judge learning accurately and support it", "So they can avoid grading", "So they can stop tests", "So they can grade without evidence"], "answer": 0, "explain": "Assessment training helps teachers use evidence to support learners.", "src": "UNESCO GEM Report 2026"}, {"ch": 6, "q": "What is teacher agency?", "options": ["Teachers who obey all orders without thought", "Teachers' ability to shape their own practice", "Teachers who never plan", "Teachers who work only at night"], "answer": 1, "explain": "Teacher agency means teachers can make decisions that improve learning.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is a teacher professional learning community?", "options": ["A group that competes to get the most holidays", "A club that sells teaching materials only", "Teachers learning together to improve practice", "A group of students who teach"], "answer": 2, "explain": "Learning communities help teachers share ideas and improve together.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What does a teacher's sense of purpose affect?", "options": ["Only the price of chalk", "Only school building costs", "Nothing important", "Motivation and commitment to learners"], "answer": 3, "explain": "Purpose and commitment influence how teachers engage with learners.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "What is a public-private partnership in education?", "options": ["Cooperation between governments and private providers", "Private companies running all schools by law", "Governments giving up all duties", "Schools paying governments"], "answer": 0, "explain": "Partnerships can expand provision but must be regulated for quality and equity.", "src": "UNESCO"}, {"ch": 7, "q": "What is regulation of private schools?", "options": ["Banning all private schools by default in the national law", "Rules ensuring private schools meet quality and safety standards", "Letting private schools write and set their own laws freely", "Ignoring private schools completely and never checking them"], "answer": 1, "explain": "Regulation protects learners in private schools.", "src": "UNESCO"}, {"ch": 7, "q": "What is fiscal space for education?", "options": ["Space for building new cars and trucks in the town centre", "Space in the school hallways for new lockers and benches", "Room in a government's budget to increase spending", "Space for holiday camps in the countryside each summer"], "answer": 2, "explain": "Fiscal space is the flexibility a government has to fund education.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "What is tax expenditure on education?", "options": ["Money spent on school exams, marking and printing each year", "Money spent on teacher holidays and time off each year", "Money spent on sports equipment and school games each term", "Tax reliefs that reduce government revenue for education"], "answer": 3, "explain": "Tax expenditures are reliefs that can reduce the money available for education.", "src": "UNESCO"}, {"ch": 7, "q": "What is cost-effectiveness in education?", "options": ["Achieving learning gains for the lowest cost", "Spending as much as possible", "Spending only on buildings", "Avoiding all spending"], "answer": 0, "explain": "Cost-effective programmes achieve more learning for each unit of money.", "src": "UNESCO"}, {"ch": 7, "q": "What is a fee waiver?", "options": ["A fee for late enrolment at the school for new families", "An exemption from school fees for families who cannot pay", "A bonus paid to teachers for good work each season", "A charge for riding the school bus for the whole term"], "answer": 1, "explain": "Fee waivers help poor families keep children in school.", "src": "UNESCO"}, {"ch": 7, "q": "What is budget credibility in education?", "options": ["Money is never spent on schools at all in the whole year", "Budgets are made in secret by a few people each year", "Planned education money is actually spent on schools", "Budgets change every single hour without any clear reason"], "answer": 2, "explain": "Budget credibility means the planned education money is delivered.", "src": "UNESCO"}, {"ch": 7, "q": "What role can parent-teacher associations play in school funding?", "options": ["Paying all teacher salaries alone", "Replacing government funding entirely", "Closing the school", "Raising money or support to help school needs"], "answer": 3, "explain": "Parent associations can help schools, though they should not replace public funding.", "src": "UNESCO"}, {"ch": 8, "q": "Which 2006 convention is about persons with disabilities?", "options": ["The UN Convention on the Rights of Persons with Disabilities", "The Geneva Convention on international trade and tariffs", "The Tokyo Agreement on sport and the training of athletes", "The Lima Convention on farming, food and land use"], "answer": 0, "explain": "The CRPD was adopted in 2006 and includes education rights.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "In which year was the CRPD adopted?", "options": ["1994", "2006", "1989", "2015"], "answer": 1, "explain": "The UN CRPD was adopted in 2006.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "What does Article 29 of the Convention on the Rights of the Child say about education?", "options": ["Education should be expensive", "Education should be only for boys", "Education should develop each child's personality and talents", "Education should be banned for children with disabilities"], "answer": 2, "explain": "Article 29 sets out the aims of education, including respect for rights and culture.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "What is the common short form for Education for All?", "options": ["ELA", "EAL", "EFR", "EFA"], "answer": 3, "explain": "EFA is the common short form for Education for All.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "What did the 2015 Incheon Declaration say about lifelong learning?", "options": ["It should be part of education for all ages", "It should end at age 14", "It should be banned", "It should apply only to teachers"], "answer": 0, "explain": "The Incheon Declaration promoted lifelong learning opportunities for all.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Which body publishes global data on education?", "options": ["World Football Association", "UNESCO Institute for Statistics", "International Hotel Council", "Global Music Fund"], "answer": 1, "explain": "The UNESCO Institute for Statistics publishes global education data.", "src": "UNESCO GEM Report 2026"}, {"ch": 8, "q": "What is the link between the MDGs and the SDGs?", "options": ["The SDGs replaced nothing", "The SDGs cancelled all goals", "The SDGs built on lessons from the MDGs", "The MDGs are still in force"], "answer": 2, "explain": "The SDGs built on the MDGs and expanded the agenda.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "What was the Global Partnership for Education founded to do?", "options": ["Sell textbooks worldwide", "Organise sports events", "Fund space travel", "Support education in low-income countries"], "answer": 3, "explain": "The Global Partnership for Education supports low-income countries to improve learning.", "src": "UNESCO GEM Report 2026"}, {"ch": 8, "q": "What did the Universal Declaration of Human Rights say about parents and education?", "options": ["Parents have a prior right to choose the education for their children", "Parents have no role at all in their children's schooling", "Parents must choose only sport and games for their children", "Parents must pay for all of the schools in their town"], "answer": 0, "explain": "Article 26 says parents have a prior right to choose the kind of education for their children.", "src": "UN General Assembly (1948)"}, {"ch": 9, "q": "What is early childhood education and care (ECEC)?", "options": ["Adult education and training courses for working people only", "Learning and care services for young children before primary school", "Teacher training courses for new teachers in the country", "Secondary school exams and final assessments for all pupils"], "answer": 1, "explain": "ECEC covers services that support young children's development and learning.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "What is a multi-sector approach in early childhood?", "options": ["Only education working alone in each school and classroom", "Only health working alone in each local clinic and hospital", "Health, nutrition, education and protection working together", "Only sport working alone in the playground and the field"], "answer": 2, "explain": "Multi-sector approaches address children's needs across services.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is a child-to-staff ratio?", "options": ["The number of toys per child", "The number of windows in a room", "The number of staff on holiday", "The number of children each adult looks after"], "answer": 3, "explain": "Lower ratios allow more attention and interaction with each child.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Why do young children need consistent caregivers?", "options": ["Stable relationships support emotional and cognitive growth", "Consistency is not important for young children at all", "Children prefer many strangers to close family members", "Caregivers should change every single day for variety"], "answer": 0, "explain": "Stable, consistent caregivers help children feel secure and learn.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is early support for children with disabilities?", "options": ["Waiting until school to begin", "Early help to build skills and development", "Keeping children away from others", "Ignoring development needs"], "answer": 1, "explain": "Early intervention helps children with disabilities develop skills sooner.", "src": "UN CRPD (2006), Article 24"}, {"ch": 9, "q": "What is developmental screening?", "options": ["Tests to choose the right school shoes for each pupil", "Exams for teachers to pass at the end of each year", "Quick checks that find children who may need support", "A check for holiday plans at the local school each year"], "answer": 2, "explain": "Screening helps identify children who may need further assessment or help.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is an adverse childhood experience (ACE)?", "options": ["A happy holiday trip with the whole family every summer", "A school prize for good work and effort each term", "A type of exam taken by pupils in primary school each year", "A stressful or harmful event in childhood that can affect development"], "answer": 3, "explain": "ACEs can affect health and learning, which makes early support important.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "What is a national literacy strategy?", "options": ["A plan to improve literacy across a country", "A plan to sell newspapers", "A plan to close libraries", "A plan for only one school"], "answer": 0, "explain": "National literacy strategies set goals and actions to raise reading and writing skills.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "What is literacy in a digital age?", "options": ["Avoiding all screens and digital devices in every class", "Reading, writing and understanding information in digital forms", "Reading only paper books and nothing else at any time", "Writing only with a pencil on paper in every subject"], "answer": 1, "explain": "Digital literacy extends reading and writing into online environments.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "What is an adult literacy survey?", "options": ["A survey of adult holidays and travel plans each year", "A survey of adult cars and their owners in each town", "A survey that measures reading and numeracy in adults", "A survey of adult sports and fitness habits in each town"], "answer": 2, "explain": "Adult literacy surveys measure skills to guide policy.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "Why are libraries important for adult literacy?", "options": ["They are only for children and young pupils in each town", "They sell books only and never lend them to anyone", "They are closed to all adults at all times of the day", "They give free access to books and learning support"], "answer": 3, "explain": "Libraries support adults who want to read, learn and build skills.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "What is linguistic diversity in literacy?", "options": ["The variety of languages used in a community", "Using only one language everywhere", "Banning local languages", "Teaching only sign language"], "answer": 0, "explain": "Linguistic diversity matters because learners read and learn in many languages.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "What is reading engagement among learners?", "options": ["How fast learners walk", "How much learners enjoy and choose to read", "How loud learners speak", "How many books are sold"], "answer": 1, "explain": "Reading engagement shows how motivated learners are to read.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "What is a literacy bridge programme?", "options": ["A programme that builds real bridges across rivers and roads", "A programme that closes libraries across the city each year", "A programme that helps learners move from basic to higher literacy", "A programme for sports and games only, with no reading at all"], "answer": 2, "explain": "Literacy bridge programmes help learners move on from basic reading.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "What is an inclusive education system?", "options": ["A system where learners are separated by disability", "A system with no teachers", "A system with no rules", "A system where all learners are included in mainstream education"], "answer": 3, "explain": "An inclusive system welcomes learners and adapts mainstream education to them.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is non-discrimination in education?", "options": ["Treating learners fairly regardless of disability, gender or background", "Treating learners differently by group in every single school", "Refusing learners entry to the school altogether for their group", "Charging extra fees to some learners based on their background"], "answer": 0, "explain": "Non-discrimination is a basic principle of inclusive education.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is the representation principle of Universal Design for Learning?", "options": ["Presenting only one format", "Presenting information in multiple formats", "Hiding information from learners", "Presenting only in silence"], "answer": 1, "explain": "Multiple means of representation help learners access content in different ways.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Why should learners with disabilities have a voice in decisions?", "options": ["They should never be consulted", "Only adults can decide", "They know their own needs best", "Decisions should be made without them"], "answer": 2, "explain": "Learners with disabilities should be consulted on decisions that affect them.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is learner participation in school decisions?", "options": ["Learners staying silent", "Learners making all decisions alone", "Learners never attending meetings", "Learners taking part in decisions that affect them"], "answer": 3, "explain": "Learner participation builds responsibility and respects learners' rights.", "src": "UN Convention on the Rights of the Child (1989), Article 12"}, {"ch": 11, "q": "What is school climate?", "options": ["The feel of a school for learners and staff", "The temperature inside a school only", "The amount of sunlight in a school", "The number of school buses"], "answer": 0, "explain": "School climate shapes whether learners feel safe, respected and motivated.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "What is an anti-bullying policy?", "options": ["Rules that encourage bullying among pupils in every school", "Rules and actions to stop bullying and protect learners", "Policies that ignore bullying completely in every school", "Policies that punish the victims of bullying each term"], "answer": 1, "explain": "Anti-bullying policies protect learners and support a safe learning environment.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "Why is inclusive education good for society?", "options": ["It creates division", "It reduces learning for all", "It builds fairness and social cohesion", "It is only useful for a few"], "answer": 2, "explain": "Inclusive education builds social cohesion and fairness for everyone.", "src": "UN CRPD (2006), Article 24"}], "12": [{"ch": 0, "q": "What is the Education 2030 Framework for Action mainly?", "options": ["A guide for countries to implement SDG 4", "A sports rulebook for school tournaments", "A banking law for the national bank", "A school dress code for every uniform"], "answer": 0, "explain": "It provides guidance for implementing SDG 4 across countries.", "src": "Incheon Framework for Action (2015)"}, {"ch": 0, "q": "What is the global indicator framework for the SDGs?", "options": ["A set of holiday dates for every school in the year", "An agreed set of indicators to measure progress", "A list of banned books for every school library", "A map showing where all school buildings are located"], "answer": 1, "explain": "The global indicator framework provides common indicators to track SDG progress.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "What do the tier classifications of SDG indicators show?", "options": ["How tall each student is at the start of the year", "How many schools a country has built over time", "How well-established each indicator's methodology is", "How much money a school raises from events each year"], "answer": 2, "explain": "Tiers show the methodological readiness and data availability of indicators.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "Why are SDG 4 indicators disaggregated by wealth?", "options": ["To rank families by height", "To choose school uniforms", "To set holiday dates", "To reveal gaps between rich and poor learners"], "answer": 3, "explain": "Wealth disaggregation shows whether progress reaches poorer learners.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "What does SDG 4 financing tracking measure?", "options": ["How much money is invested and where it goes", "How many trees are planted", "How many sports clubs exist", "How many books are printed"], "answer": 0, "explain": "Financing tracking shows investment levels and whether they reach priority groups.", "src": "Incheon Framework for Action (2015)"}, {"ch": 0, "q": "What is policy evaluation in education?", "options": ["Choosing new school colours", "Assessing whether policies achieve their goals", "Counting school windows", "Writing holiday poems"], "answer": 1, "explain": "Evaluation helps decide whether policies should continue, change or stop.", "src": "UNESCO"}, {"ch": 0, "q": "What is evidence-based policy?", "options": ["Policy made without any data", "Policy made by guessing", "Policy informed by research and data", "Policy copied from films"], "answer": 2, "explain": "Evidence-based policy uses research to guide decisions.", "src": "UNESCO"}, {"ch": 0, "q": "Why do governments need education data systems?", "options": ["To avoid making decisions", "To hide information", "To replace teachers", "To plan, monitor and improve education"], "answer": 3, "explain": "Data systems support planning, monitoring and accountability.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "What does it mean that SDG 4 has synergies with other goals?", "options": ["Progress on education helps progress on other goals", "Education blocks all other goals", "Education has no link to other goals", "Other goals only affect sport"], "answer": 0, "explain": "Education supports health, gender equality, jobs and climate goals.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "What is non-enrolment?", "options": ["Enrolled but not attending", "Being of school age but not enrolled", "Attending school abroad only", "Teaching without pay"], "answer": 1, "explain": "Non-enrolment means school-age children are not registered at school.", "src": "UNESCO"}, {"ch": 1, "q": "What is effective access to education?", "options": ["Access only on paper", "Access without any teachers", "Access that also leads to real learning", "Access for only one day"], "answer": 2, "explain": "Effective access means children attend and learn, not just enrol.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What is a catch-up pathway for children with interrupted schooling?", "options": ["A route to leave school", "A route to skip grades without learning", "A route that closes schools", "A route that helps them catch up and rejoin"], "answer": 3, "explain": "Catch-up pathways help children who lost schooling rejoin education.", "src": "UNESCO"}, {"ch": 1, "q": "What does the right to education require from states?", "options": ["Making education available, accessible, acceptable and adaptable", "Making education only for the rich families in the country", "Making education only available in the big cities of the country", "Making education completely optional for every single family"], "answer": 0, "explain": "The four A's describe the core obligations of the right to education.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "What does availability mean in the right to education?", "options": ["Schools never open for any students at all during the year", "Functioning schools and programmes exist in sufficient numbers", "Schools only open on weekends and public holidays for families", "Schools are only for the teachers to use on certain days"], "answer": 1, "explain": "Availability means enough functioning institutions and programmes.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "What does acceptability mean in the right to education?", "options": ["Education that is always boring", "Education that is kept secret", "Education that is good quality and culturally appropriate", "Education that is only in one language"], "answer": 2, "explain": "Acceptability means education is relevant, safe and of good quality.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "What does adaptability mean in the right to education?", "options": ["Education that never changes with the needs of the times", "Education that ignores the needs of learners and families", "Education that stays fixed the same forever in every school", "Education that adapts to the needs of learners and society"], "answer": 3, "explain": "Adaptability means education responds to changing needs.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "Why is out-of-pocket spending on education a concern?", "options": ["Families pay costs directly, which can push children out", "Families never pay anything", "Out-of-pocket spending always helps schools", "It only affects teachers"], "answer": 0, "explain": "High out-of-pocket costs can prevent poor families from sending children to school.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "What is a humanitarian education response?", "options": ["Education only in peacetime", "Support for education in emergencies and crises", "A response that closes schools", "A response for sports only"], "answer": 1, "explain": "Humanitarian education responses keep learning going during crises.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "What is a learning pathway from secondary to tertiary education?", "options": ["A route to leave education for good and never return", "A route only for adults who have already left school", "A route from secondary school into further education", "A route into a sports club for every student after school"], "answer": 2, "explain": "Pathways link secondary education to tertiary study and training.", "src": "UNESCO"}, {"ch": 2, "q": "What is tertiary education?", "options": ["Education before kindergarten for toddlers and young children", "Education only for teachers in their training courses", "Education only for sports and athletic training at clubs", "Education after secondary school, such as university or college"], "answer": 3, "explain": "Tertiary education includes universities, colleges and advanced technical training.", "src": "UNESCO"}, {"ch": 2, "q": "What is equity of completion?", "options": ["Completion rates that are similar across groups", "Completion rates that favour only the rich", "Completion rates that are never measured", "Completion rates that are always zero"], "answer": 0, "explain": "Equity of completion means groups finish school at similar rates.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "Who are early leavers from education and training?", "options": ["Young people who leave school early for a holiday", "Young people who leave without completing secondary education", "Teachers who leave early", "Learners who finish first"], "answer": 1, "explain": "Early leavers are young people who leave without a secondary qualification.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "What is a vocational programme at upper secondary level?", "options": ["A course in cooking and baking skills taught only at home", "A university degree in history, law and politics", "A course that gives practical skills and qualifications", "A holiday camp for young children in the summer"], "answer": 2, "explain": "Vocational programmes at upper secondary give practical skills and qualifications.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "Why is completing school important for later life?", "options": ["It has no effect later", "It only affects holidays", "It only affects sport", "It strongly shapes health, jobs and income"], "answer": 3, "explain": "Completing school is linked to better health, employment and wellbeing.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "What is lifelong completion?", "options": ["Completing learning at any age", "Completing learning only before age ten", "Stopping learning after school", "Learning only for teachers"], "answer": 0, "explain": "Lifelong completion means people can finish learning at any age.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "What is reversal of dropout?", "options": ["Learners leaving more quickly", "Learners returning to education after leaving", "Learners moving backwards in exams only", "Learners cutting school fees"], "answer": 1, "explain": "Reversal of dropout means learners re-enter and finish education.", "src": "UNESCO"}, {"ch": 3, "q": "What is the foundational skills target for countries?", "options": ["Ensuring children learn music and singing only throughout primary school", "Ensuring children never learn to read at all in primary school", "Ensuring most children reach basic literacy and numeracy by the end of primary", "Ensuring children skip school and stay at home during primary years"], "answer": 2, "explain": "Many countries aim to ensure children reach basic skills early in primary school.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What does quality in learning mean?", "options": ["Learning that is only fast and rushed through each lesson", "Learning that is only long and tiring for every pupil", "Learning that avoids all exams and tests for every pupil", "Learning that is relevant, effective and equitable"], "answer": 3, "explain": "Quality learning meets learners' needs and leads to real progress.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "What is curriculum relevance?", "options": ["Connecting learning to learners' lives and future work", "Teaching things that are never used", "Ignoring learners' lives", "Teaching only in dead languages"], "answer": 0, "explain": "Relevant curricula link lessons to real life and future needs.", "src": "UNESCO"}, {"ch": 3, "q": "What is outcome-based education policy?", "options": ["Setting targets based on school size", "Setting targets based on what learners can do", "Setting targets based on teacher height", "Setting targets based on holiday length"], "answer": 1, "explain": "Outcome-based policy focuses on the skills and results learners achieve.", "src": "UNESCO"}, {"ch": 3, "q": "What is translanguaging in classrooms?", "options": ["Banning all languages except one at school for every learner", "Using only sign language in every lesson of the school day", "Using all of a learner's languages to support learning", "Teaching only in silence with no talking in any lesson"], "answer": 2, "explain": "Translanguaging uses learners' full language repertoire to help them learn.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "What is cognitive load?", "options": ["The weight of a school bag", "The number of pages in a book", "The amount of sunlight in a room", "The amount of mental effort a task needs"], "answer": 3, "explain": "Cognitive load matters for how learners process and remember information.", "src": "Harvard Center on the Developing Child"}, {"ch": 3, "q": "What is spaced practice?", "options": ["Spreading learning sessions over time to improve memory", "Cramming everything into one single night before the test", "Never practising the same material again at any time", "Only practising during the long school holidays each year"], "answer": 0, "explain": "Spaced practice helps learners remember information better over time.", "src": "UNESCO"}, {"ch": 3, "q": "What is retrieval practice?", "options": ["Copying notes repeatedly without recall", "Recalling information from memory to strengthen learning", "Reading only the title", "Ignoring what was taught"], "answer": 1, "explain": "Retrieval practice strengthens memory by recalling what has been learned.", "src": "UNESCO"}, {"ch": 3, "q": "What is assessment bias?", "options": ["Tests that are always fair", "Tests that never measure learning", "Tests that favour some groups over others unfairly", "Tests that only measure height"], "answer": 2, "explain": "Bias in assessment can disadvantage learners for reasons unrelated to ability.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "What are transversal skills?", "options": ["Skills for one subject only", "Skills for sleeping", "Skills for crossing roads only", "Skills useful across many subjects and jobs"], "answer": 3, "explain": "Transversal skills such as communication and teamwork apply everywhere.", "src": "UNESCO"}, {"ch": 4, "q": "What is digital pedagogy?", "options": ["Teaching methods that use technology well", "Teaching without technology", "Teaching only with broken machines", "Teaching only through silence"], "answer": 0, "explain": "Digital pedagogy uses technology to support learning, not just to replace paper.", "src": "UNESCO"}, {"ch": 4, "q": "What is data privacy in education technology?", "options": ["Sharing learners' data with strangers", "Protecting learners' personal information", "Selling learner data", "Ignoring privacy rules"], "answer": 1, "explain": "Data privacy protects learners from misuse of their personal information.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is upskilling?", "options": ["Learning to lose skills you already have while working", "Learning only for children in primary school each year", "Learning new skills to keep up with changing work", "Ending all training once you start a new job and career"], "answer": 2, "explain": "Upskilling helps workers adapt to new technologies and jobs.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is reskilling?", "options": ["Forgetting all of your skills and knowledge from the past", "Learning only sports and games for fun in your free time", "Stopping work completely and staying at home for good", "Learning new skills to move into a different kind of work"], "answer": 3, "explain": "Reskilling prepares people for new roles when old jobs change.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is green jobs training?", "options": ["Preparing workers for jobs that help the environment", "Training for jobs that harm nature", "Training to paint walls only", "Training to play sport"], "answer": 0, "explain": "Green jobs training prepares people for sustainable work.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is global competence?", "options": ["Ignoring other countries and their people entirely", "Understanding and engaging with the world and other cultures", "Knowing only one country's history and nothing else at all", "Refusing to travel or to meet people from other countries"], "answer": 1, "explain": "Global competence helps learners understand global issues and communicate across cultures.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "What is social-emotional learning (SEL)?", "options": ["Learning to avoid all feelings and emotions in every situation", "Learning only maths and nothing else at school each day", "Learning to manage emotions and relate well to others", "Learning to stay silent in every social setting you enter"], "answer": 2, "explain": "SEL builds self-awareness, empathy and relationship skills.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "What are gender norms?", "options": ["Rules about what children eat for lunch at the school canteen", "Measures of how big each school building is across town", "Rules about holidays only for the teachers and staff members", "Shared expectations about how girls and boys should behave"], "answer": 3, "explain": "Gender norms shape the roles and opportunities of girls and boys.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "How does keeping girls in school relate to child marriage?", "options": ["It is one of the most effective ways to delay child marriage", "It encourages girls to marry at a very young age each year", "It has no link to marriage at any age in any community", "It closes schools for girls in the community each term"], "answer": 0, "explain": "Keeping girls in school is one of the most effective ways to delay child marriage.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What is the impact of teenage pregnancy on schooling?", "options": ["It always improves schooling", "It can interrupt girls' education", "It has no link to school", "It only affects boys"], "answer": 1, "explain": "Pregnancy can interrupt schooling, so re-entry and support policies matter.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What is inclusive sanitation in schools?", "options": ["Toilets only for the teachers and staff at the school", "No toilets or washing facilities at all for any of the pupils", "Toilets and washing facilities that meet everyone's needs", "Toilets that are always locked to students during the day"], "answer": 2, "explain": "Inclusive sanitation includes facilities for girls and for learners with disabilities.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "What does learner poverty include beyond money?", "options": ["Having too many books to read at home each evening", "Having too many friends to play with after school", "Having too much free time to play after school each day", "Lack of food, transport, materials and quiet study space"], "answer": 3, "explain": "Learner poverty includes lacking food, transport, materials and quiet study space.", "src": "UNESCO"}, {"ch": 5, "q": "What is multiple disadvantage?", "options": ["Facing several barriers at once", "Having no barriers", "Only facing one small barrier", "Having too much support"], "answer": 0, "explain": "Multiple disadvantage means several barriers combine and need combined responses.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "What does refugee inclusion in national systems mean?", "options": ["Separating refugee learners permanently", "Including refugee learners in national education systems", "Refusing refugee learners", "Only teaching refugees online"], "answer": 1, "explain": "Inclusion of refugees in national systems helps them access education and recognised qualifications.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "What is nomadic education?", "options": ["Schooling that is always in one building", "Schooling only for city children", "Schooling designed for mobile communities", "Schooling without teachers"], "answer": 2, "explain": "Nomadic education adapts teaching and timing to mobile families.", "src": "UNESCO"}, {"ch": 5, "q": "What does an equity index in education measure?", "options": ["The height of school buildings", "The number of school bells", "The length of teacher holidays", "How access or outcomes compare across groups"], "answer": 3, "explain": "Equity indices summarise how fairly education is distributed.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "What does gender balance among teachers mean?", "options": ["Balanced numbers of women and men among teachers", "Only men are allowed to teach in the schools here", "Only women are allowed to teach in the schools here", "No teachers are needed in any of the schools here"], "answer": 0, "explain": "Gender balance among teachers can influence role models and school culture.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "What is teacher supply and demand analysis?", "options": ["Comparing teachers' favourite colours and clothes each year", "Comparing how many teachers are needed with how many are available", "Counting how many holidays and days off teachers take each year", "Comparing the heights of teachers in the staff room each year"], "answer": 1, "explain": "Supply and demand analysis helps governments plan recruitment.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is teacher education reform?", "options": ["Removing all training", "Ending teacher careers", "Changing how teachers are trained", "Closing teacher colleges only"], "answer": 2, "explain": "Teacher education reform updates training to match modern classrooms.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is school leadership development?", "options": ["Training leaders to avoid teaching in every class they visit", "Training leaders in sport and games only for the school", "Training leaders to close schools early each term", "Training school leaders to guide teaching and learning"], "answer": 3, "explain": "Developing leaders improves school quality.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What does teacher career progression include?", "options": ["Clear steps for growing skills and responsibilities", "No steps at all for the teachers to climb in their career", "Only holidays and long breaks each year for the teachers", "Only pay cuts and fewer staff members each term"], "answer": 0, "explain": "Clear progression helps teachers grow and stay in the profession.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is the teacher-learner relationship?", "options": ["A relationship with no contact", "A positive bond that supports learning", "A business deal only", "A rivalry that stops learning"], "answer": 1, "explain": "Strong relationships help learners feel safe and motivated.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "What is teacher working time?", "options": ["The number of minutes in a school day only", "The time spent on holiday", "The total time a teacher spends on teaching and related work", "The time spent on the bus"], "answer": 2, "explain": "Working time includes planning, marking and other duties beyond classes.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "Why do some teachers need extra support in crisis areas?", "options": ["They face no difficulty", "They never need support", "They have too many holidays", "They face unsafe conditions and trauma"], "answer": 3, "explain": "Teachers in crises may need training and wellbeing support.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "What is education expenditure per student?", "options": ["The average spending on each learner", "The number of books per school", "The cost of one exam", "The cost of one bus route"], "answer": 0, "explain": "Spending per student helps compare resources across systems.", "src": "UNESCO"}, {"ch": 7, "q": "Why can cost-sharing be a concern for access?", "options": ["It always reduces costs for families", "It can push costs onto families who cannot afford them", "It has no impact on access", "It ends all fees"], "answer": 1, "explain": "Cost sharing can create barriers for poorer families if it is not managed.", "src": "UNESCO"}, {"ch": 7, "q": "What is debt relief for education?", "options": ["Increasing debt to fund sports", "Ending all schools", "Reducing debt payments so money can go to schools", "Making teachers pay debt"], "answer": 2, "explain": "Debt relief can free up funds for education.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "What is innovative finance for education?", "options": ["Only paying teachers in gold", "Only selling school desks", "Only closing schools", "New ways to raise money for education"], "answer": 3, "explain": "Innovative finance includes new mechanisms to mobilise funding.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "What is an education financing plan?", "options": ["A plan showing how education will be funded over time", "A plan for school holidays only, with no lessons at all", "A plan for buying cars and vans for the school staff", "A plan with no numbers, costs or dates in it at all"], "answer": 0, "explain": "A financing plan links education goals to the money needed to reach them.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "What is fiscal decentralisation in education?", "options": ["Taking all of the money to the capital city each year", "Giving local governments more control over education money", "Banning local government from making any decisions at all", "Closing local schools one by one until none are left"], "answer": 1, "explain": "Decentralisation can help local responsiveness, but needs equity safeguards.", "src": "UNESCO"}, {"ch": 7, "q": "What is an equalisation grant?", "options": ["Money that makes the rich areas even richer each year", "Money for teachers' holidays and time off only each summer", "Extra funding that helps poorer areas match richer ones", "Money to close schools in the poorer areas each year"], "answer": 2, "explain": "Equalisation grants reduce gaps between regions.", "src": "UNESCO"}, {"ch": 7, "q": "What is a sunset clause in education funding?", "options": ["A clause about sunsets", "A rule for school dance nights", "A rule that doubles funding every day", "A rule that ends funding after a set time unless renewed"], "answer": 3, "explain": "Sunset clauses end programmes unless they are reviewed and renewed.", "src": "UNESCO"}, {"ch": 7, "q": "What is government revenue for education?", "options": ["Money the government collects from taxes and other sources", "Money from sports tickets sold at the national stadium each year", "Money from school fees paid by families only, with no taxes", "Money earned only from holiday tourism and travel each year"], "answer": 0, "explain": "Government revenue is the main base for public education funding.", "src": "UNESCO"}, {"ch": 8, "q": "What did the Salamanca Statement promote?", "options": ["Separate schools only", "Inclusive schools for all children", "Schools for adults only", "Schools for teachers only"], "answer": 1, "explain": "The Salamanca Statement promoted inclusion for children with special needs.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "In which year was the Universal Declaration of Human Rights adopted?", "options": ["1989", "1990", "1948", "2015"], "answer": 2, "explain": "The UDHR was adopted by the UN General Assembly in 1948.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "Which convention sets out children's rights, including education?", "options": ["The Treaty of Trade", "The Geneva Sports Charter", "The Tokyo Shipping Code", "The Convention on the Rights of the Child"], "answer": 3, "explain": "The CRC, adopted in 1989, sets out children's rights including education.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "What did the Dakar goals commit to for early childhood?", "options": ["Expanding and improving early childhood care and education", "Closing early childhood services across the whole country", "Ignoring young children and their families completely", "Banning kindergartens in every town and village"], "answer": 0, "explain": "Dakar goals included expanding and improving early childhood care and education.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "What did the Incheon Declaration aim for by 2030?", "options": ["Only tertiary education for the very top students in each year", "Inclusive, equitable and quality education and lifelong learning", "Only sports and games for every school in the whole country", "Only holiday schools for the summer months in each region"], "answer": 1, "explain": "The Incheon Declaration set this aim for 2030.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "Why did the 2015 SDGs go further than the MDGs?", "options": ["They are only for poor countries in the world and nobody else", "They cover only education and nothing else at all in the world", "They are universal and cover broader issues like climate and inequality", "They ended all aid to the poorest countries across the world"], "answer": 2, "explain": "The SDGs apply to all countries and cover more issues than the MDGs.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "What is the aim of Education for Sustainable Development (ESD)?", "options": ["To teach only environmental laws", "To close science classes", "To stop environmental studies", "To equip learners to act for a sustainable future"], "answer": 3, "explain": "ESD helps learners understand sustainability and take action.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "What does the UN Special Rapporteur on the right to education do?", "options": ["Reports on the right to education worldwide", "Runs a school", "Referees football matches", "Manages a bank"], "answer": 0, "explain": "The UN Special Rapporteur reports on the right to education worldwide.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 9, "q": "What is brain development in the early years mainly shaped by?", "options": ["The colour of toys", "Experiences and relationships", "The number of school buses", "The price of school uniforms"], "answer": 1, "explain": "Relationships and experiences shape brain development in early life.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "Why do early years policies need cross-sector coordination?", "options": ["Children need only education in the classroom to learn well", "Children need only health care and nothing else to thrive", "Children's needs span health, care, nutrition and learning", "Children need nothing from any service or family at all"], "answer": 2, "explain": "Coordination helps meet children's needs across different services.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is an early childhood development index?", "options": ["A measure of school buildings", "A count of teachers' pets", "A list of holidays", "A measure of children's readiness in key areas"], "answer": 3, "explain": "Development indices track children's readiness across domains.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is language-rich interaction in the early years?", "options": ["Conversation that builds vocabulary and understanding", "Silent play with toys and no talking at all in the room", "Constant shouting at children all day long in the house", "Only watching television for hours and hours every day"], "answer": 0, "explain": "Language-rich interaction supports later reading and learning.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is early identification and referral?", "options": ["Ignoring children who need help at school and at home", "Finding children who need help and linking them to services", "Labelling children permanently with a fixed and harsh label", "Sending children home whenever they show that they need help"], "answer": 1, "explain": "Referral systems connect children to the right support early.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "What is family support in early childhood?", "options": ["Taking children away from their families and their homes", "Banning family visits to the school for the whole year", "Help for families to care for and educate young children", "Ignoring families completely in every decision about school"], "answer": 2, "explain": "Family support strengthens home learning and wellbeing.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "How is child health linked to learning?", "options": ["Health has no link to learning at all in any school", "Sick children learn faster than healthy ones in class", "Health only matters once the school day has ended for good", "Good health supports attendance, attention and development"], "answer": 3, "explain": "Child health is closely linked to learning outcomes.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "What is lifelong literacy?", "options": ["Continuing to build reading and writing skills throughout life", "Reading only in childhood and then never again after that", "Reading only in school and never at home or outside", "Reading only for jobs and nothing else in your whole life"], "answer": 0, "explain": "Lifelong literacy means continuing to read and write across life.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "What are reading for information skills?", "options": ["Reading only fiction", "Finding and using facts in texts", "Reading only poetry", "Reading without purpose"], "answer": 1, "explain": "Reading for information helps learners find facts for decisions.", "src": "UNESCO"}, {"ch": 10, "q": "What is the readability of a text?", "options": ["How heavy a book is", "How many pages a book has", "How easy a text is to read and understand", "How expensive a book is"], "answer": 2, "explain": "Readability depends on language, sentence length and vocabulary.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "What is a gender gap in literacy?", "options": ["Differences in height between girls and boys", "Differences in shoe size between girls and boys", "Differences in favourite colours between girls and boys", "Differences in reading skills between girls and boys"], "answer": 3, "explain": "Gender gaps in literacy vary by country and need targeted response.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 10, "q": "What is print access in low-resource settings?", "options": ["Access to printed materials for reading", "Banning printing", "Printing only money", "Printing only maps of the moon"], "answer": 0, "explain": "Print access helps learners in low-resource settings practise reading.", "src": "UNESCO"}, {"ch": 10, "q": "What is a mother-tongue literacy policy?", "options": ["A policy to ban mother tongues in every school across the country", "A policy to teach early reading in the language children speak", "A policy to teach only English in all classes in every school", "A policy to teach only sign language in all classes from age six"], "answer": 1, "explain": "Mother-tongue literacy supports early reading and identity.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "What is literacy for development?", "options": ["Literacy with no purpose at all in daily life or at work", "Literacy only for tourists who visit the country each year", "Using literacy to improve health, jobs and community life", "Literacy that ends once every child turns ten years old"], "answer": 2, "explain": "Literacy supports development across health, work and civic life.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "What is a reading-for-pleasure programme?", "options": ["A programme that bans storybooks", "A programme that only tests spelling", "A programme that stops reading after age ten", "A programme that encourages children to read for enjoyment"], "answer": 3, "explain": "Reading for pleasure builds motivation and habits that support lifelong literacy.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 11, "q": "What does inclusion mean as a human rights principle in education?", "options": ["Every learner belongs and participates", "Some learners are separated", "Learners are kept apart by ability", "Learners are excluded by design"], "answer": 0, "explain": "Inclusion is a human rights principle that ensures belonging and participation.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is inclusive teacher education?", "options": ["Training teachers to teach only top learners", "Training teachers to teach all learners", "Training teachers to avoid disabled learners", "Training teachers in sport only"], "answer": 1, "explain": "Inclusive teacher training prepares teachers for diverse classrooms.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What does individual support mean in an inclusive school?", "options": ["Support for the whole school only", "Support only for the best learners", "Tailored help for a learner's specific needs", "No support at all"], "answer": 2, "explain": "Individual support adapts help to each learner.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is disability inclusion in curricula?", "options": ["Excluding disability from every single lesson taught in class", "Teaching disability as a punishment for pupils who misbehave", "Teaching disability only in sport and games class each week", "Including disability as part of learning about diversity"], "answer": 3, "explain": "Disability inclusion in curricula promotes respect and understanding.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is participatory assessment for inclusion?", "options": ["Involving learners in judging their own progress", "Assessing learners in secret without telling them", "Ignoring learners' views about their own work", "Assessing learners only by how tall they are"], "answer": 0, "explain": "Participatory assessment builds self-awareness and inclusion.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "What is inclusive recruitment of teachers?", "options": ["Hiring only one group", "Hiring teachers from diverse groups", "Refusing all applicants", "Hiring by family ties only"], "answer": 1, "explain": "Inclusive recruitment helps schools reflect the communities they serve.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 11, "q": "What is disability-inclusive data?", "options": ["Data that hides disability completely from the public eye", "Data about disability only in sport and games each season", "Data that includes people with disabilities and their needs", "Data that is never collected in any school or district"], "answer": 2, "explain": "Inclusive data helps policies respond to disability.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "Why is the right to education called a multiplier right?", "options": ["Because it multiplies the price of books", "Because it doubles school fees", "Because it only applies to teachers", "Because it helps people access other rights"], "answer": 3, "explain": "Education helps people access health, work, political participation and other rights.", "src": "UN Special Rapporteur on the Right to Education"}]};
